// Curved C-like bracket/clip with two concentric ribs and a long tapered slot
// One connected solid, arc-shaped body, thicker end block + tab, tapered thin end
// Bounding box target: ~0.3 x 0.1 x 0.4 mm (X x Y x Z), elongated along Z

$fn = 128;

// ---------------- Parameters (mm) ----------------
bbox_x = 0.30;
bbox_y = 0.10;
bbox_z = 0.40;

// Arc in XZ plane, extruded along Y
arc_outer_R = 0.155;
arc_inner_R = 0.105;
arc_angle_deg = 210;

part_thickness_y = 0.06;
rib_thickness_radial = 0.020;

// Slot (tapered along arc)
slot_width_start = 0.020;   // wider near thick end
slot_width_end   = 0.010;   // narrower near thin end

// End features
end_block_len = 0.055;      // tangential length
end_block_height_z = 0.085; // radial height (Z)
tab_d = 0.012;
tab_len = 0.016;

// Thin end taper
thin_end_taper_len = 0.070;
thin_end_min_radial = 0.012;

// Small overlap for watertight unions/differences
// NOTE: model is sub-mm; keep overlap small but non-zero
overlap = 0.002;

// ---------------- Helpers ----------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module bbox_limit() {
  cube([bbox_x, bbox_y, bbox_z], center=true);
}

// 2D ring sector (in XZ plane), then linear_extrude along Y
module ring_sector_2d(r_in, r_out, ang_deg) {
  intersection() {
    difference() {
      circle(r=r_out);
      circle(r=r_in);
    }
    // sector wedge centered on +X axis
    polygon(points=[
      [0,0],
      [r_out*2*cos(-ang_deg/2), r_out*2*sin(-ang_deg/2)],
      [r_out*2*cos( ang_deg/2), r_out*2*sin( ang_deg/2)]
    ]);
  }
}

module ring_sector_3d(r_in, r_out, ang_deg, y_th) {
  linear_extrude(height=y_th, center=true)
    ring_sector_2d(r_in, r_out, ang_deg);
}

// Place a child at a given angle on the mid-radius, oriented tangentially.
// Arc lies in XZ around Y axis.
module at_angle(ang_deg, r_mid) {
  rotate([0, -ang_deg, 0])
    translate([r_mid, 0, 0])
      rotate([0, 90, 0])
        children();
}

// ---------------- Main geometry ----------------
module ribs_base() {
  // Two concentric ribs: outer and inner
  union() {
    ring_sector_3d(arc_outer_R - rib_thickness_radial, arc_outer_R, arc_angle_deg, part_thickness_y);
    ring_sector_3d(arc_inner_R, arc_inner_R + rib_thickness_radial, arc_angle_deg, part_thickness_y);
  }
}

// Tapered slot cutter: hull of two tangential boxes at arc ends
// FIX: ensure cutter actually intersects the ribs (radially) and stays centered in Z.
module tapered_slot_cutter() {
  r_mid = (arc_outer_R + arc_inner_R)/2;

  // Tangential cutter length: long enough to span across the rib thickness along tangent
  slot_len = clamp(bbox_z*0.95, 0.22, 0.38);

  // Gap between ribs (radial)
  gap_rad = (arc_outer_R - rib_thickness_radial) - (arc_inner_R + rib_thickness_radial);

  // Make cutter radial height exceed the gap so it fully opens the slot
  slot_radial_h_start = max(gap_rad + 2*overlap, slot_width_start + 2*overlap);
  slot_radial_h_end   = max(gap_rad + 2*overlap, slot_width_end   + 2*overlap);

  hull() {
    // thick end: wider
    at_angle( arc_angle_deg/2 - 1, r_mid)
      cube([slot_len, part_thickness_y + 4*overlap, slot_radial_h_start], center=true);

    // thin end: narrower
    at_angle(-arc_angle_deg/2 + 1, r_mid)
      cube([slot_len, part_thickness_y + 4*overlap, slot_radial_h_end], center=true);
  }
}

// Thick end block at +end of arc, connected by overlap into ribs
// FIX: place block so its inner tangential face overlaps the rib end (no floating).
module thick_end_block() {
  r_mid = (arc_outer_R + arc_inner_R)/2;

  at_angle( arc_angle_deg/2, r_mid) {
    // Ensure overlap with rib end: inner face at x = -end_block_len/2 + overlap
    translate([end_block_len/2 - overlap, 0, 0])
      cube([end_block_len, part_thickness_y, end_block_height_z], center=true);
  }
}

// Small protruding tab/peg on thick end block
// FIX: attach to the outer tangential face of the end block with overlap.
module end_tab_peg() {
  r_mid = (arc_outer_R + arc_inner_R)/2;

  at_angle( arc_angle_deg/2, r_mid) {
    // Outer face of end block is at x = (end_block_len/2 - overlap) + end_block_len/2 = end_block_len - overlap
    // Place peg so it overlaps that face by 'overlap'
    translate([end_block_len - overlap + tab_len/2 - overlap, 0, 0])
      rotate([0, 90, 0])
        cylinder(d=tab_d, h=tab_len, center=true);
  }
}

// Thin tapered end at -end of arc: a wedge that blends into ribs
// FIX: ensure it overlaps the rib end and is part of the same connected component.
module thin_end_taper() {
  r_mid = (arc_outer_R + arc_inner_R)/2;

  at_angle(-arc_angle_deg/2, r_mid) {
    // Build a tangential wedge that starts overlapping the rib end and extends outward.
    // Use a small but non-zero base length so it unions robustly with the rib end.
    base_len = max(overlap*8, 0.010);

    hull() {
      // base: overlaps ribs at the arc end (extends slightly into the rib end by overlap)
      translate([base_len/2 - overlap, 0, 0])
        cube([base_len, part_thickness_y, rib_thickness_radial*2 + overlap*2], center=true);

      // tip: thinner, moved along +X (tangent direction) by taper length
      translate([thin_end_taper_len + base_len/2 - overlap, 0, 0])
        cube([base_len, part_thickness_y, thin_end_min_radial], center=true);
    }
  }
}

// Assemble connected solid
module clip_body() {
  union() {
    difference() {
      ribs_base();
      tapered_slot_cutter();
    }
    thick_end_block();
    end_tab_peg();
    thin_end_taper();
  }
}

// Final: clip to bounding box (keeps within requested overall size)
intersection() {
  clip_body();
  bbox_limit();
}

// Thin circular plate with central round through-hole and 8 hex through-holes on a bolt circle
// Units: meters (values are small; scale up if your viewer expects mm)

$fn = 180;

// Parameters
plate_d = 0.03;                 // outer diameter
plate_t = 0.0008;               // thickness (increased so it renders reliably)
center_hole_d = 0.015;          // central circular through-hole diameter
bolt_circle_d = 0.022;          // bolt circle diameter for the 8 hex holes
hex_flat_to_flat = 0.004;       // hex hole size (flat-to-flat)
hex_rotation_deg = 0;           // rotation of hex holes
hole_count = 8;                 // number of hex holes
eps = 1e-5;                     // robust boolean epsilon

// Helpers
function hex_R_from_F(F) = F / sqrt(3); // circumradius from flat-to-flat

module outer_disk() {
    cylinder(r = plate_d/2, h = plate_t, center = true);
}

module center_through_hole() {
    cylinder(r = center_hole_d/2, h = plate_t + 2*eps, center = true);
}

module hex_through_hole() {
    rotate([0,0,hex_rotation_deg])
        cylinder(r = hex_R_from_F(hex_flat_to_flat), h = plate_t + 2*eps, center = true, $fn = 6);
}

module hex_holes_on_bolt_circle() {
    for (i = [0:hole_count-1]) {
        rotate([0,0, i*360/hole_count])
            translate([bolt_circle_d/2, 0, 0])
                hex_through_hole();
    }
}

difference() {
    outer_disk();
    center_through_hole();
    hex_holes_on_bolt_circle();
}

// L-shaped prismatic bracket with an open rectangular recess (step)
// Single connected solid, constant thickness (plate-like)

$fn = 64;

// Target overall footprint (approx): 0.1 x 0.2 mm
L = 0.2;          // overall length (X)
W = 0.1;          // overall width  (Y)
T = 0.03;         // thickness (Z) - cannot be 0 for a solid

// L geometry
pad_L    = 0.12;  // main block length
pad_W    = W;     // main block spans full width
flange_L = L - pad_L; // flange length
flange_W = 0.05;  // flange width (narrow arm)

// Recess (open step) carved from the flange side to create the L profile
recess_L = flange_L;          // recess runs along the flange length
recess_W = W - flange_W;      // removes the "missing" width to leave a narrow arm
overlap  = 0.002;

// Optional mounting holes (kept small)
hole_r = 0.004;
hole_edge_margin = 0.012;

module l_bracket_solid() {
  // Start from full bounding rectangle, then remove the step to form an L
  difference() {
    cube([L, W, T], center=true);

    // Step cutout: remove the upper portion of the flange region, leaving a narrow arm
    // Flange region in X: [pad_L/2 .. L/2]
    // Remove in Y: top band of width recess_W (i.e., everything except the narrow flange_W at bottom)
    translate([ (pad_L/2 + L/2)/2,  (W - recess_W)/2, 0 ])
      cube([recess_L + overlap, recess_W + overlap, T + 2*overlap], center=true);

    // Holes on the main pad only (avoid cutting into the flange)
    for (sy = [-1, 1]) {
      translate([ -L/2 + hole_edge_margin, sy*(W/2 - hole_edge_margin), 0 ])
        cylinder(r=hole_r, h=T + 2*overlap, center=true);
    }
  }
}

l_bracket_solid();

// Flat key-like plate: rectangular shank + circular bow with concentric circular hole
// + bit with stepped rectangular notches and ONE triangular tooth.
// Bounding box target: 0.2 x 0.1 x ~0 mm (use very thin T).

$fn = 128;

// --- Parameters (mm) ---
L = 0.20;          // overall length (X)
W = 0.10;          // overall max width (Y) (kept as an upper bound)
T = 0.001;         // near-zero thickness (Z)

shank_L = 0.12;
shank_W = 0.03;

bow_OD = 0.08;
bow_ID = 0.04;

bit_L = 0.04;
bit_W = 0.04;

// Notches (cut from top edge of bit)
notch1_L = 0.012;
notch1_depth = 0.010;

notch2_L = 0.010;
notch2_depth = 0.016;

// Single triangular tooth (adds below bottom edge of bit)
tooth_L = 0.012;
tooth_H = 0.012;
tooth_offset_from_tip = 0.010;

eps = 0.0005;      // small overlap for robust booleans

// --- Derived placement (all formula-based) ---
bow_cx = -L/2 + bow_OD/2;          // bow centered so its leftmost touches -L/2
bit_tip_x =  L/2;                  // rightmost tip at +L/2
bit_cx = bit_tip_x - bit_L/2;      // bit centered so it ends at +L/2

// Shank spans from bow rightmost to bit leftmost
shank_left_x  = bow_cx + bow_OD/2;
shank_right_x = bit_cx - bit_L/2;
shank_L_eff   = shank_right_x - shank_left_x;
shank_cx      = (shank_left_x + shank_right_x)/2;

// --- 2D profiles ---
module bow_2d() {
  difference() {
    circle(d = bow_OD);
    circle(d = bow_ID);
  }
}

module shank_2d() {
  square([shank_L_eff, shank_W], center=true);
}

module bit_base_2d() {
  square([bit_L, bit_W], center=true);
}

module tooth_2d() {
  // Right triangle protruding downward from the bit's bottom edge
  // Base along X, height along -Y.
  polygon(points=[
    [0, 0],
    [tooth_L, 0],
    [0, -tooth_H]
  ]);
}

module key_2d() {
  difference() {
    union() {
      // Bow ring
      translate([bow_cx, 0]) bow_2d();

      // Shank (connected between bow and bit)
      translate([shank_cx, 0]) shank_2d();

      // Bit base
      translate([bit_cx, 0]) bit_base_2d();

      // Single triangular tooth on bottom edge of bit
      // Place so its top edge sits on bit bottom (y = -bit_W/2)
      // and its right end is offset from the tip.
      translate([
        bit_tip_x - tooth_offset_from_tip - tooth_L,
        -bit_W/2
      ]) tooth_2d();
    }

    // Stepped notches cut from the TOP edge of the bit (y = +bit_W/2)
    // Notch 1 at the tip
    translate([
      bit_tip_x - notch1_L/2,
      bit_W/2 - notch1_depth/2
    ])
      square([notch1_L, notch1_depth], center=true);

    // Notch 2 just behind notch 1
    translate([
      bit_tip_x - notch1_L - notch2_L/2,
      bit_W/2 - notch2_depth/2
    ])
      square([notch2_L, notch2_depth], center=true);
  }
}

// --- 3D (thin plate) ---
linear_extrude(height=T, center=true, convexity=10)
  key_2d();

// Thin rectangular plate with small triangular recessed corner reliefs (top face)

// Parameters (mm)
plate_L = 0.10;          // length
plate_W = 0.05;          // width
plate_T = 0.01;          // thickness
corner_cut_leg = 0.006;  // triangle leg length along edges
corner_cut_depth = 0.003;// recess depth into top face

eps = 0.0005;

// Main Plate Body
module plate_main_body() {
    cube([plate_L, plate_W, plate_T], center=true);
}

// One corner triangular recess (cut into top face)
module corner_relief_cutout(sx, sy) {
    // sx, sy are +/-1 selecting which corner
    x0 = sx * plate_L/2;
    y0 = sy * plate_W/2;

    // Create a local triangle at origin, then move it to the chosen corner.
    // This avoids relying on polygon points far from the origin (which can
    // cause fragile/empty differences at tiny scales).
    translate([x0, y0, plate_T/2 - corner_cut_depth])
        linear_extrude(height=corner_cut_depth + eps, center=false, convexity=10)
            polygon(points=[
                [0, 0],
                [-sx*corner_cut_leg, 0],
                [0, -sy*corner_cut_leg]
            ]);
}

// Final geometry (single connected solid)
difference() {
    plate_main_body();

    // Four corner recesses (top face only)
    corner_relief_cutout( 1,  1);
    corner_relief_cutout(-1,  1);
    corner_relief_cutout(-1, -1);
    corner_relief_cutout( 1, -1);
}

// Vented/stiffened panel: perimeter frame + 3x2 rounded-rect cutouts + two diagonal ribs/webs
// Fixed: diagonal ribs are now guaranteed to be visible and connected (not removed by cutouts),
// by subtracting cutouts first and then adding ribs on top (with slight Z overlap).
// All dimensions in mm.

$fn = 64;

// Overall bounding box target (approx): 0.20 x 0.10 x thin
L = 0.20;
W = 0.10;
T = 0.01;

// Frame
frame_w  = 0.012;
corner_r = 0.004;

// Cutouts (3x2 grid)
cut_cols = 3;
cut_rows = 2;
gap_x    = 0.008;
gap_y    = 0.010;
cut_r    = 0.006;

// Ribs/webs
rib_w         = 0.010;   // slightly wider so they read in orthographic views
rib_angle_deg = 35;

// Robustness / connectivity
overlap = 0.001;         // small overlap for boolean robustness
z_fuse  = 0.002;         // extra rib height to ensure union + visibility

// ---------- helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module rounded_rect_2d(sz=[10,10], r=1) {
  rr = clamp(r, 0, min(sz[0], sz[1]) / 2);
  offset(r=rr)
    square([max(0, sz[0]-2*rr), max(0, sz[1]-2*rr)], center=true);
}

module rounded_box(sz=[10,10,1], r=1) {
  linear_extrude(height=sz[2], center=true)
    rounded_rect_2d([sz[0], sz[1]], r);
}

module plate_outer() {
  rounded_box([L, W, T], corner_r);
}

// Inner window for clipping ribs (keeps them inside the frame)
inner_L = L - 2*frame_w;
inner_W = W - 2*frame_w;

module inner_window_box(h=T) {
  rounded_box([inner_L, inner_W, h], max(0, corner_r - frame_w/2));
}

// Compute cutout size to fit inside inner area with requested gaps
cut_w = (inner_L - (cut_cols-1)*gap_x) / cut_cols;
cut_h = (inner_W - (cut_rows-1)*gap_y) / cut_rows;

module cutout_at(ix, iy) {
  // ix: 0..cut_cols-1, iy: 0..cut_rows-1 (top to bottom)
  x0 = -inner_L/2 + cut_w/2;
  y0 =  inner_W/2 - cut_h/2;

  x = x0 + ix*(cut_w + gap_x);
  y = y0 - iy*(cut_h + gap_y);

  translate([x, y, 0])
    rounded_box([cut_w, cut_h, T + 4*overlap],
                clamp(cut_r, 0, min(cut_w, cut_h)/2 - 1e-6));
}

module cutouts_union() {
  union() {
    for (ix = [0:cut_cols-1])
      for (iy = [0:cut_rows-1])
        cutout_at(ix, iy);
  }
}

module rib_bar(len, h) {
  cube([len, rib_w, h], center=true);
}

module diagonal_ribs() {
  // Long enough to span the inner window; then clipped to inner window so ribs connect to frame.
  rib_len = sqrt(inner_L*inner_L + inner_W*inner_W) + 2*frame_w;

  // Make ribs slightly thicker in Z and slightly offset so they fuse with the plate.
  rib_h = T + z_fuse;
  rib_z = 0; // centered; extra height ensures overlap with plate

  intersection() {
    union() {
      translate([0,0,rib_z]) rotate([0,0, rib_angle_deg]) rib_bar(rib_len, rib_h);
      translate([0,0,rib_z]) rotate([0,0,-rib_angle_deg]) rib_bar(rib_len, rib_h);
    }
    // Clip to inner window (expanded slightly for guaranteed connection)
    rounded_box([inner_L + 2*overlap, inner_W + 2*overlap, rib_h + 2*overlap],
                max(0, corner_r - frame_w/2));
  }
}

module base_panel_with_openings() {
  // Single flat plate with six openings (keeps the "vented panel" look).
  difference() {
    plate_outer();
    cutouts_union();
  }
}

union() {
  // Base vented plate
  base_panel_with_openings();

  // Add diagonal ribs AFTER cutouts so they remain visible and create the stepped/angled transitions.
  // They are clipped to the inner window so they don't overwrite the perimeter frame.
  diagonal_ribs();
}

// Long prismatic stepped bar made from fused rectangular blocks (no holes/cutouts)
// Elongated along X, constant thickness Z, stepped width Y along length

L = 0.20;      // total length (X)
T = 0.20;      // thickness (Z)
W_max = 0.20;  // maximum width (Y)

// Segment lengths (sum to L)
seg_L1 = 0.04;
seg_L2 = 0.04;
seg_L3 = 0.04;
seg_L4 = 0.04;
seg_L5 = 0.04;

// Segment widths (Y) - stepped shoulders along length (fused end-to-end)
W1 = 0.20;
W2 = 0.14;
W3 = 0.20;
W4 = 0.14;
W5 = 0.20;

eps = 0.002; // overlap to guarantee connectivity and avoid coincident faces

module seg(len, wid, x_start_from_left) {
    // x_start_from_left measured from left end (0..L)
    translate([-L/2 + x_start_from_left + len/2, 0, 0])
        cube([len + eps, wid, T], center=true);
}

union() {
    seg(seg_L1, W1, 0);
    seg(seg_L2, W2, seg_L1);
    seg(seg_L3, W3, seg_L1 + seg_L2);
    seg(seg_L4, W4, seg_L1 + seg_L2 + seg_L3);
    seg(seg_L5, W5, seg_L1 + seg_L2 + seg_L3 + seg_L4);
}

// Rectangular tray-like housing with recessed panel + long slot
// Structural fixes applied:
// - Slot is a CLEAR through-opening: cut from above top down into the cavity (not just a shallow groove)
// - All translate() values are derived from part dimensions (no arbitrary offsets)
// - Single connected solid: outer tapered body + flange are unioned; all features are subtractive
// - Robust booleans via eps overlaps (scaled to tiny mm dimensions)

$fn = 48;

// --- Target overall size (elongated along X) ---
L = 0.10;   // mm (bounding box X)
W = 0.04;   // mm
H = 0.03;   // mm

// --- Construction parameters ---
wall_t = 0.004;
base_t = 0.004;

taper_inset_per_side = 0.004;   // taper from bottom to top (per side)

flange_overhang = 0.003;
flange_t = 0.003;

recess_depth = 0.008;
recess_margin_L = 0.010;
recess_margin_W = 0.008;

slot_L = 0.070;
slot_W = 0.006;

corner_chamfer = 0.002;

// Robust boolean overlap (relative to tiny model size)
eps = 0.001;   // mm

// ---------- Helpers ----------
module rect2d(x, y) {
  polygon(points=[
    [-x/2, -y/2],
    [ x/2, -y/2],
    [ x/2,  y/2],
    [-x/2,  y/2]
  ]);
}

module tapered_solid(outerL, outerW, height, taper) {
  // Bottom is larger, top is smaller -> tapered side walls
  hull() {
    translate([0,0,-height/2]) linear_extrude(height=eps) rect2d(outerL, outerW);
    translate([0,0, height/2]) linear_extrude(height=eps) rect2d(outerL-2*taper, outerW-2*taper);
  }
}

module tapered_void(innerL, innerW, taper, z0, z1) {
  // Void that follows taper between absolute Z extents z0..z1
  hull() {
    translate([0,0,z0]) linear_extrude(height=eps) rect2d(innerL, innerW);
    translate([0,0,z1]) linear_extrude(height=eps) rect2d(innerL-2*taper, innerW-2*taper);
  }
}

module top_flange() {
  // Slight overhang, connected to body by a small overlap (eps)
  // Flange sits on the top face of the body.
  translate([0,0, (H/2) + (flange_t/2) - (eps/2)])
    cube([L + 2*flange_overhang, W + 2*flange_overhang, flange_t + eps], center=true);
}

module corner_chamfer_wedge(xsgn, ysgn) {
  // 45° corner chamfer through full height (+flange + eps)
  total_h = H + flange_t + 4*eps;
  translate([xsgn*(L/2 - corner_chamfer/2), ysgn*(W/2 - corner_chamfer/2), (flange_t/2)])
    rotate([0,0,45])
      cube([corner_chamfer, corner_chamfer, total_h], center=true);
}

// ---------- Model ----------
module model_core() {
  // Outer tapered body + top flange (single connected solid)
  union() {
    tapered_solid(L, W, H, taper_inset_per_side);
    top_flange();
  }
}

module inner_cavity_cut() {
  // Open-top cavity: remove from just above base to above top to guarantee opening
  innerL = L - 2*wall_t;
  innerW = W - 2*wall_t;

  // Keep base thickness; open all the way through the top (including flange)
  z0 = (-H/2) + base_t;                 // cavity starts above base
  z1 = ( H/2) + flange_t + 3*eps;       // ensure it opens through flange

  tapered_void(innerL, innerW, taper_inset_per_side, z0, z1);
}

module recessed_panel_cut() {
  // Recess is cut DOWN from the top face (Z+), centered
  recessL = L - 2*recess_margin_L;
  recessW = W - 2*recess_margin_W;

  // Cut starts slightly above the top of the flange and goes down recess_depth
  z_top = (H/2) + flange_t + 2*eps;
  z_bot = z_top - recess_depth;

  translate([0,0,(z_top+z_bot)/2])
    cube([recessL, recessW, (z_top - z_bot) + 2*eps], center=true);
}

module slot_through_cut() {
  // Long narrow slot cut within the recess.
  // Cut THROUGH the recessed panel and into the cavity so it reads as an opening.
  // Start above top and extend below the cavity start plane (slight overlap).
  z_top = (H/2) + flange_t + 3*eps;
  z_bot = (-H/2) + base_t - 2*eps;  // into cavity region, but not through base

  translate([0,0,(z_top+z_bot)/2])
    cube([slot_L, slot_W, (z_top - z_bot) + 2*eps], center=true);
