difference() {
  model_core();

  // Tray cavity
  inner_cavity_cut();

  // Recess on the top panel area
  recessed_panel_cut();

  // Visible opening feature: slot through the recessed panel into the cavity
  slot_through_cut();

  // Corner chamfers
  corner_chamfer_wedge( 1,  1);
  corner_chamfer_wedge(-1,  1);
  corner_chamfer_wedge( 1, -1);
  corner_chamfer_wedge(-1, -1);
