// U-shaped clamp/bracket with semicircular saddle cutout, forked prongs, chamfered outer facets, and end through-holes.
// All translations are derived from dimensions; model is one connected solid.

$fn = 96;

// -------------------- Parameters (mm) --------------------
body_L = 0.060;   // main body length (X)
body_W = 0.030;   // main body width  (Y)
body_H = 0.050;   // main body height (Z)

fork_len = 0.020; // prong extension length (X)
prong_W  = 0.010; // each prong width (Y)
slot_W   = 0.010; // gap between prongs (Y)
prong_H  = 0.030; // prong height (Z)

cutout_R = 0.018; // saddle radius (semi-cylindrical cut)
cutout_z = 0.026; // saddle center height from bottom (Z)

hole_d = 0.003;        // through-hole diameter
hole_end_offset = 0.008; // from each end along X

chamfer = 0.003; // heavy facet amount
overlap = 0.001; // boolean overlap

// -------------------- Derived --------------------
total_L = body_L + fork_len;

prong_center_y = (slot_W/2 + prong_W/2);
prong_center_x = body_L/2 + fork_len/2 - overlap;
prong_center_z = -body_H/2 + prong_H/2;

slot_center_x  = prong_center_x;
slot_center_z  = prong_center_z;

hole1_x = -body_L/2 + hole_end_offset;
hole2_x =  body_L/2 - hole_end_offset;

// -------------------- Helpers --------------------
module chamfered_box(size=[10,10,10], c=1) {
    // Faceted/chamfered look by subtracting 45° wedges from a box.
    // Works best with relatively large c.
    sx=size[0]; sy=size[1]; sz=size[2];
    difference() {
        cube([sx,sy,sz], center=true);

        // 12 edge chamfers (approx): subtract long rotated boxes along edges
        // Along X edges (vary Y/Z)
        for (yy=[-1,1], zz=[-1,1])
            translate([0, yy*(sy/2 - c/2), zz*(sz/2 - c/2)])
                rotate([45,0,0])
                    cube([sx+2*overlap, c*2, c*2], center=true);

        // Along Y edges (vary X/Z)
        for (xx=[-1,1], zz=[-1,1])
            translate([xx*(sx/2 - c/2), 0, zz*(sz/2 - c/2)])
                rotate([0,45,0])
                    cube([c*2, sy+2*overlap, c*2], center=true);

        // Along Z edges (vary X/Y)
        for (xx=[-1,1], yy=[-1,1])
            translate([xx*(sx/2 - c/2), yy*(sy/2 - c/2), 0])
                rotate([0,0,45])
                    cube([c*2, c*2, sz+2*overlap], center=true);
    }
}

module main_body() {
    chamfered_box([body_L, body_W, body_H], chamfer);
}

module prong_block() {
    // Prong itself is chamfered for faceted look
    chamfered_box([fork_len, prong_W, prong_H], chamfer);
}

module fork_prongs() {
    union() {
        translate([prong_center_x,  prong_center_y, prong_center_z]) prong_block();
        translate([prong_center_x, -prong_center_y, prong_center_z]) prong_block();
    }
}

module fork_slot_cut() {
    translate([slot_center_x, 0, slot_center_z])
        cube([fork_len + 2*overlap, slot_W, prong_H + 2*overlap], center=true);
}

module saddle_cut() {
    // True semicircular internal cutout: subtract a cylinder and clip to half-space.
    // Cylinder axis along Y, so top view shows a circle/arc rather than polygon.
    translate([0, 0, -body_H/2 + cutout_z])
        rotate([90,0,0])
            intersection() {
                cylinder(r=cutout_R, h=body_W + 2*overlap, center=true);
                // keep only the upper half (Z >= center) to make a semicircular "U" saddle
                translate([0,0, cutout_R/2])
                    cube([2*cutout_R + 2*overlap, body_W + 4*overlap, cutout_R + 2*overlap], center=true);
            }
}

module end_holes() {
    // Through holes along Y (appear diamond-ish in some views when chamfered body is present)
    for (xx=[hole1_x, hole2_x])
        translate([xx, 0, 0])
            rotate([90,0,0])
                cylinder(d=hole_d, h=body_W + 2*overlap, center=true);
}

// -------------------- Final --------------------
difference() {
    union() {
        main_body();
        fork_prongs();
    }
    fork_slot_cut();
    saddle_cut();
    end_holes();
}

$fn = 96;

// Units: mm
thickness_z = 3.0;

body_w   = 22.0;
body_l   = 56.0;

flange_w = 30.0;
flange_l = 24.0;

hole_d = 4.0;
hole_edge_margin_x = 4.0;
hole_edge_margin_y = 4.0;

chamfer_len = 6.0;

feature_depth = 0.6;   // shallow recess
overlap = 0.2;

// Derived
total_l = body_l + flange_l;

// 2D outline (top view) with stepped flange and chamfered far end corners
module outline_2d() {
    // Coordinate system: Y along length, flange at +Y end
    // Body spans: y = [-total_l/2, +total_l/2 - flange_l]
    // Flange spans: y = [+total_l/2 - flange_l, +total_l/2]
    y_body_min = -total_l/2;
    y_body_max =  total_l/2 - flange_l;
    y_flange_min = y_body_max;
    y_flange_max = total_l/2;

    // Chamfer only on the far (non-flange) end: y_body_min corners
    polygon(points=[
        // start at left edge near flange, go CCW
        [-body_w/2, y_body_max],
        [-body_w/2, y_body_min + chamfer_len],
        [-body_w/2 + chamfer_len, y_body_min],
        [ body_w/2 - chamfer_len, y_body_min],
        [ body_w/2, y_body_min + chamfer_len],
        [ body_w/2, y_body_max],

        // step out to flange width
        [ flange_w/2, y_flange_min],
        [ flange_w/2, y_flange_max],
        [-flange_w/2, y_flange_max],
        [-flange_w/2, y_flange_min]
    ]);
}

// Through holes in flange (near its two top corners)
module flange_holes() {
    y_flange_center = total_l/2 - flange_l/2;
    y_hole = y_flange_center + (flange_l/2 - hole_edge_margin_y);

    for (sx = [-1, 1]) {
        translate([sx*(flange_w/2 - hole_edge_margin_x), y_hole, 0])
            cylinder(h=thickness_z + 2*overlap, d=hole_d, center=true);
    }
}

// Shallow V/arrow recess on both broad faces (top and bottom)
module v_recess(zsign=1) {
    // Place on body area, slightly toward the middle
    y0 = -total_l/2 + body_l*0.55;

    // 2D V shape
    v_w = body_w * 0.45;
    v_h = body_w * 0.22;
    v_th = body_w * 0.10;

    translate([0, y0, zsign*(thickness_z/2 - feature_depth/2)])
        linear_extrude(height=feature_depth + overlap, center=true)
            polygon(points=[
                [0,  v_h],
                [ v_w/2, -v_h],
                [ v_w/2 - v_th, -v_h],
                [0,  v_h*0.15],
                [-v_w/2 + v_th, -v_h],
                [-v_w/2, -v_h]
            ]);
}

module complete_model() {
    difference() {
        // Main plate as a single connected solid
        linear_extrude(height=thickness_z, center=true)
            outline_2d();

        // Holes
        flange_holes();

        // Face features (recessed on both sides)
        v_recess( 1);
        v_recess(-1);
    }
}

color("Silver") complete_model();

// Elongated ribbed shaft with polygonal end caps, DISCRETE radial tabs, and a single side nub
// Target bounding box ~0.9 x 0.3 x 1.4 mm (Z is long axis)

$fn = 72;

// -------------------- Parameters (mm) --------------------
bbox_x = 0.93;
bbox_y = 0.35;
bbox_z = 1.43;

mid_len = 0.95;
mid_r   = 0.12;

// Ribbed midsection (stacked thin discs)
fin_count = 14;
fin_thk   = 0.02;
fin_r     = 0.165;

// End caps
cap_len   = 0.24;
cap_sides = 8;
cap_r     = 0.175;

// Discrete radial tabs along length (not continuous fins)
tab_count  = 10;
tab_len    = 0.045;   // radial protrusion length
tab_w      = 0.05;    // tangential width
tab_h      = 0.03;    // axial height
tab_z_span = 0.80;    // span along Z where tabs appear
tab_ring_n = 4;       // number of tabs around circumference per Z station

// Single side nub near one end
nub_r          = 0.03;
nub_len        = 0.04;
nub_z_from_end = 0.18; // measured from very bottom end toward center

// NOTE: model is in mm; use small overlaps appropriate to this scale
overlap   = 0.006;   // robust unions at this tiny scale
chamfer_h = 0.02;

// -------------------- Helpers --------------------
module mid_cyl_body() {
  cylinder(h=mid_len, r=mid_r, center=true);
}

module fin_at(zpos) {
  translate([0,0,zpos])
    cylinder(h=fin_thk, r=fin_r, center=true);
}

module ribbed_fins_midsection() {
  union() {
    if (fin_count <= 1) {
      fin_at(0);
    } else {
      for (i = [0:fin_count-1]) {
        fin_at((-mid_len/2) + fin_thk/2 + i*(mid_len - fin_thk)/(fin_count-1));
      }
    }
  }
}

module end_cap(zsign=1) { // zsign: -1 bottom, +1 top
  // Centered so it overlaps slightly into the midsection for a watertight union
  translate([0,0, zsign*(mid_len/2 + cap_len/2 - overlap)])
    cylinder(h=cap_len, r=cap_r, center=true, $fn=cap_sides);
}

// One tab, oriented radially outward along +X, centered at given z
module tab_primitive(zpos) {
  // Inner face overlaps into shaft for connectivity
  translate([mid_r + tab_len/2 - overlap, 0, zpos])
    cube([tab_len + 2*overlap, tab_w, tab_h], center=true);
}

// Tabs: discrete protrusions (small blocks) at multiple Z positions and multiple angles
module radial_tabs_array() {
  union() {
    if (tab_count <= 1) {
      for (a = [0:tab_ring_n-1])
        rotate([0,0,a*360/tab_ring_n]) tab_primitive(0);
    } else {
      for (i = [0:tab_count-1]) {
        zpos = (-tab_z_span/2) + i*(tab_z_span)/(tab_count-1);
        for (a = [0:tab_ring_n-1])
          rotate([0,0,a*360/tab_ring_n]) tab_primitive(zpos);
      }
    }
  }
}

module single_side_nub() {
  // Whole part extents (with caps) along Z:
  // bottom end = -(mid_len/2 + cap_len)
  // top end    = +(mid_len/2 + cap_len)
  z_bottom = -(mid_len/2 + cap_len);
  z0 = z_bottom + nub_z_from_end;

  // Clamp nub Z so it stays on/near the bottom cap region and remains connected
  // (prevents accidental placement outside the solid if parameters change)
  z0c = min(z0, -(mid_len/2) + cap_len - overlap);
  z0cc = max(z0c, z_bottom + overlap);

  // Attach on +X side; overlap into shaft/cap region
  translate([mid_r + nub_len/2 - overlap, 0, z0cc])
    rotate([0,90,0])
      cylinder(h=nub_len + 2*overlap, r=nub_r, center=true, $fn=36);
}

module cap_chamfer_cutter(zpos, flip=false) {
  translate([0,0,zpos])
    rotate([flip ? 180 : 0, 0, 0])
      cylinder(h=chamfer_h, r1=cap_r + 0.02, r2=0, center=true, $fn=cap_sides*2);
}

module main_union_pre_chamfer() {
  union() {
    // Core
    mid_cyl_body();

    // Ribbed/grip texture (circumferential rings)
    ribbed_fins_midsection();

    // Enlarged polygonal end housings/collars
    end_cap(-1);
    end_cap( 1);

    // Discrete side tabs/protrusions along the length
    radial_tabs_array();

    // Single asymmetrical side nub near one end
    single_side_nub();
  }
}

module final_part() {
  difference() {
    main_union_pre_chamfer();

    // Bottom cap chamfer (outer end)
    cap_chamfer_cutter(
      zpos = (-(mid_len/2 + cap_len)) + chamfer_h/2,
      flip = true
    );

    // Top cap chamfer (outer end)
    cap_chamfer_cutter(
      zpos = ( (mid_len/2 + cap_len)) - chamfer_h/2,
      flip = false
    );
  }
}

// Output: one connected solid
final_part();

// Concave-sided mounting plate with 4 circular through-holes,
// central cylindrical boss, and a small hexagonal protrusion on top.
// Single connected solid with guaranteed overlaps.

$fn = 96;

// ---------- Parameters (mm) ----------
plate_xy = 0.07;
plate_t  = 0.015;

