module stem_main() {
    // Stem top should overlap into grip underside for a solid connection
    z_stem_center = -(grip_H/2 + stem_H/2 - overlap);

    translate([
        stem_offset_from_grip_center_L,
        stem_offset_from_grip_center_W,
        z_stem_center
