// Low-profile decorative plate/nameplate insert
// Bounding box target: L x W x H = 3.1 x 1.6 x 0.5 mm

// Parameters
L = 3.10;                 // overall length (X)
W = 1.60;                 // overall width  (Y)
H = 0.50;                 // overall height (Z)

corner_clip = 0.25;       // clipped corner amount (plan)
outer_chamfer = 0.06;     // top-edge chamfer height

panel_inset_x = 0.35;     // panel offset from left/right
panel_inset_y = 0.25;     // panel offset from top/bottom
panel_recess_depth = 0.10;// recess depth into top face

border_width = 0.18;      // raised border width around inner panel
panel_corner_cut = 0.12;  // angled cuts on panel corners (plan)

micro_texture_depth = 0.01; // subtle extra recess in inner panel

fillet_r = 0.03;          // small overall edge softening
eps = 0.01;

// ---------- Helpers (2D) ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module octo2d(len, wid, clip) {
  // Octagonal-like perimeter: rectangle with clipped corners
  polygon(points=[
    [ len/2 - clip,  wid/2],
    [-len/2 + clip,  wid/2],
    [-len/2,         wid/2 - clip],
    [-len/2,        -wid/2 + clip],
    [-len/2 + clip, -wid/2],
    [ len/2 - clip, -wid/2],
    [ len/2,        -wid/2 + clip],
    [ len/2,         wid/2 - clip]
  ]);
}

module panel2d(px, py, clip) {
  // Panel outline with clipped corners
  octo2d(px, py, clip);
}

// ---------- Main solids ----------
module base_plate() {
  // Single connected plate with clipped corners
  linear_extrude(height=H, center=true)
    octo2d(L, W, corner_clip);
}

module top_chamfer_cut() {
  // Remove a thin ring near the top to create a chamfered outer edge.
  // Uses 2D offset difference to form a wedge-like cut.
  translate([0,0, H/2 - outer_chamfer])
  linear_extrude(height=outer_chamfer + eps, center=false)
    difference() {
      octo2d(L, W, corner_clip);
      offset(delta=-outer_chamfer)
        octo2d(L, W, corner_clip);
    }
}

module recessed_panel_cut() {
  // Recessed panel region (with angled corner cuts) cut into TOP face only.
  px = L - 2*panel_inset_x;
  py = W - 2*panel_inset_y;

  // Keep panel valid
  px2 = clamp(px, 0.2, L - 2*outer_chamfer);
  py2 = clamp(py, 0.2, W - 2*outer_chamfer);

  // Panel corner clip should not exceed half-dim
  pclip = clamp(panel_corner_cut, 0, min(px2, py2)/2 - 0.001);

  translate([0,0, H/2 - panel_recess_depth])
  linear_extrude(height=panel_recess_depth + eps, center=false)
    panel2d(px2, py2, pclip);
}

module inner_texture_cut() {
  // Slight extra recess inside the raised border (top face only)
  px = L - 2*panel_inset_x - 2*border_width;
  py = W - 2*panel_inset_y - 2*border_width;

  px2 = clamp(px, 0.15, L);
  py2 = clamp(py, 0.15, W);

  // Slightly smaller corner clip for inner area
  pclip = clamp(panel_corner_cut - border_width*0.5, 0, min(px2, py2)/2 - 0.001);

  translate([0,0, H/2 - panel_recess_depth - micro_texture_depth])
  linear_extrude(height=micro_texture_depth + eps, center=false)
    panel2d(px2, py2, pclip);
}

module plate_with_top_details() {
  // Opposite face remains mostly flat: all detailing is cut from the top only.
  difference() {
    base_plate();
    top_chamfer_cut();
    recessed_panel_cut();
    inner_texture_cut();
  }
}

// Final output: small global fillet/softening while keeping one connected solid
minkowski() {
  plate_with_top_details();
  sphere(r=fillet_r, $fn=24);
}

// Long slender prismatic bar with socket head and tapered tip
// Units: mm

$fn = 64;

// Target overall bounding box (approx): X=0.03, Y=0.32, Z=0.07
bbox_x = 0.03;
bbox_y = 0.32;
bbox_z = 0.07;

// Main dimensions
head_L        = 0.06;
head_OD       = 0.03;   // collar OD (also approx max X)
head_H        = 0.07;   // collar height in Z (max Z)

shoulder_L    = 0.01;

shaft_L       = bbox_y - head_L - shoulder_L;  // ensures overall length matches bbox_y
shaft_W       = 0.022;  // X
shaft_H       = 0.045;  // Z

// Tip
tip_L         = 0.02;
tip_end_W     = 0.008;
tip_end_H     = 0.02;

// Socket
socket_depth  = 0.03;
socket_square = 0.016;
lead_in_L     = 0.006;

// Faceting/chamfers
facet_cut     = 0.002;
overlap       = 0.001;

// Derived positions along Y (object centered at origin)
y_min = -bbox_y/2;
y_max =  bbox_y/2;

y_head0     = y_min;
y_head1     = y_head0 + head_L;

y_shoulder0 = y_head1;
y_shoulder1 = y_shoulder0 + shoulder_L;

y_shaft0    = y_shoulder1;
y_shaft1    = y_shaft0 + shaft_L;

y_tip0      = y_max - tip_L;
y_tip1      = y_max;

// ---------- Helpers ----------
module hex_prism_y(flat_d, len_y, center_y=false) {
    // flat_d is across flats
    r = flat_d / sqrt(3); // circumradius for across-flats = sqrt(3)*r
    rotate([90,0,0])
        cylinder(r=r, h=len_y, center=center_y, $fn=6);
}

module collar_union() {
    // Cylindrical collar + hex flats, same length, unioned (connected)
    translate([0, (y_head0+y_head1)/2, 0]) {
        rotate([90,0,0]) cylinder(r=head_OD/2, h=head_L, center=true);
        // Slightly smaller hex so it reads as flats on the cylinder
        hex_prism_y(flat_d=head_OD*0.98, len_y=head_L, center_y=true);
    }
}

module shoulder_block() {
    // Transition block between collar and shaft (ensures connectivity)
    translate([0, (y_shoulder0+y_shoulder1)/2 - overlap/2, 0])
        cube([max(head_OD, shaft_W), shoulder_L + overlap, max(head_H, shaft_H)], center=true);
}

module shaft_block() {
    translate([0, (y_shaft0+y_shaft1)/2, 0])
        cube([shaft_W, shaft_L, shaft_H], center=true);
}

module tip_wedge() {
    // Tapered/chamfered tip made by hulling two rectangles (prismatic taper)
    hull() {
        translate([0, (y_tip0+y_tip0+overlap)/2, 0])
            cube([shaft_W, overlap, shaft_H], center=true);
        translate([0, (y_tip1+y_tip1-overlap)/2, 0])
            cube([tip_end_W, overlap, tip_end_H], center=true);
    }
}

module main_solid() {
    union() {
        collar_union();
        shoulder_block();
        shaft_block();
        // Blend into tip: overlap into shaft to guarantee connection
        translate([0, -overlap, 0]) tip_wedge();
    }
}

// Facet the shaft slightly (keep mostly rectangular)
module shaft_facets_subtractive() {
    // Cut small 45° bevels along the long edges by removing thin rotated prisms
    // Only applied over shaft+tip region to keep head mostly intact.
    y_mid = (y_shaft0 + y_tip1)/2;
    y_len = (y_tip1 - y_shaft0) + 2*overlap;

    for (sx = [-1, 1], sz = [-1, 1]) {
        translate([sx*(shaft_W/2), y_mid, sz*(shaft_H/2)])
            rotate([0,45,0])
                cube([facet_cut*4, y_len, facet_cut*4], center=true);
    }
}

// Socket cut: recessed square/diamond opening into the collar end
module socket_cut() {
    // Square rotated 45° around Y to appear diamond in XZ in end view
    // Cut starts at y_head0 and goes inward socket_depth
    translate([0, y_head0 + socket_depth/2 + overlap, 0])
        rotate([0,45,0])
            cube([socket_square, socket_depth + 2*overlap, socket_square], center=true);

    // Lead-in chamfer at the mouth
    translate([0, y_head0 + lead_in_L/2 + overlap, 0])
        rotate([90,0,0])
            cylinder(r1=socket_square*0.85, r2=socket_square*0.55, h=lead_in_L + 2*overlap, center=true);
}

// ---------- Final ----------
difference() {
    // Ensure one connected solid
    main_solid();

    // Facets (subtractive)
    shaft_facets_subtractive();

    // Recessed socket
    socket_cut();
}

// Thin plate with rounded outer corners + 4 rotated polygon cutouts (through-holes)
// Units: mm

$fn = 64;

// Parameters (match ~0.2 x 0.1 x thin)
plate_L = 0.20;
plate_W = 0.10;
plate_T = 0.01;

corner_R = 0.008;          // outer corner radius
cutout_sides = 6;          // polygonal opening (hex-like)
cutout_flat_d = 0.012;     // across-flats size
cutout_angle_deg = 30;     // rotate cutouts relative to edges
cutout_edge_offset_x = 0.018;
cutout_edge_offset_y = 0.016;

overlap = 0.002;

// Rounded rectangle plate (true rounded outer corners)
module rounded_plate(L, W, T, R) {
    // Ensure valid radius
    r = min(R, min(L, W)/2 - 1e-6);

    linear_extrude(height=T, center=true)
        offset(r=r)
            square([L - 2*r, W - 2*r], center=true);
}

// Regular polygon cutout sized by across-flats (for even/odd n)
module poly_cutout(n, flat_d, h) {
    // For a regular n-gon: apothem a = R*cos(pi/n); across-flats = 2a
    // => circumradius R = (flat_d/2)/cos(pi/n)
    R = (flat_d/2) / cos(180/n);

    linear_extrude(height=h, center=true)
        circle(r=R, $fn=n);
}

module corner_cutouts() {
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(plate_L/2 - cutout_edge_offset_x),
                   sy*(plate_W/2 - cutout_edge_offset_y),
                   0])
            rotate([0, 0, cutout_angle_deg])
                poly_cutout(cutout_sides, cutout_flat_d, plate_T + 2*overlap);
    }
}

difference() {
    rounded_plate(plate_L, plate_W, plate_T, corner_R);
    corner_cutouts();
}

// Small axially oriented fitting: faceted collar with through-bore + slotted shank + central rib
// Units: mm

// ---------- Parameters (kept from original, but made consistent) ----------
bbox_x = 0.04; //[0.02:0.08:0.001]
bbox_y = 0.06; //[0.03:0.12:0.001]
bbox_z = 0.09; //[0.045:0.18:0.001]

collar_z = 0.02; //[0.01:0.04:0.001]
collar_facets = 6; //[6:6:1]
collar_radius = 0.018; //[0.009:0.03:0.001]
hole_d = 0.018; //[0.009:0.03:0.001]

shank_z = 0.07; //[0.035:0.14:0.001]
shank_x = 0.028; //[0.014:0.04:0.001]
shank_y = 0.036; //[0.018:0.06:0.001]

slot_len = 0.022; //[0.011:0.04:0.001]
slot_w = 0.008; //[0.004:0.016:0.001]
slot_z_center_1 = 0.02; //[0.01:0.06:0.001]
slot_z_center_2 = 0.045; //[0.02:0.065:0.001]

rib_thk = 0.004; //[0.002:0.008:0.001]
rib_h = 0.01; //[0.005:0.02:0.001]
rib_z_start = 0.0; //[0.0:0.02:0.001]
rib_z_end = 0.07; //[0.04:0.07:0.001]

overlap = 0.001; //[0.0005:0.002:0.0005]

// ---------- Derived placement (no arbitrary translates) ----------
total_z = collar_z + shank_z;

// Place model so collar top is at +total_z/2 and shank bottom at -total_z/2
collar_cz =  total_z/2 - collar_z/2;
shank_cz  = -total_z/2 + shank_z/2;

// Slots are positioned within shank, measured from shank top face (near collar)
function slot_cz_from_top(z_from_shank_top) =
    (shank_cz + shank_z/2) - z_from_shank_top;

// ---------- Helpers ----------
module capsule_slot_y(len, w, h_y) {
    // Slot runs along Z (len), thickness along X (w), extruded along Y (h_y)
    // Centered at origin.
    union() {
        cube([w, h_y, len], center=true);
        translate([0, 0, -len/2 + w/2])
            rotate([90, 0, 0]) cylinder(r=w/2, h=h_y, center=true, $fn=32);
        translate([0, 0,  len/2 - w/2])
            rotate([90, 0, 0]) cylinder(r=w/2, h=h_y, center=true, $fn=32);
    }
}

// ---------- Base solids ----------
module collar_head_faceted() {
    translate([0, 0, collar_cz])
        cylinder(r=collar_radius, h=collar_z, center=true, $fn=collar_facets);
}

module rectangular_shank() {
    translate([0, 0, shank_cz])
        cube([shank_x, shank_y, shank_z], center=true);
}

module central_longitudinal_rib() {
    // Rib centered on shank, protruding on +Y face, running along Z
    rib_len = max(0, rib_z_end - rib_z_start);
    rib_cz_local = -shank_z/2 + rib_z_start + rib_len/2;

    translate([0, shank_y/2 - rib_h/2 + overlap, shank_cz + rib_cz_local])
        cube([rib_thk, rib_h, rib_len], center=true);
}

// ---------- Cutters ----------
module central_through_opening() {
    // Through-bore along Z through entire part
    cylinder(r=hole_d/2, h=total_z + 4*overlap, center=true, $fn=48);
}

module shank_slot_at(z_from_shank_top) {
    // Cut slot through shank in Y direction, centered in X, running along Z
    translate([0, 0, slot_cz_from_top(z_from_shank_top)])
        capsule_slot_y(slot_len, slot_w, shank_y + 4*overlap);
}

// ---------- Main ----------
module main_solid() {
    union() {
        collar_head_faceted();
        // Ensure collar and shank are connected with slight overlap
        translate([0, 0, -overlap/2]) rectangular_shank();
        central_longitudinal_rib();
    }
}

difference() {
    main_solid();
    shank_slot_at(slot_z_center_1);
    shank_slot_at(slot_z_center_2);
    central_through_opening();
}

// Flat-pack rail/strap set with cutouts + notched rails + small spool/I-beam block
// One connected solid (explicit overlaps/bridges ensure connectivity)

$fn = 48;

// --- Scale note ---
// The prompt's bounding box is extremely tiny (sub-mm). Many renderers will look blank.
// Keep the same proportions but scale up for visibility; set SCALE=1 to revert.
SCALE = 1000; // 1000x makes ~0.22mm -> ~220mm for clear viewing

// Parameters
bb_L = 0.22 * SCALE;
bb_W = 0.14 * SCALE;

t    = 0.001 * SCALE;
gap  = 0.004 * SCALE;

// Required overlap for solid connections (1–2mm in scaled view)
conn_ov = 0.0015 * SCALE;   // ~1.5mm at SCALE=1000
eps = 1e-6 * SCALE;
t_cut = t + 2*eps;

// Straps
strap_L = 0.205 * SCALE;
strap_W = 0.018 * SCALE;
strap_ch = 0.006 * SCALE;
strap_hole_pitch = 0.022 * SCALE;
strap_hole_size  = 0.007 * SCALE;
strap_hole_count = 7;

// Rails
rail_L = 0.205 * SCALE;
rail_W = 0.014 * SCALE;
tooth_pitch = 0.01 * SCALE;
tooth_depth = 0.004 * SCALE;
tooth_count = 14;
tooth_width = 0.006 * SCALE;

// Spool / I-beam-ish block (make it clearly visible and distinct)
spool_L = 0.022 * SCALE;
spool_W = 0.014 * SCALE;
spool_H = max(0.002 * SCALE, t); // slightly thicker than plate so it reads in ortho views
spool_web_W = 0.0045 * SCALE;

// Bridge sizing (ensure not vanishingly thin)
bridge_w = max(min(gap*0.7, min(rail_W, strap_W)*0.45), t*1.5);

// 2D helpers
module chamfered_rect_2d(L, W, ch) {
  ch2 = min(ch, min(L/2 - eps, W/2 - eps));
  polygon(points=[
    [-L/2 + ch2, -W/2],
    [ L/2 - ch2, -W/2],
    [ L/2,       -W/2 + ch2],
    [ L/2,        W/2 - ch2],
    [ L/2 - ch2,  W/2],
    [-L/2 + ch2,  W/2],
    [-L/2,        W/2 - ch2],
    [-L/2,       -W/2 + ch2]
  ]);
}

module tri_2d(s) {
  polygon(points=[[-s/2, -s/2], [s/2, -s/2], [0, s/2]]);
}

module strap_plate() {
  difference() {
    linear_extrude(height=t, center=true)
      chamfered_rect_2d(strap_L, strap_W, strap_ch);

    for (i = [0:strap_hole_count-1]) {
      x = -strap_hole_pitch*(strap_hole_count-1)/2 + strap_hole_pitch*i;
      translate([x, 0, 0])
        linear_extrude(height=t_cut, center=true) {
          if (i % 3 == 0) {
            square([strap_hole_size, strap_hole_size], center=true);
          } else if (i % 3 == 1) {
            rotate(45) square([strap_hole_size, strap_hole_size], center=true);
          } else {
            tri_2d(strap_hole_size);
          }
        }
    }
  }
}

module rail_strip() {
  difference() {
    cube([rail_L, rail_W, t], center=true);

    for (i = [0:tooth_count-1]) {
      x = -rail_L/2 + tooth_pitch/2 + tooth_pitch*i;
      translate([x, rail_W/2 - tooth_depth/2, 0])
        cube([tooth_width, tooth_depth, t_cut], center=true);
    }
  }
}

module small_spool_block() {
  // "I-beam/spool" silhouette: two flanges with a web (via subtraction)
  difference() {
    cube([spool_L, spool_W, spool_H], center=true);
    cube([spool_L*0.62, max(eps, spool_W - spool_web_W), spool_H + 2*eps], center=true);
  }
}

module bridge_x(len, wid, thick) { cube([len, wid, thick], center=true); }
module bridge_y(len, wid, thick) { cube([wid, len, thick], center=true); }

// --- Layout (centered in X, stacked in Y) ---
// Use explicit formulas so parts touch via bridges with overlap.
y_rail1  = 0;
y_rail2  = y_rail1 + (rail_W/2 + gap + rail_W/2);
y_strap1 = y_rail2 + (rail_W/2 + gap + strap_W/2);
y_strap2 = y_strap1 + (strap_W/2 + gap + strap_W/2);

// Place spool as a distinct separate piece offset from the strips (clearly visible),
// but still connected via a bridge to rail1.
x_spool = -rail_L/2 - gap - spool_L/2; // left of rails with a visible gap
y_spool = y_rail1 - (rail_W/2 + gap + spool_W/2); // below rail1 with a visible gap

// --- Bridge lengths (computed from actual edges + overlap) ---
// Between rail1 and rail2 (vertical)
len_r1_r2 = (rail_W/2 + gap + rail_W/2) + 2*conn_ov;
// Between rail2 and strap1 (vertical)
len_r2_s1 = (rail_W/2 + gap + strap_W/2) + 2*conn_ov;
// Between strap1 and strap2 (vertical)
len_s1_s2 = (strap_W/2 + gap + strap_W/2) + 2*conn_ov;

// Spool -> rail1 bridge (diagonal-ish via two orthogonal bridges for robustness)
// 1) X-bridge at y = y_rail1: from rail left edge to spool right edge
rail_left_x   = -rail_L/2;
spool_right_x = x_spool + spool_L/2;
x_gap_len = (rail_left_x - spool_right_x); // positive distance between edges
bridge_len_x = max(eps, x_gap_len + 2*conn_ov);
x_bridge_center = (rail_left_x + spool_right_x)/2;

// 2) Y-bridge at x = x_spool: from spool top edge to rail1 bottom edge
rail1_bottom_y = y_rail1 - rail_W/2;
spool_top_y    = y_spool + spool_W/2;
y_gap_len = (rail1_bottom_y - spool_top_y);
bridge_len_y = max(eps, y_gap_len + 2*conn_ov);
y_bridge_center = (rail1_bottom_y + spool_top_y)/2;

union() {
  // Main strips
  translate([0, y_rail1, 0])  rail_strip();
  translate([0, y_rail2, 0])  rail_strip();
  translate([0, y_strap1, 0]) strap_plate();
  translate([0, y_strap2, 0]) strap_plate();

  // Distinct small separate spool/I-beam block (offset so it reads clearly)
  translate([x_spool, y_spool, 0]) small_spool_block();

  // Connectivity bridges (ensure ONE connected solid)
  translate([0, (y_rail1 + y_rail2)/2, 0])
    bridge_y(len_r1_r2, bridge_w, t);

  translate([0, (y_rail2 + y_strap1)/2, 0])
    bridge_y(len_r2_s1, bridge_w, t);

  translate([0, (y_strap1 + y_strap2)/2, 0])
    bridge_y(len_s1_s2, bridge_w, t);

  // Spool connectivity (two-step bridge so it cannot miss due to diagonal placement)
  translate([x_bridge_center, y_rail1, 0])
    bridge_x(bridge_len_x, min(bridge_w, spool_W*0.9), max(t, spool_H));

  translate([x_spool, y_bridge_center, 0])
    bridge_y(bridge_len_y, min(bridge_w, spool_L*0.9), max(t, spool_H));
}

// Parameters
bbox_x = 0.01; //[0.005:0.02:0.0001]
bbox_y = 0.01; //[0.005:0.02:0.0001]
bbox_z = 0.01; //[0.005:0.02:0.0001]
head_h = 0.0042; //[0.0021:0.0084:0.0001]
head_r_max = 0.0048; //[0.0024:0.0096:0.0001]
head_r_base = 0.0032; //[0.0016:0.0064:0.0001]
neck_h = 0.0006; //[0.0003:0.0012:0.00005]
neck_r = 0.0026; //[0.0013:0.0052:0.0001]
shank_h = 0.0052; //[0.0026:0.0104:0.0001]
shank_r = 0.0022; //[0.0011:0.0044:0.0001]
flange_r = 0.003; //[0.0015:0.006:0.0001]
flange_t = 0.00035; //[0.00015:0.0007:0.00001]
flange1_z = 0.0016; //[0.0008:0.0032:0.0001]
flange2_z = 0.0034; //[0.0017:0.0068:0.0001]
hole_r = 0.0007; //[0.00035:0.0014:0.00005]
hole_depth = 0.0065; //[0.00325:0.013:0.0001]
overlap = 0.0008; //[0.0005:0.002:0.0001]
facet_segments = 12; //[6:48:1]
micro_chamfer = 0.00025; //[0.0001:0.0005:0.00001]
tip_round_r = 0.00035; //[0.00015:0.0007:0.00001]

// Base Shapes
module faceted_tessellation_low_poly() {
  rotate_extrude($fn=facet_segments) {
    polygon(points=[
      [0, 0],
      [shank_r - micro_chamfer, 0],
      [shank_r, micro_chamfer],
      [shank_r, shank_h - micro_chamfer],
      [shank_r + (flange_r - shank_r) * 0.6, shank_h - flange2_z - flange_t/2],
      [flange_r, shank_h - flange2_z],
      [shank_r + (flange_r - shank_r) * 0.6, shank_h - flange2_z + flange_t/2],
      [shank_r, shank_h - flange2_z + flange_t/2 + micro_chamfer],
      [shank_r, shank_h - flange1_z - flange_t/2 - micro_chamfer],
      [shank_r + (flange_r - shank_r) * 0.6, shank_h - flange1_z - flange_t/2],
      [flange_r, shank_h - flange1_z],
      [shank_r + (flange_r - shank_r) * 0.6, shank_h - flange1_z + flange_t/2],
      [shank_r, shank_h - flange1_z + flange_t/2 + micro_chamfer],
      [shank_r, shank_h - micro_chamfer],
      [neck_r, shank_h],
      [head_r_base, shank_h + neck_h],
      [head_r_max, shank_h + neck_h + head_h * 0.55],
      [head_r_max - micro_chamfer, shank_h + neck_h + head_h - micro_chamfer],
      [0, shank_h + neck_h + head_h],
      [0, 0]
    ]);
  }
}

module shank_cylinder() {
  translate([0, 0, 0])
    cylinder(h=shank_h, r=shank_r, center=false);
}

module head_to_shank_transition_neck() {
  translate([0, 0, shank_h - overlap])
    cylinder(h=neck_h + overlap, r=neck_r, center=false);
}

module head_domed_conical() {
  translate([0, 0, shank_h + neck_h])
    cylinder(h=head_h, r1=head_r_max, r2=0, center=false);
}

module retaining_flange_1() {
  translate([0, 0, shank_h - flange1_z])
    cylinder(h=flange_t, r=flange_r, center=true);
}

module retaining_flange_2() {
  translate([0, 0, shank_h - flange2_z])
    cylinder(h=flange_t, r=flange_r, center=true);
}

module tiny_tip_rounding() {
  translate([0, 0, tip_round_r - overlap])
    sphere(r=tip_round_r);
}

module edge_chamfers_micro() {
  translate([0, 0, 0])
    cylinder(h=micro_chamfer + overlap, r1=shank_r, r2=0, center=false);
}

module internal_axial_hole() {
  translate([0, 0, 0])
    cylinder(h=hole_depth, r=hole_r, center=false);
}

// Operations
module union_main_parts() {
  union() {
    shank_cylinder();
    head_to_shank_transition_neck();
    head_domed_conical();
    retaining_flange_1();
    retaining_flange_2();
    tiny_tip_rounding();
    edge_chamfers_micro();
  }
}

module union_with_faceted_shell() {
  union() {
    union_main_parts();
    faceted_tessellation_low_poly();
  }
}

module difference_internal_relief() {
  difference() {
    union_with_faceted_shell();
    internal_axial_hole();
  }
}

// Final Output
difference_internal_relief();

// Prismatic U-channel cradle/guide block with:
// - open-top cavity (U-channel) clearly visible from top
// - recessed central pocket (second step down) in the cavity floor
// - slightly tapered inner faces of side walls (draft)
// - chamfered outer top edges (along length)
// - bottom rectangular relief/notch creating a bridge-like underside profile
//
// Structural fixes applied:
// - Cavity tool is an OPEN-TOP cut (no "top face" in polyhedron) so top view shows the opening
// - Bottom notch is cut from underside but clamped to NOT break into cavity floor
// - Pocket is cut from cavity floor downward but clamped to preserve remaining floor
// - All translate() values are derived from L/W/H and feature sizes (no arbitrary offsets)
// - Single connected solid via one base cube and subtractive tools
// - Small overlap used to avoid coplanar artifacts

// ---------- Parameters (mm) ----------
L = 30;                  // overall length (X)
W = 20;                  // overall width  (Y)
H = 20;                  // overall height (Z)

wall_t = 4;              // side wall thickness (each side)

floor_t = 4;             // thickness under main cavity floor (must remain)
cavity_depth = H - floor_t;  // depth of open-top cavity from top down (leaves floor)

taper_per_side = 0.5;    // inner wall taper per side (wider at top by 2*taper)

chamfer = 1;             // outer top edge chamfer size (along the two long top edges)

notch_L = 20;            // bottom relief notch length (X)
notch_W = 12;            // bottom relief notch width  (Y)
notch_H = 8;             // bottom relief notch height (Z, from bottom upward)

pocket_L = 22;           // recessed pocket in cavity floor (X)
pocket_W = 12;           // recessed pocket in cavity floor (Y)
pocket_depth = 2;        // extra depth below cavity floor (Z)

overlap = 0.6;           // boolean overlap (mm) to avoid coplanar artifacts (within 1-2mm)

$fn = 48;

// ---------- Helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Effective dimensions (kept valid)
floor_t_eff      = clamp(floor_t, 1, H - 1);
cavity_depth_eff = clamp(cavity_depth, 1, H - floor_t_eff);

// Ensure bottom notch does not break into the cavity floor (bridge-like underside)
notch_H_eff      = clamp(notch_H, 0, max(0, floor_t_eff - 1));

// Ensure pocket does not break through the remaining floor
pocket_depth_eff = clamp(pocket_depth, 0, max(0, floor_t_eff - 1));

// Inner opening width at cavity bottom/top (taper in Y with Z)
inner_W_bottom = max(0.5, W - 2*wall_t);
inner_W_top    = max(0.5, inner_W_bottom + 2*taper_per_side);

// ---------- Tools (subtractive solids) ----------
module cavity_tool_open_top() {
    // Open-top cavity with tapered inner faces.
    // IMPORTANT: no "top face" included, so it is a true open cut and reads as a cavity in top view.
    z_top =  H/2 + overlap;
    z_bot =  H/2 - cavity_depth_eff - overlap;

    y_top_p =  inner_W_top/2;
    y_top_n = -inner_W_top/2;
    y_bot_p =  inner_W_bottom/2;
    y_bot_n = -inner_W_bottom/2;

    x_p =  L/2 + overlap;
    x_n = -L/2 - overlap;

    polyhedron(
        points=[
            [x_n, y_top_n, z_top], // 0
            [x_n, y_top_p, z_top], // 1
            [x_n, y_bot_p, z_bot], // 2
            [x_n, y_bot_n, z_bot], // 3
            [x_p, y_top_n, z_top], // 4
            [x_p, y_top_p, z_top], // 5
            [x_p, y_bot_p, z_bot], // 6
            [x_p, y_bot_n, z_bot]  // 7
        ],
        faces=[
            [0,1,2,3],   // x_n side
            [4,7,6,5],   // x_p side
            // NO TOP FACE -> open-top cavity
            [3,2,6,7],   // bottom face (cavity floor surface)
            [0,3,7,4],   // y- inner wall
            [1,5,6,2]    // y+ inner wall
        ],
        convexity=10
    );
}

module pocket_tool() {
    // Extra recessed pocket in the cavity floor (second step down).
    // Starts at cavity floor and goes DOWN by pocket_depth_eff.
    z_cav_floor = H/2 - cavity_depth_eff; // Z of cavity floor plane
    translate([0, 0, z_cav_floor - pocket_depth_eff/2])
        cube([pocket_L + 2*overlap, pocket_W + 2*overlap, pocket_depth_eff + 2*overlap], center=true);
}

module bottom_notch_tool() {
    // Rectangular relief from bottom upward, centered.
    // Clamped so it stays within the bottom floor thickness (bridge-like profile).
    translate([0, 0, -H/2 + notch_H_eff/2])
        cube([notch_L + 2*overlap, notch_W + 2*overlap, notch_H_eff + 2*overlap], center=true);
}

module top_chamfer_tools() {
    // Chamfer ONLY the two long outer top edges (along X) at Y = +/-W/2.
    // Use long rotated prisms that run the full length.
    if (chamfer > 0) {
        translate([0,  W/2 - chamfer/2, H/2 - chamfer/2])
            rotate([45, 0, 0])
                cube([L + 4*overlap, chamfer + 2*overlap, chamfer + 2*overlap], center=true);

        translate([0, -W/2 + chamfer/2, H/2 - chamfer/2])
            rotate([45, 0, 0])
                cube([L + 4*overlap, chamfer + 2*overlap, chamfer + 2*overlap], center=true);
    }
}

// ---------- Main solid ----------
module u_channel_block() {
    difference() {
        // Single connected base solid
        cube([L, W, H], center=true);

        // Subtractions to form the cradle/guide features
        cavity_tool_open_top(); // open-top cavity with tapered inner faces (visible in top view)
        pocket_tool();          // recessed pocket step in the cavity floor
        bottom_notch_tool();    // underside relief (bridge-like)
        top_chamfer_tools();    // chamfered outer top edges
    }
}

// Final model: one connected solid
u_channel_block();

// Compact faceted cylindrical tool body with:
// - central hex through-bore (visible on both ends)
// - multiple smaller hexagonal through-holes arranged around it on ONE end face (-X end)
// - stepped collar near one end (-X)
// - domed/capped opposite end (+X)
// Units: meters

// ---------- Quality ----------
$fn = 64;
facet_count = 12;

// ---------- Parameters ----------
body_len      = 0.026;
body_flat_d   = 0.0092;

collar_len    = 0.0025;
collar_flat_d = 0.010;

dome_len      = 0.0015;   // axial length of cap segment
dome_r        = 0.005;    // sphere radius used to form cap

bore_hex_af   = 0.0036;

hole_count    = 6;
hole_hex_af   = 0.0016;
hole_ring_r   = 0.0032;

recess_depth  = 0.0006;
recess_af     = 0.0068;

// Robust overlap for unions/cuts (1–2mm)
overlap       = 0.0012;

// ---------- Derived extents (axis along X) ----------
x_body_min   = -body_len/2;
x_body_max   =  body_len/2;

x_collar_min = x_body_min - collar_len + overlap; // overlaps into body
x_collar_max = x_body_min + overlap;

x_neg_end    = x_collar_min; // outermost -X end face
x_pos_end    = x_body_max + dome_len; // outermost +X end (cap tip plane)

// ---------- Helpers ----------
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for hex with given across-flats

module hex_prism_x(af, len, center=true) {
    rotate([0,90,0])
        linear_extrude(height=len, center=center, convexity=10)
            circle(r=hex_R_from_AF(af), $fn=6);
}

// ---------- Main solids (axis along X) ----------
module main_faceted_body() {
    rotate([0,90,0])
        cylinder(r=body_flat_d/2, h=body_len, $fn=facet_count, center=true);
}

module stepped_collar() {
    // Collar spans x = [x_collar_min, x_collar_max]
    translate([(x_collar_min + x_collar_max)/2, 0, 0])
        rotate([0,90,0])
            cylinder(r=collar_flat_d/2, h=(x_collar_max - x_collar_min), $fn=facet_count, center=true);
}

module domed_or_capped_end() {
    // Domed cap on +X end, overlapping into main body by `overlap`
    x_base = x_body_max - overlap; // where sphere begins overlapping the body
    x_tip  = x_body_max + dome_len;

    intersection() {
        translate([x_base, 0, 0]) sphere(r=dome_r, $fn=96);
        translate([(x_base + x_tip)/2, 0, 0])
            cube([ (x_tip - x_base) + 2*overlap,
                   2*(dome_r + overlap),
                   2*(dome_r + overlap) ], center=true);
    }
}

// ---------- Cutters ----------
module central_hex_through_bore() {
    // Through the entire assembled length (+ extra) so openings are visible on both ends
    total_len = (x_pos_end - x_neg_end) + 6*overlap;
    hex_prism_x(bore_hex_af, total_len, center=true);
}

module peripheral_hex_holes_endface_only() {
    // Smaller hex through-holes that start at the -X end face and run inward only.
    // Ensure they CLEAR the collar and enter the main body.
    hole_depth = body_len * 0.55;

    // Start slightly outside the -X end face, extend inward
    x_start  = x_neg_end - overlap;
    x_end    = x_start + hole_depth + 2*overlap;
    x_center = (x_start + x_end)/2;

    for (i = [0:hole_count-1]) {
        ang = i * 360 / hole_count;
        translate([x_center, hole_ring_r*cos(ang), hole_ring_r*sin(ang)])
            hex_prism_x(hole_hex_af, (x_end - x_start), center=true);
    }
}

module end_face_recess() {
    // Shallow hex counterbore opening on the -X end face (around the central bore)
    x_start  = x_neg_end - overlap;
    x_end    = x_start + recess_depth + 2*overlap;
    x_center = (x_start + x_end)/2;

    translate([x_center, 0, 0])
        hex_prism_x(recess_af, (x_end - x_start), center=true);
}

// ---------- Assembly ----------
module tool_body() {
    difference() {
        union() {
            main_faceted_body();
            stepped_collar();
            domed_or_capped_end();
        }
        // Required features:
        central_hex_through_bore();
        peripheral_hex_holes_endface_only();
        end_face_recess();
    }
}

// Final output
tool_body();

// Thick annular ring (washer/bushing-like) with circular through-bore
// and a faceted, slightly irregular outer surface.
// Bounding box target: ~0.1 x 0.1 x 0.1 mm

$fn = 96;

// Parameters (mm)
bbox_x = 0.1;
bbox_y = 0.1;
bbox_z = 0.1;

height  = bbox_z;          // axial thickness
outer_d = bbox_x;          // overall OD
inner_d = 0.045;           // circular bore ID

facet_sides = 18;          // faceted exterior
outer_irregularity = 0.03; // +/- radial variation (fraction of radius)

edge_chamfer = 0.004;      // small edge bevel
overlap = 0.002;           // boolean robustness

function clamp(x, a, b) = x < a ? a : (x > b ? b : x);

// Deterministic slightly irregular faceted profile
module irregular_facet_profile(r, n, irr=0.03, phase=0) {
    polygon(points=[
        for (i = [0:n-1]) let(
            a = phase + i*360/n,
            k = 1
                + irr*0.60*sin(a*1 + 17)
                + irr*0.35*sin(a*2 + 73)
                + irr*0.25*sin(a*3 + 11),
            rr = r * clamp(k, 1-irr*1.2, 1+irr*1.2)
        )
        [ rr*cos(a), rr*sin(a) ]
    ]);
}

// Faceted outer solid (NOT rotate_extrude; that caused empty/invalid geometry)
module outer_faceted_solid() {
    r = outer_d/2;
    linear_extrude(height=height, center=true, convexity=10)
        irregular_facet_profile(r=r, n=facet_sides, irr=outer_irregularity, phase=0);
}

// Chamfered cylindrical envelope to bevel the faceted solid
module chamfer_clip() {
    r = outer_d/2;
    h = height;

    if (edge_chamfer <= 0)
        cylinder(r=r, h=h + overlap*2, center=true);
    else
        union() {
            // middle straight section
            cylinder(r=r, h=max(0, h - 2*edge_chamfer) + overlap*2, center=true);

            // top chamfer
            translate([0,0, (h/2 - edge_chamfer/2)])
                cylinder(r1=r, r2=max(0, r-edge_chamfer), h=edge_chamfer + overlap, center=true);

            // bottom chamfer
            translate([0,0, -(h/2 - edge_chamfer/2)])
                cylinder(r1=max(0, r-edge_chamfer), r2=r, h=edge_chamfer + overlap, center=true);
        }
}

module through_bore() {
    cylinder(r=inner_d/2, h=height + 2*overlap, center=true, $fn=128);
}

module annular_ring() {
    difference() {
        // One connected body: faceted exterior clipped by chamfered envelope
        intersection() {
            outer_faceted_solid();
            chamfer_clip();
        }
        through_bore();
    }
}

// Final output
annular_ring();

// Flat stepped mounting plate with narrow tongue + rounded tip and 5 hex through-holes
// Units are in mm (small values here are intentional per provided parameters).

$fn = 96;

// Parameters
L = 0.09;                 //[0.045:0.18:0.001] overall length
W = 0.04;                 //[0.02:0.08:0.001] body width
T = 0.004;                //[0.002:0.008:0.0005] thickness

base_L = 0.05;            //[0.025:0.1:0.001] wide section length
tongue_L = 0.04;          //[0.02:0.08:0.001] narrow tongue length
tongue_W = 0.024;         //[0.012:0.048:0.001] tongue width
tip_R = 0.012;            //[0.006:0.024:0.001] rounded tip radius (semicircle)

hex_large_AF = 0.016;     //[0.008:0.032:0.001] across flats
hex_small_AF = 0.008;     //[0.004:0.016:0.0005]
hex_clearance = 0.0005;   //[0.0:0.0015:0.0001]

large_hex_x = 0.022;      //[0.011:0.044:0.001] from left end of overall part
large_hex_y = 0.0;        //[-0.01:0.01:0.0005]

small_hex_center_x = 0.072; //[0.036:0.144:0.001] from left end of overall part
small_hex_dx = 0.01;        //[0.005:0.02:0.0005]
small_hex_dy = 0.01;        //[0.005:0.02:0.0005]

overlap = 0.001;          //[0.0005:0.002:0.0001] ensures connectivity/robust boolean

// Helpers
function hex_r_from_AF(af) = (af/2) / cos(30); // circumradius for a hex with given across-flats

module hex_hole(af, h) {
  rotate([0,0,30])
    cylinder(r=hex_r_from_AF(af + hex_clearance), h=h, center=true, $fn=6);
}

// 2D outline (extruded to thickness)
module plate_2d() {
  // Coordinate system: x from 0..L, y centered about 0
  // Wide rectangle: [0..base_L] x [-W/2..W/2]
  // Tongue rectangle: [base_L..base_L+tongue_L] x [-tongue_W/2..tongue_W/2]
  // Rounded tip: semicircle centered at x = base_L + tongue_L, radius tip_R, unioned with tongue
  union() {
    translate([base_L/2, 0])
      square([base_L, W], center=true);

    // Tongue + rounded end
    union() {
      translate([base_L + tongue_L/2, 0])
        square([tongue_L, tongue_W], center=true);

      // Full circle unioned; only the forward half protrudes beyond tongue end
      translate([base_L + tongue_L, 0])
        circle(r=tip_R);
    }
  }
}

module plate_solid() {
  linear_extrude(height=T, center=true, convexity=10)
    plate_2d();
}

module holes() {
  // Through holes: make taller than T for clean subtraction
  hole_h = T + 2*overlap;

  // Large hex on wide section
  translate([large_hex_x, large_hex_y, 0])
    hex_hole(hex_large_AF, hole_h);

  // Four small hex holes in 2x2 near rounded end
  for (sx = [-small_hex_dx/2, small_hex_dx/2])
    for (sy = [-small_hex_dy/2, small_hex_dy/2])
      translate([small_hex_center_x + sx, sy, 0])
        hex_hole(hex_small_AF, hole_h);
}

// Final
difference() {
  plate_solid();
  holes();
}

// Parameters
bbox_X = 0.08; //[0.04:0.16:0.001]
bbox_Y = 0.05; //[0.025:0.1:0.001]
bbox_Z = 0.07; //[0.035:0.14:0.001]
base_L = 0.08; //[0.04:0.16:0.001]
base_W = 0.05; //[0.025:0.1:0.001]
base_T = 0.01; //[0.005:0.02:0.001]
upright_W = 0.05; //[0.025:0.1:0.001]
upright_H = 0.06; //[0.03:0.12:0.001]
upright_T = 0.01; //[0.005:0.02:0.001]
gusset_T = 0.01; //[0.005:0.02:0.001]
gusset_leg_base = 0.03; //[0.015:0.06:0.001]
gusset_leg_upright = 0.03; //[0.015:0.06:0.001]
sq_hole_d = 0.008; //[0.004:0.016:0.001]
sq_hole_rot_deg = 45; //[0:90:1]
base_hole_pitch_X = 0.018; //[0.009:0.036:0.001]
base_hole_pitch_Y = 0.016; //[0.008:0.032:0.001]
upright_hole_pitch_X = 0.018; //[0.009:0.036:0.001]
upright_hole_pitch_Z = 0.02; //[0.01:0.04:0.001]
slot_base_L = 0.03; //[0.015:0.06:0.001]
slot_base_W = 0.01; //[0.005:0.02:0.001]
slot_upright_L = 0.03; //[0.015:0.06:0.001]
slot_upright_W = 0.01; //[0.005:0.02:0.001]
slot_corner_r = 0.003; //[0.001:0.006:0.001]
tab_count = 3; //[1:6:1]
tab_L = 0.006; //[0.003:0.012:0.001]
tab_W = 0.004; //[0.002:0.008:0.001]
tab_H = 0.004; //[0.002:0.008:0.001]
overlap = 0.001; //[0.0005:0.002:0.0005]
cut_extra = 0.02; //[0.01:0.04:0.001]
edge_round_r = 0.001; //[0.0005:0.002:0.0005]

// Base Plate
module base_plate() {
  translate([0, 0, base_T/2])
    cube([base_L, base_W, base_T], center=true);
}

// Upright Plate
module upright_plate() {
  translate([-base_L/2 + upright_T/2 - overlap, 0, upright_H/2])
    cube([upright_T, upright_W, upright_H], center=true);
}

// Gusset
module triangular_gusset() {
  translate([-base_L/2 + overlap, 0, base_T + overlap])
    rotate([90, 0, 0])
      linear_extrude(height=gusset_T, center=true)
        polygon(points=[[0, 0], [gusset_leg_base, 0], [0, gusset_leg_upright]]);
}

// Edge Tabs
module edge_tabs_steps() {
  union() {
    translate([base_L/2 - tab_L/2 + overlap, 0, tab_H/2])
      cube([tab_L, tab_W, tab_H], center=true);
    translate([base_L/2 - tab_L/2 + overlap, base_W/4, tab_H/2])
      cube([tab_L, tab_W, tab_H], center=true);
    translate([base_L/2 - tab_L/2 + overlap, -base_W/4, tab_H/2])
      cube([tab_L, tab_W, tab_H], center=true);
  }
}

// Base Diamond Square Hole Pattern
module base_diamond_square_hole_pattern() {
  union() {
    for (x = [-base_hole_pitch_X, 0, base_hole_pitch_X])
      for (y = [-base_hole_pitch_Y/2, base_hole_pitch_Y/2])
        rotate([0, 0, sq_hole_rot_deg])
          translate([x, y, base_T/2])
            cube([sq_hole_d, sq_hole_d, base_T + cut_extra], center=true);
  }
}

// Upright Diamond Square Hole Pattern
module upright_diamond_square_hole_pattern() {
  union() {
    for (z = [-upright_hole_pitch_Z/2, upright_hole_pitch_Z/2])
      for (y = [0, upright_W/4])
        rotate([sq_hole_rot_deg, 0, 0])
          translate([-base_L/2 + upright_T/2 - overlap, y, z + upright_H/2])
            cube([upright_T + cut_extra, sq_hole_d, sq_hole_d], center=true);
  }
}

// Base Rectangular Slot Cutout
module base_rectangular_slot_cutout() {
  minkowski() {
    translate([base_L/4, 0, base_T/2])
      cube([slot_base_L, slot_base_W, base_T + cut_extra], center=true);
    sphere(r=slot_corner_r, center=true);
  }
}

// Upright Rectangular Slot Cutout
module upright_rectangular_slot_cutout() {
  minkowski() {
    translate([-base_L/2 + upright_T/2 - overlap, 0, upright_H*0.6])
      cube([upright_T + cut_extra, slot_upright_W, slot_upright_L], center=true);
    sphere(r=slot_corner_r, center=true);
  }
}

// Main Solid Union
module main_solid_union() {
  union() {
    base_plate();
    upright_plate();
    triangular_gusset();
    edge_tabs_steps();
  }
}

// Cutouts Union
module cutouts_union() {
  union() {
    base_diamond_square_hole_pattern();
    upright_diamond_square_hole_pattern();
    base_rectangular_slot_cutout();
    upright_rectangular_slot_cutout();
  }
}

// Bracket with Cutouts
module bracket_with_cutouts() {
  difference() {
    main_solid_union();
    cutouts_union();
  }
}

// Small Edge Chamfers/Fillets
module small_edge_chamfers_fillets() {
  minkowski() {
    bracket_with_cutouts();
    sphere(r=edge_round_r, center=true);
  }
}

