$fn = 96;

// Target bounding box (mm)
bbox_L = 0.2;
bbox_W = 0.1;
bbox_H = 0.1;

// Base plate (rounded rectangle)
base_L = bbox_L;
base_W = bbox_W;
base_T = 0.02;
base_corner_R = 0.015;

// Central strap-like rib (runs along base)
rib_L = 0.14;
rib_W = 0.02;
rib_H = 0.03;

// Bosses/steps near arm transition (either side of rib)
boss_L = 0.018;
boss_W = 0.012;
boss_H = 0.015;
boss_gap = 0.003;

// Hook arm + tip (strap-like, not a tube)
arm_W = 0.02;            // strap width (Y)
arm_T = 0.012;           // strap thickness (Z)
arm_inner_R = 0.02;      // inner radius of hook
arm_sweep_deg = 210;     // open hook
tip_L = 0.02;
tip_W = 0.02;
tip_H = 0.02;

// Small overlap for watertight unions (in mm; keep tiny due to tiny model)
overlap = 0.001;

// ---------- Helpers ----------
module rounded_rect_prism(L, W, H, R) {
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - R), sy*(W/2 - R), 0])
                cylinder(r=R, h=H, center=true);
    }
}

module base_plate() {
    rounded_rect_prism(base_L, base_W, base_T, base_corner_R);
}

module rib() {
    // Rib sits on top of base, centered, runs along X
    translate([0, 0, base_T/2 + rib_H/2 - overlap])
        cube([rib_L, rib_W, rib_H], center=true);
}

module bosses() {
    // Bosses placed near the rib end where the arm starts (positive X end)
    boss_x = rib_L/2 - boss_L/2;
    boss_y = rib_W/2 + boss_gap + boss_W/2 - overlap;
    boss_z = base_T/2 + boss_H/2 - overlap;

    translate([boss_x,  boss_y, boss_z]) cube([boss_L, boss_W, boss_H], center=true);
    translate([boss_x, -boss_y, boss_z]) cube([boss_L, boss_W, boss_H], center=true);
}

module transition_block() {
    // Blend rib into hook root; ensures robust connection
    pad_L = 0.02;
    pad_W = max(rib_W * 1.6, arm_W);
    pad_H = max(arm_T * 1.2, 0.012);

    // Place pad at rib end, sitting on top of rib
    translate([rib_L/2 - pad_L/2, 0, base_T/2 + rib_H - pad_H/2 + overlap])
        cube([pad_L, pad_W, pad_H], center=true);
}

module hook_arm_and_tip() {
    // Hook root at rib end, on top of rib (strap-like section)
    hook_center_x = rib_L/2 - arm_T/2;                 // slight overlap into rib end
    hook_center_z = base_T/2 + rib_H - arm_T/2 + overlap;

    // Strap-like curved arm: rotate_extrude a rectangle (not a circle)
    // rotate_extrude revolves around Z; rotate so axis becomes world Y (hook in XZ plane)
    translate([hook_center_x, 0, hook_center_z])
        rotate([90, 0, 0])  // rotate_extrude axis -> world Y
            rotate_extrude(angle=arm_sweep_deg, convexity=10)
                translate([arm_inner_R + arm_T/2, 0, 0])
                    square([arm_T, arm_W], center=true);

    // Tip: short rectangular end with flat end face, tangent to end of sweep
    r_mid = arm_inner_R + arm_T/2;
    a = arm_sweep_deg;

    // End point in rotate_extrude's XY plane (before rotate([90,0,0])):
    end_x_local = r_mid * cos(a);
    end_y_local = r_mid * sin(a);

    // After rotate([90,0,0]): local X -> world X, local Y -> world Z
    tip_center_x = hook_center_x + end_x_local;
    tip_center_z = hook_center_z + end_y_local;

    // Tangent direction at end angle in local XY: t = [-sin(a), cos(a)]
    // Map to world XZ similarly; rotate tip so its length aligns with tangent.
    tangent_angle_world = atan2(cos(a), -sin(a)); // angle in XZ plane, degrees

    // Place tip so it overlaps into the strap end for a solid union
    translate([tip_center_x, 0, tip_center_z])
        rotate([0, -tangent_angle_world, 0]) // rotate about Y to align length in XZ
            translate([tip_L/2 - overlap, 0, 0])
                cube([tip_L, tip_W, tip_H], center=true);
}

// ---------- Assembly ----------
union() {
    base_plate();
    rib();
    bosses();
    transition_block();
    hook_arm_and_tip();
}

// Elongated faceted lever/bracket with tapered nose, stepped body, forked U-slot, and 3 mount holes
// Units: mm (very small part per given parameters)

$fn = 64;

// -------------------- Parameters --------------------
L = 0.11;                 // overall length (X)
W_max = 0.09;             // max width at mount end (Y)
W_mid = 0.06;             // mid/body width (Y)
T = 0.01;                 // thickness (Z)

L_nose = 0.02;            // nose length
W_tip = 0.02;             // nose tip width (controls chamfered/pointed nose)

L_mount = 0.03;           // mount block length
L_step  = 0.01;           // step transition length

slot_depth = 0.02;        // fork slot depth from mount end
slot_width = 0.03;        // slot opening width (Y)

hole_d = 0.004;           // through-hole diameter
hole_pitch = 0.008;       // spacing along X between holes
hole_edge_margin = 0.006; // first hole from mount end (X)

flat_cut_depth  = 0.006;  // side flat depth (Y)
flat_cut_length = 0.045;  // flat length (X)

overlap = 0.001;          // boolean overlap (small, relative to tiny model)

// -------------------- Derived positions --------------------
x_min = -L/2;
x_max =  L/2;

x_nose_end    = x_min + L_nose;
x_mount_start = x_max - L_mount;
x_step_start  = x_mount_start - L_step;

// -------------------- 2D planform (XY) --------------------
module planform_2d() {
    // Faceted/prismatic outline with a chamfered/pointed nose and a stepped mount end
    polygon(points=[
        // Nose tip (pointed)
        [x_min, 0],

        // Upper nose chamfer to body
        [x_min + L_nose*0.55,  W_tip/2],
        [x_nose_end,           W_mid/2],

        // Body to step
        [x_step_start,         W_mid/2],

        // Step up to mount width
        [x_step_start,         W_max/2],
        [x_max,                W_max/2],

        // Down at mount end
        [x_max,               -W_max/2],
        [x_step_start,        -W_max/2],

        // Step down to mid width
        [x_step_start,        -W_mid/2],

        // Lower nose chamfer back to tip
        [x_nose_end,          -W_mid/2],
        [x_min + L_nose*0.55, -W_tip/2]
        // closes to [x_min,0]
    ]);
}

// -------------------- Main solid --------------------
module body_solid() {
    linear_extrude(height=T, center=true, convexity=10)
        planform_2d();
}

// -------------------- Forked U-slot cut --------------------
module fork_slot_cut() {
    // Cut a centered rectangular slot that opens at the mount end (x_max) and goes inward by slot_depth.
    // Place the cube so its +X face is slightly beyond x_max to guarantee an open mouth.
    slot_len = slot_depth + 2*overlap;
    x_center = x_max - slot_depth/2 + overlap; // ensures x_max is inside the cut volume
    translate([x_center, 0, 0])
        cube([slot_len, slot_width, T + 2*overlap], center=true);
}

// -------------------- Three through-holes cut --------------------
module mount_holes_cut() {
    // 3 holes along X within the mount block, centered in Y, through Z.
    // Robustly keep all three inside the mount region.
    usable = max(0, L_mount - 2*hole_edge_margin);

    // Ensure 3-hole pattern fits: need 2*pitch <= usable
    pitch = min(hole_pitch, usable/2);

    // If mount is extremely small, collapse pitch safely (still 3 cylinders, may overlap)
    pitch = max(pitch, 0);

    for (i = [0:2]) {
        // Place holes from near the mount end inward
        xh_raw = x_max - hole_edge_margin - i*pitch;

        // Clamp to stay inside mount region
        xh = max(x_mount_start + hole_edge_margin, min(x_max - hole_edge_margin, xh_raw));

        translate([xh, 0, 0])
            cylinder(d=hole_d, h=T + 2*overlap, center=true);
    }
}

// -------------------- Angular/faceted flats cut --------------------
module side_flats_cut() {
    // Cut wedges from both +Y and -Y sides to create angular flats along length.
    // Start after the nose and extend into the stepped region for clearer faceting.
    x0 = x_min + L_nose*0.35;
    x1 = min(x0 + flat_cut_length, x_mount_start);

    len = max(0, x1 - x0);

    if (len > 0) {
        // +Y wedge (removes material from upper side)
        translate([x0, 0, 0])
            linear_extrude(height=T + 2*overlap, center=true, convexity=10)
                polygon(points=[
                    [0,   W_mid/2 + overlap],
                    [len, W_mid/2 + overlap],
                    [len, W_mid/2 - flat_cut_depth],
                    [0,   W_mid/2 - flat_cut_depth*0.35]
                ]);

        // -Y wedge (removes material from lower side)
        translate([x0, 0, 0])
            linear_extrude(height=T + 2*overlap, center=true, convexity=10)
                polygon(points=[
                    [0,   -W_mid/2 - overlap],
                    [len, -W_mid/2 - overlap],
                    [len, -W_mid/2 + flat_cut_depth],
                    [0,   -W_mid/2 + flat_cut_depth*0.35]
                ]);
    }
}

// -------------------- Final model (single connected solid) --------------------
union() {
    difference() {
        // Single connected solid base
        body_solid();

        // Subtractive features (all intersect the body; no floating parts)
        fork_slot_cut();
        mount_holes_cut();   // now guaranteed to be 3 holes
        side_flats_cut();
    }
}

// U-shaped bent strap with two cylindrical end bosses and recessed hex sockets
// All dimensions in mm (very small part as requested)

$fn = 96;

// ---------------- Parameters ----------------
strap_thk = 0.01;           // Z thickness of strap
strap_w   = 0.006;          // strap width (in Y for legs, radial for bend)

leg_center_spacing = 0.048; // distance between leg centerlines (Y)
u_inner_R = 0.012;          // inner bend radius (to inner edge of strap)
leg_len   = 0.02;           // straight leg length from tangent to boss transition

boss_d   = 0.012;           // boss diameter
boss_len = 0.006;           // boss length along X

boss_transition_len = 0.002; // transition length from strap to boss

hex_AF    = 0.006;          // hex across flats
hex_depth = 0.004;          // socket depth into boss (along X from end face)
socket_lead_in = 0.001;     // small lead-in depth
chamfer_scale = 1.15;       // lead-in hex scale

overlap = 0.001;            // overlap to ensure connectivity / robust booleans

// Derived
hex_R = hex_AF / sqrt(3);        // circumradius for regular hex with given AF
u_center_R = u_inner_R + strap_w/2;

// ---------------- Helpers ----------------
module hex2d(r){
    polygon(points=[
        [ r, 0],
        [ r/2,  r*sqrt(3)/2],
        [-r/2,  r*sqrt(3)/2],
        [-r, 0],
        [-r/2, -r*sqrt(3)/2],
        [ r/2, -r*sqrt(3)/2]
    ]);
}

// U-bend: 180° ring sector (in XY) with rectangular cross-section (strap_w x strap_thk), centered at origin
module u_bend_flat(){
    // Make a 2D U-shaped band (annulus sector) then extrude to strap_thk
    linear_extrude(height=strap_thk, center=true)
    difference(){
        // outer half-disk
        intersection(){
            circle(r=u_inner_R + strap_w);
            // keep only y >= 0 half (U bend at +Y)
            translate([0, (u_inner_R + strap_w)/2, 0])
                square([2*(u_inner_R + strap_w) + 2*overlap, (u_inner_R + strap_w) + 2*overlap], center=true);
        }
        // inner half-disk
        intersection(){
            circle(r=u_inner_R);
            translate([0, u_inner_R/2, 0])
                square([2*u_inner_R + 2*overlap, u_inner_R + 2*overlap], center=true);
        }
    }
}

// Straight legs (rectangular strap) from bend tangent at y=0 to bosses at y = -(leg_len + transition + boss_len/2)
module legs_flat(){
    leg_total = leg_len + boss_transition_len + overlap;
    // Legs run along -Y from y=0
    translate([ leg_center_spacing/2, -leg_total/2 + overlap/2, 0])
        cube([strap_w, leg_total, strap_thk], center=true);
    translate([-leg_center_spacing/2, -leg_total/2 + overlap/2, 0])
        cube([strap_w, leg_total, strap_thk], center=true);
}

// Transition block to boss (widen in X to boss_d, keep strap_thk in Z)
module boss_transitions(){
    // Transition occupies last boss_transition_len of the leg near the boss
    y0 = -leg_len - boss_transition_len/2 + overlap/2;
    translate([ leg_center_spacing/2, y0, 0])
        cube([boss_d, boss_transition_len + overlap, strap_thk], center=true);
    translate([-leg_center_spacing/2, y0, 0])
        cube([boss_d, boss_transition_len + overlap, strap_thk], center=true);
}

// Boss cylinders at ends, axis along Y (end axis)
module bosses_raw(){
    y_boss_center = -(leg_len + boss_transition_len + boss_len/2 - overlap);
    translate([ leg_center_spacing/2, y_boss_center, 0])
        cylinder(r=boss_d/2, h=boss_len, center=true);
    translate([-leg_center_spacing/2, y_boss_center, 0])
        cylinder(r=boss_d/2, h=boss_len, center=true);
}

// Hex socket cut: recessed from the OUTER end face of each boss (negative Y end)
module hex_socket_cut(xpos){
    y_end = -(leg_len + boss_transition_len + boss_len - overlap); // outer end face (more negative)
    y_socket_center = y_end + hex_depth/2 - overlap/2;

    union(){
        // main hex prism (along Y)
        translate([xpos, y_socket_center, 0])
            linear_extrude(height=hex_depth + overlap, center=true)
                hex2d(hex_R);

        // lead-in at the mouth (slightly larger)
        translate([xpos, y_end + socket_lead_in/2 - overlap/2, 0])
            linear_extrude(height=socket_lead_in + overlap, center=true)
                scale([chamfer_scale, chamfer_scale]) hex2d(hex_R);
    }
}

// Full part (one connected solid)
module u_bracket(){
    difference(){
        union(){
            u_bend_flat();
            legs_flat();
            boss_transitions();
            bosses_raw();
        }
        // sockets in both bosses
        hex_socket_cut( leg_center_spacing/2);
        hex_socket_cut(-leg_center_spacing/2);
    }
}

u_bracket();

// Spur-gear-like wheel with external teeth and central hex through-bore
// Single solid, constant thickness, flat parallel faces

$fn = 128;

// Parameters (meters in original; keep as-is)
bbox_X = 0.02; //[0.01:0.04:0.001]
bbox_Y = 0.01; //[0.005:0.02:0.001]
bbox_Z = 0.02; //[0.01:0.04:0.001]

thickness_Y = 0.01; //[0.005:0.02:0.001]
outer_diam_XZ = 0.02; //[0.01:0.04:0.001]     // tip diameter (approx)
body_diam_XZ  = 0.016; //[0.008:0.032:0.001]   // root/body diameter

tooth_count = 12; //[6:40:1]
tooth_depth_rad = 0.002; //[0.001:0.004:0.0005]
tooth_tip_width_arc  = 0.003; //[0.0015:0.006:0.0005] // tangential width at tip
tooth_root_width_arc = 0.002; //[0.001:0.004:0.0005]  // tangential width at root

hex_flat_to_flat = 0.008; //[0.004:0.016:0.0005]
hex_clearance = 0.0002; //[0.0:0.001:0.0001]

overlap = 0.0005; //[0.0001:0.002:0.0001]
chamfer_size = 0.0005; //[0.0:0.002:0.0001]

// Derived
body_r = body_diam_XZ/2;
tooth_len = tooth_depth_rad;
tooth_w_root = tooth_root_width_arc;
tooth_w_tip  = tooth_tip_width_arc;

// Ensure teeth actually reach (or slightly exceed) requested outer diameter
// If outer_diam_XZ is larger than body+tooth_depth, extend tooth length to match.
tooth_len_eff = max(tooth_len, outer_diam_XZ/2 - body_r);

// Hex geometry: for a regular hex, flat-to-flat = sqrt(3)*R (circumradius)
hex_R = (hex_flat_to_flat + hex_clearance)/sqrt(3);

// 2D hex polygon (point-up orientation)
module hex2d(R) {
    polygon(points=[
        [ R, 0],
        [ R/2,  R*sqrt(3)/2],
        [-R/2,  R*sqrt(3)/2],
        [-R, 0],
        [-R/2, -R*sqrt(3)/2],
        [ R/2, -R*sqrt(3)/2]
    ]);
}

// Single tooth as a constant-thickness prism (extruded along Y)
module single_tooth() {
    // Place tooth so it overlaps into the body by "overlap" to guarantee connectivity
    // Inner radius = body_r - overlap
    // Outer radius = body_r + tooth_len_eff
    r_in  = body_r - overlap;
    r_out = body_r + tooth_len_eff;

    // 2D trapezoid in XZ plane, then extrude along Y
    linear_extrude(height=thickness_Y, center=true)
        polygon(points=[
            [r_in,  -tooth_w_root/2],
            [r_out, -tooth_w_tip/2],
            [r_out,  tooth_w_tip/2],
            [r_in,   tooth_w_root/2]
        ]);
}

// External teeth ring (evenly spaced around Z axis)
module external_teeth_ring() {
    for (i = [0:tooth_count-1])
        rotate([0, 0, i*360/tooth_count])
            single_tooth();
}

// Main gear blank (circular body)
module gear_body_disc() {
    cylinder(r=body_r, h=thickness_Y, center=true);
}

// Optional edge chamfer cutters (keep faces flat/parallel; chamfer only at rim)
module edge_chamfer_cutters() {
    // Cut a small 45-ish chamfer at top and bottom outer edge
    // Use cones that intersect only near the rim.
    r_outer = body_r + tooth_len_eff + overlap;
    r_inner = max(0, r_outer - chamfer_size);

    // Top chamfer cutter
    translate([0, thickness_Y/2 - chamfer_size/2, 0])
        cylinder(r1=r_outer, r2=r_inner, h=chamfer_size + 2*overlap, center=true);

    // Bottom chamfer cutter
    translate([0, -thickness_Y/2 + chamfer_size/2, 0])
        cylinder(r1=r_inner, r2=r_outer, h=chamfer_size + 2*overlap, center=true);
}

// Central hex through-bore
module central_hex_through_bore() {
    linear_extrude(height=thickness_Y + 2*overlap, center=true)
        hex2d(hex_R);
}

// Final part
module final_gear() {
    difference() {
        // One connected solid: body + teeth
        difference() {
            union() {
                gear_body_disc();
                external_teeth_ring();
            }
            if (chamfer_size > 0)
                edge_chamfer_cutters();
        }

        // Through-bore only (remove any extra cylindrical subtraction that would distort the hex)
        central_hex_through_bore();
    }
}

final_gear();

// Thin elongated plate with 4 asymmetric rectangular bosses on ONE face only.
// Units: mm

// Plate (elongated along X)
plate_L = 0.10;     // length
plate_W = 0.06;     // width
plate_T = 0.006;    // thickness

// Bosses (4 discrete studs)
boss_L  = 0.014;
boss_W  = 0.010;
boss_H  = 0.004;

// Small overlap to guarantee a single connected solid
// (must be >0 and < plate_T so the opposite face stays perfectly flat)
overlap = 0.001;

// Asymmetric boss locations across the plate surface (kept within footprint)
boss_pos = [
    [-plate_L*0.33, -plate_W*0.20],
    [ plate_L*0.12, -plate_W*0.02],
    [-plate_L*0.06,  plate_W*0.24],
    [ plate_L*0.34,  plate_W*0.16]
];

module plate() {
    cube([plate_L, plate_W, plate_T], center=true);
}

module boss() {
    cube([boss_L, boss_W, boss_H], center=true);
}

// Place bosses so they protrude ONLY from +Z face.
// Plate top surface is at +plate_T/2.
// Boss bottom is set to (plate_T/2 - overlap) so it slightly intersects the plate.
// This guarantees a single solid and keeps the -Z face smooth/featureless.
boss_center_z = (plate_T/2 - overlap) + boss_H/2;

union() {
    plate();

    for (p = boss_pos)
        translate([p[0], p[1], boss_center_z])
            boss();
}

// Thin octagonal annular ring with circular inner opening,
// 8 square through-holes (one per facet), and segmented/beveled outer faces.

// ---------- Parameters (mm) ----------
bbox_X = 0.09;                 // target overall X (approx)
bbox_Y = 0.09;                 // target overall Y (approx)
T = 0.01;                      // thickness (plate-like)

outer_flat_to_flat = 0.09;     // octagon flat-to-flat
inner_d = 0.045;               // circular inner diameter

hole_count = 8;                // fixed at 8
hole_size = 0.008;             // square hole size
hole_radial_center = 0.037;    // radius to hole centers (near perimeter)

bevel_depth = 0.002;           // radial inset for bevel
bevel_z = 0.003;               // height of bevel region from each face (<= T/2 recommended)

eps = 0.0005;
$fn = 96;

// ---------- Derived ----------
outer_apothem = outer_flat_to_flat/2;                 // distance center->flat
outer_R = outer_apothem / cos(180/8);                 // distance center->vertex
inner_R = inner_d/2;

// keep bevel sane for very thin parts
bevel_z_eff = min(bevel_z, T/2 - eps);
bevel_depth_eff = min(bevel_depth, outer_R - inner_R - 2*eps);

// ---------- Helpers ----------
module octagon2d(R) {
    polygon(points=[
        for (i=[0:7]) [ R*cos(45*i), R*sin(45*i) ]
    ]);
}

module ring_core() {
    // clean octagonal outer, circular inner
    difference() {
        linear_extrude(height=T, center=true)
            octagon2d(outer_R);
        cylinder(r=inner_R, h=T+2*eps, center=true);
    }
}

module holes() {
    // 8 evenly spaced square through-holes, aligned with facets (0,45,...)
    for (i=[0:hole_count-1]) {
        rotate([0,0,i*360/hole_count])
            translate([hole_radial_center, 0, 0])
                cube([hole_size, hole_size, T+2*eps], center=true);
    }
}

module segmented_outer_bevels() {
    // Create a segmented/beveled appearance by subtracting 8 wedge-like cuts
    // near the outer perimeter on both faces.
    // Each cut is a trapezoidal prism (in XY) extruded only near the top/bottom.
    w_ang = 360/hole_count;                 // 45 deg
    half_ang = w_ang/2;
    ang_margin = 6;                        // leaves small "seams" between segments
    a1 = -half_ang + ang_margin;
    a2 =  half_ang - ang_margin;

    r_outer = outer_R + 2*eps;
    r_inner = outer_R - bevel_depth_eff;

    // 2D trapezoid in polar sector (a1..a2) between r_inner..r_outer
    module bevel_sector_2d() {
        polygon(points=[
            [ r_outer*cos(a1), r_outer*sin(a1) ],
            [ r_outer*cos(a2), r_outer*sin(a2) ],
            [ r_inner*cos(a2), r_inner*sin(a2) ],
            [ r_inner*cos(a1), r_inner*sin(a1) ]
        ]);
    }

    // top and bottom bevel cuts
    for (i=[0:hole_count-1]) {
        rotate([0,0,i*w_ang]) {
            // top cut
            translate([0,0, T/2 - bevel_z_eff/2])
                linear_extrude(height=bevel_z_eff+2*eps, center=true)
                    bevel_sector_2d();

            // bottom cut
            translate([0,0,-T/2 + bevel_z_eff/2])
                linear_extrude(height=bevel_z_eff+2*eps, center=true)
                    bevel_sector_2d();
        }
    }
}

// ---------- Final ----------
difference() {
    ring_core();
    holes();
    segmented_outer_bevels();
}

// Thin mounting plate with rounded corners, 4 corner through-holes,
// stepped side notch on one edge, and mirrored engraved text on both faces.
// Units are mm (very small part as provided).

// Parameters
L = 0.07; //[0.035:0.14:0.001]
W = 0.06; //[0.03:0.12:0.001]
T = 0.01; //[0.005:0.02:0.001]

corner_r = 0.006; //[0.003:0.012:0.001]

hole_d = 0.006; //[0.003:0.012:0.001]
hole_edge_offset_x = 0.01; //[0.005:0.02:0.001]
hole_edge_offset_y = 0.01; //[0.005:0.02:0.001]

notch_depth = 0.012; //[0.006:0.024:0.001]
notch_w1 = 0.018; //[0.009:0.036:0.001]
notch_w2 = 0.01;  //[0.005:0.02:0.001]
notch_step = 0.004; //[0.002:0.008:0.001]  // how much deeper the smaller step goes

notch_fillet_r = 0.002; //[0.001:0.004:0.001]

text_str = "Sleepy Pi 2";
text_size = 0.012;      // scaled for tiny model
text_depth = 0.0012;    // engraving depth
text_font = "Liberation Sans:style=Bold";

eps = 0.001; //[0.0005:0.002:0.0005]
$fn = 48;

// Rounded rectangle prism (centered)
module rounded_plate(l, w, h, r) {
  // Ensure sane radii
  rr = min(r, min(l, w)/2 - eps);
  linear_extrude(height=h, center=true)
    offset(r=rr)
      square([l - 2*rr, w - 2*rr], center=true);
}

// Stepped notch cutout on +Y edge (centered in X)
module stepped_notch_cut() {
  // Main shallow notch (w1, depth)
  // Second deeper step (w2, depth+notch_step), centered within w1
  union() {
    translate([0, W/2 - notch_depth/2, 0])
      cube([notch_w1, notch_depth + eps, T + 2*eps], center=true);

    translate([0, W/2 - (notch_depth + notch_step)/2, 0])
      cube([notch_w2, notch_depth + notch_step + eps, T + 2*eps], center=true);

    // Simple fillet relief at the two inner corners of the shallow notch
    // (subtracting cylinders helps avoid jagged artifacts)
    for (sx = [-1, 1]) {
      translate([sx*(notch_w1/2 - notch_fillet_r), W/2 - notch_depth + notch_fillet_r, 0])
        cylinder(r=notch_fillet_r, h=T + 2*eps, center=true);
    }
  }
}

// Corner through-holes
module corner_holes() {
  for (sx = [-1, 1], sy = [-1, 1]) {
    translate([sx*(L/2 - hole_edge_offset_x), sy*(W/2 - hole_edge_offset_y), 0])
      cylinder(r=hole_d/2, h=T + 2*eps, center=true);
  }
}

// Engraved text on both faces (mirrored on opposite face)
module mirrored_engraving() {
  // Keep text within plate
  max_w = L - 2*corner_r - 2*eps;
  max_h = W - 2*corner_r - 2*eps;

  // Top face engraving (cut into top)
  translate([0, 0, T/2 - text_depth/2])
    linear_extrude(height=text_depth + eps, center=true)
      text(text_str, size=text_size, font=text_font, halign="center", valign="center");

  // Bottom face engraving, mirrored (so it reads correctly from bottom)
  mirror([0, 1, 0])
    translate([0, 0, -T/2 + text_depth/2])
      linear_extrude(height=text_depth + eps, center=true)
        text(text_str, size=text_size, font=text_font, halign="center", valign="center");
}

// Complete model: one connected solid
difference() {
  // Base plate
  rounded_plate(L, W, T, corner_r);

  // Features to remove
  corner_holes();
  stepped_notch_cut();
  mirrored_engraving();
}

// Long prismatic bar with recessed panels on broad faces,
// chamfered/mitred perimeter corners, and shallow concave top/bottom
// across width with a central longitudinal rib/step.
//
// Target bounding box (approx): 0.1 x 0.4 x 0.1 mm  =>  H x L x W
// Here: L=0.40, W=0.10, H=0.10 (mm)

$fn = 128;

// -------------------- Parameters (mm) --------------------
L = 0.40;   // length (X)
W = 0.10;   // width  (Y)
H = 0.10;   // height (Z)

// Recessed panel on broad faces (top & bottom)
recess_margin_L = 0.03;
recess_margin_W = 0.015;
recess_depth    = 0.010;

// Perimeter chamfer (mitred corners around full perimeter)
chamfer = 0.010;

// Shallow concave curvature across width (top & bottom)
concave_sag = 0.006;   // sagitta across chord W (per face)

// Central longitudinal rib/step on top and bottom
rib_W = 0.030;         // rib width across Y
rib_H = 0.008;         // rib height above the concave surface
rib_margin_L = 0.03;   // keep rib away from ends

// Small epsilon for robust booleans (tiny, since model is tiny)
eps = 0.0005;

// -------------------- Helpers --------------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

recess_L = clamp(L - 2*recess_margin_L, eps, L - eps);
recess_W = clamp(W - 2*recess_margin_W, eps, W - eps);
rib_L    = clamp(L - 2*rib_margin_L, eps, L - eps);

// Radius for a circular arc that gives sagitta = concave_sag over chord W
// R = W^2/(8s) + s/2
R = (W*W)/(8*concave_sag) + concave_sag/2;

// -------------------- Geometry modules --------------------
module base_block() {
    cube([L, W, H], center=true);
}

// Perimeter chamfer wedges (subtractive)
module perimeter_chamfers() {
    // Long edges along X (at Y=±W/2, Z=±H/2)
    for (sy = [-1, 1], sz = [-1, 1]) {
        translate([0, sy*(W/2 - chamfer/2), sz*(H/2 - chamfer/2)])
            rotate([0, 90, 0])
                linear_extrude(height=L + 2*eps, center=true)
                    polygon(points=[
                        [-chamfer/2 - eps, -chamfer/2 - eps],
                        [ chamfer/2 + eps, -chamfer/2 - eps],
                        [-chamfer/2 - eps,  chamfer/2 + eps]
                    ]);
    }

    // End edges along Y (at X=±L/2, Z=±H/2)
    for (sx = [-1, 1], sz = [-1, 1]) {
        translate([sx*(L/2 - chamfer/2), 0, sz*(H/2 - chamfer/2)])
            rotate([90, 0, 0])
                linear_extrude(height=W + 2*eps, center=true)
                    polygon(points=[
                        [-chamfer/2 - eps, -chamfer/2 - eps],
                        [ chamfer/2 + eps, -chamfer/2 - eps],
                        [-chamfer/2 - eps,  chamfer/2 + eps]
                    ]);
    }

    // Vertical edges along Z (at X=±L/2, Y=±W/2)
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(L/2 - chamfer/2), sy*(W/2 - chamfer/2), 0])
            linear_extrude(height=H + 2*eps, center=true)
                polygon(points=[
                    [-chamfer/2 - eps, -chamfer/2 - eps],
                    [ chamfer/2 + eps, -chamfer/2 - eps],
                    [-chamfer/2 - eps,  chamfer/2 + eps]
                ]);
    }
}

// Recessed rectangular panel on top face (subtractive)
module top_recess() {
    // Cut starts at top surface and goes downward
    translate([0, 0, H/2 - recess_depth/2])
        cube([recess_L, recess_W, recess_depth + 2*eps], center=true);
}

// Recessed rectangular panel on bottom face (subtractive)
module bottom_recess() {
    // Cut starts at bottom surface and goes upward
    translate([0, 0, -H/2 + recess_depth/2])
        cube([recess_L, recess_W, recess_depth + 2*eps], center=true);
}

// Concave cut across width on top face (cylindrical surface along X).
// IMPORTANT FIX: limit the cutter to only the top region so we don't remove the whole block.
// We intersect the cylinder with a thin "cap" volume above the top face.
module top_concave_cut() {
    cap_h = concave_sag + 4*eps; // only remove a shallow band
    intersection() {
        // Cylinder positioned so it just kisses the top plane at the edges (y=±W/2)
        translate([0, 0, H/2 + (R - concave_sag)])
            rotate([0, 90, 0])
                cylinder(r=R, h=L + 2*eps, center=true);

        // Limit to a thin slab at the top surface
        translate([0, 0, H/2 - cap_h/2 + eps])
            cube([L + 4*eps, W + 4*eps, cap_h], center=true);
    }
}

// Concave cut across width on bottom face (limited to bottom region)
module bottom_concave_cut() {
    cap_h = concave_sag + 4*eps;
    intersection() {
        translate([0, 0, -H/2 - (R - concave_sag)])
            rotate([0, 90, 0])
                cylinder(r=R, h=L + 2*eps, center=true);

        translate([0, 0, -H/2 + cap_h/2 - eps])
            cube([L + 4*eps, W + 4*eps, cap_h], center=true);
    }
}

// Central longitudinal rib/step on top and bottom (additive)
// IMPORTANT FIX: place ribs ON the concave faces (not embedded inside the block).
module ribs() {
    overlap = 2*eps;

    // Top rib: sits above the (now concave) top surface, with slight overlap into body
    translate([0, 0, H/2 + rib_H/2 - overlap])
        cube([rib_L, rib_W, rib_H + 2*overlap], center=true);

    // Bottom rib: sits below the concave bottom surface, with slight overlap into body
    translate([0, 0, -H/2 - rib_H/2 + overlap])
        cube([rib_L, rib_W, rib_H + 2*overlap], center=true);
}

// -------------------- Final solid --------------------
module part() {
    union() {
        // Main body with chamfers, recesses, and concave top/bottom
        difference() {
            base_block();

            perimeter_chamfers();

            top_recess();
            bottom_recess();

            top_concave_cut();
            bottom_concave_cut();
        }

        // Add ribs after concave cuts so they remain visible and create the arched/stepped profile
        ribs();
    }
}

part();

// Wedge-ended rectangular block with integrated U-shaped clevis/handle and through cutout
// Structural fix: make a clear clevis with TWO PARALLEL FORK ARMS (in Y), open U-channel at X+,
// plus a recognizable THROUGH cutout in the clevis loop region. All parts connected with overlaps.

// ---------- Parameters (mm) ----------
L = 60;                 // overall length (X)
W = 40;                 // overall width  (Y)
H = 50;                 // overall height (Z)

wedge_L = 18;           // length of wedge tip (X)
wedge_tip_W = 4;        // width at very tip (Y)

clevis_L = 16;          // length of clevis region (X)
channel_depth = 12;     // depth of U-channel cut from end (X)

channel_W = 16;         // inner slot width between fork arms (Y)

cutout_r = 9;           // half-width of arched/polygonal cutout (in XZ profile)
cutout_H = 22;          // height of cutout profile (Z)

blend_L = 6;            // overlap/blend length between body and clevis (X)

eps = 0.2;              // boolean robustness
overlap = 1.5;          // intentional overlap for solid connections (1-2mm)
fillet_r = 0;           // keep 0 to preserve clevis details

$fn = 48;

// ---------- Derived ----------
x_min = -L/2;
x_max =  L/2;

x_wedge_start = x_min;
x_wedge_end   = x_min + wedge_L;

x_body_start  = x_wedge_end;
x_body_end    = x_max - clevis_L;

x_clevis_start = x_body_end;
x_clevis_end   = x_max;

// Fork thickness derived, clamped for robustness
fork_wall = (W - channel_W)/2;
fork_wall = (fork_wall < 1) ? 1 : fork_wall;                 // ensure visible arms
channel_W_eff = W - 2*fork_wall;                              // actual slot width
channel_W_eff = (channel_W_eff < 1) ? 1 : channel_W_eff;

// Keep the through-cutout inside the "closed" part of the clevis (not inside the open slot)
cutout_x_center = x_clevis_start + (clevis_L - channel_depth) * 0.55;
cutout_x_center = (cutout_x_center < (x_clevis_start + 1)) ? (x_clevis_start + 1) : cutout_x_center;
cutout_x_center = (cutout_x_center > (x_max - channel_depth - 1)) ? (x_max - channel_depth - 1) : cutout_x_center;

module wedge_solid() {
  // Linear taper in Y from full W at x_wedge_end to wedge_tip_W at x_wedge_start; constant Z=H.
  polyhedron(
    points=[
      // x = x_wedge_start (tip)
      [x_wedge_start, -wedge_tip_W/2, -H/2],
      [x_wedge_start,  wedge_tip_W/2, -H/2],
      [x_wedge_start,  wedge_tip_W/2,  H/2],
      [x_wedge_start, -wedge_tip_W/2,  H/2],

      // x = x_wedge_end (full width)
      [x_wedge_end, -W/2, -H/2],
      [x_wedge_end,  W/2, -H/2],
      [x_wedge_end,  W/2,  H/2],
      [x_wedge_end, -W/2,  H/2]
    ],
    faces=[
      [0,1,2,3],
      [4,7,6,5],
      [0,4,5,1],
      [1,5,6,2],
      [2,6,7,3],
      [3,7,4,0]
    ]
  );
}

module main_body_block() {
  translate([(x_body_start + x_body_end)/2, 0, 0])
    cube([ (x_body_end - x_body_start), W, H ], center=true);
}

module clevis_outer_block() {
  // Outer volume for clevis; overlaps into body for connectivity.
  // Recalculated so the clevis overlaps the body by `overlap` at x_clevis_start.
  clevis_len = (x_clevis_end - x_clevis_start) + overlap;
  clevis_center_x = x_clevis_start + clevis_len/2 - overlap; // ensures overlap into body
  translate([clevis_center_x, 0, 0])
    cube([ clevis_len, W, H ], center=true);
}

module u_channel_cut_y() {
  // Cut a U-channel OPEN at X+ that creates TWO PARALLEL FORK ARMS in Y.
  // Remove the center slot in Y across full Z, only in the last `channel_depth` of the clevis.
  x0 = x_max - channel_depth;
  x1 = x_max + eps; // open end

  translate([(x0 + x1)/2, 0, 0])
    cube([ (x1 - x0), channel_W_eff + 2*eps, H + 2*eps ], center=true);
}

module loop_through_cutout() {
  // Through-opening across Y in the clevis loop region (in the "closed" section),
  // so it reads as a true through-hole in the clevis/handle.
  translate([cutout_x_center, 0, 0])
    rotate([90, 0, 0])
      linear_extrude(height=W + 2*eps, center=true)
        polygon(points=[
          [-cutout_r, -cutout_H/2],
          [ cutout_r, -cutout_H/2],
          [ cutout_r,  cutout_H/2 - cutout_r],
          [ 0,         cutout_H/2],
          [-cutout_r,  cutout_H/2 - cutout_r]
        ]);
}

module core() {
  union() {
    wedge_solid();
    main_body_block();

    // Ensure wedge-body connection (overlap slab at the interface)
    translate([x_wedge_end + overlap/2, 0, 0])
      cube([overlap, W, H], center=true);

    // Clevis outer volume (connected)
    clevis_outer_block();

    // Blend/overlap between body and clevis to keep silhouette continuous
    // Recalculated to straddle x_clevis_start with overlap.
    translate([x_clevis_start - blend_L/2 + overlap/2, 0, 0])
      cube([blend_L + overlap, W, H], center=true);
  }
}

module final_shape() {
  difference() {
    core();

    // Create the clevis U-channel (fork arms in Y)
    u_channel_cut_y();

    // Add through cutout in the loop region (through Y)
    loop_through_cutout();
  }
}

// Optional fillet (disabled by default)
if (fillet_r > 0)
  minkowski() { final_shape(); sphere(r=fillet_r, $fn=24); }
else
  final_shape();

$fn = 96;

// --- Target bounding box (approx): 0.1 x 0.1 x ~0 (very thin plate-like) ---
L = 0.10;                 // X
W = 0.10;                 // Y
T = 0.004;                // Z (thin but nonzero so it renders)

// Fillet radius (rounded rectangle)
corner_r = 0.012;

// Recess/decor pattern (shallow, must be visible)
recess_depth   = 0.0010;  // increased so it shows in ortho renders
recess_margin  = 0.012;
recess_line_W  = 0.004;

// Tabs (rectangular protrusions on ONE face)
tab_count = 5;
tab_L     = 0.010;
tab_W     = 0.006;
tab_H     = 0.0022;       // slightly taller so they read as protrusions
tab_gap   = 0.004;

// Placement: tabs along +Y edge, centered in X
tab_edge_inset = 0.002;   // how far tabs sit in from the outer +Y edge
overlap = 0.0003;         // ensures watertight unions/differences

// ---------- Helpers ----------
module rounded_rect_2d(l, w, r) {
  // Filleted rectangle using offset
  offset(r=r) offset(delta=-r)
    square([l, w], center=true);
}

module plate_body() {
  linear_extrude(height=T, center=true)
    rounded_rect_2d(L, W, corner_r);
}

// Shallow recessed pattern on a face (engraved into that face only)
module recess_pattern(zsign=+1) {
  // zsign: +1 engrave from top, -1 engrave from bottom
  // Place cutter so it intersects only the intended face region.
  zc = zsign*(T/2 - recess_depth/2);

  translate([0, 0, zc]) union() {
    // Cross
    cube([L - 2*recess_margin, recess_line_W, recess_depth + overlap], center=true);
    cube([recess_line_W, W - 2*recess_margin, recess_depth + overlap], center=true);

    // Inner frame (thin rectangular ring) to make relief clearly visible
    difference() {
      linear_extrude(height=recess_depth + overlap, center=true)
        offset(delta=recess_line_W/2)
          rounded_rect_2d(L - 2*recess_margin, W - 2*recess_margin, max(0, corner_r - recess_margin/2));
      linear_extrude(height=recess_depth + overlap + 2*overlap, center=true)
        rounded_rect_2d(L - 2*(recess_margin + recess_line_W), W - 2*(recess_margin + recess_line_W),
                        max(0, corner_r - recess_margin/2 - recess_line_W));
    }
  }
}

// Rectangular tabs protruding from the BOTTOM face (one opposite face)
module tab_row() {
  // Total span of tabs+gaps
  span = tab_count*tab_L + (tab_count-1)*tab_gap;

  // Center the row in X
  x0 = -span/2 + tab_L/2;

  // Place tabs near +Y edge, protruding downward from bottom face
  y_center = (W/2 - tab_edge_inset - tab_W/2);
  z_center = (-T/2 - tab_H/2 + overlap); // overlap into plate for connectivity

  for (i = [0:tab_count-1]) {
    translate([x0 + i*(tab_L + tab_gap), y_center, z_center])
      cube([tab_L, tab_W, tab_H], center=true);
  }
}

// ---------- Complete model ----------
module complete_model() {
  union() {
    difference() {
      plate_body();
      // Recesses on both large faces (decorative shallow relief)
      recess_pattern(+1);
      recess_pattern(-1);
    }
    // Tabs on one face only (bottom)
    tab_row();
  }
}

color([0.85, 0.85, 0.8]) complete_model();

// Compact offset mounting bracket with rounded-rectangle base and smooth curved elbow arm
// Units: mm (very small part; bbox target ~0.2 x 0.1 x 0.1)

// ---------- Parameters ----------
bbox_L = 0.20;
bbox_W = 0.10;
bbox_H = 0.10;

base_L = 0.085;
base_W = 0.060;
base_H = 0.030;
base_corner_r = 0.012;

arm_thk = 0.018;      // Z thickness of arm
arm_width = 0.030;    // Y width of arm
elbow_R = 0.030;      // bend radius (centerline-ish)

arm_rise_Z = 0.050;   // vertical rise from base top to arm top run center
arm_reach_X = 0.060;  // horizontal reach from base side to pad

pad_L = 0.030;
pad_W = 0.040;
pad_H = 0.020;

boss1_L = 0.020;
boss1_W = 0.030;
boss1_H = 0.010;

boss2_L = 0.018;
boss2_W = 0.028;
boss2_H = 0.010;

overlap = 0.001;
micro_fillet_r = 0.0015;

$fn = 48;

// ---------- Helpers ----------
module rounded_rect_prism(L, W, H, r) {
    // Robust rounded rectangle via hull of 4 cylinders
    r2 = min(r, min(L, W)/2 - 0.0001);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - r2), sy*(W/2 - r2), 0])
                cylinder(r=r2, h=H, center=false);
    }
}

module arm_path_2d() {
    // 2D centerline path in XZ plane: vertical up, quarter-arc, horizontal out
    // Start at (0,0) at base top surface.
    // End at (elbow_R + arm_reach_X, arm_rise_Z)
    // Ensure rise is compatible with elbow_R
    rise = max(arm_rise_Z, elbow_R + 0.0001);
    vlen = rise - elbow_R;

    // Build a polyline with arc approximation
    pts = concat(
        [[0, 0], [0, vlen]],
        [for (a = [0:6:90]) [elbow_R*(1 - cos(a)), vlen + elbow_R*sin(a)]],
        [[elbow_R + arm_reach_X, rise]]
    );

    polygon(points=pts);
}

module arm_solid() {
    // Sweep a rectangle (arm_width x arm_thk) along the 2D path by linear_extrude in Y,
    // then thicken in Z by offsetting the 2D path and extruding.
    // Approach: create 2D "tube" in XZ by offsetting the centerline path, then extrude in Y.
    rise = max(arm_rise_Z, elbow_R + 0.0001);
    vlen = rise - elbow_R;

    // Centerline polyline points (XZ)
    pts = concat(
        [[0, 0], [0, vlen]],
        [for (a = [0:6:90]) [elbow_R*(1 - cos(a)), vlen + elbow_R*sin(a)]],
        [[elbow_R + arm_reach_X, rise]]
    );

    // Make a 2D thickened path by hulling circles along the polyline
    module thick_path_2d(r) {
        hull() {
            for (p = pts)
                translate([p[0], p[1]]) circle(r=r);
        }
    }

    // Extrude along Y to get arm width; place so Y is centered at 0
    translate([0, 0, base_H])  // start at base top
        translate([0, 0, 0])
            rotate([90, 0, 0])  // extrude in Y by rotating XZ->XY then extruding Z
                linear_extrude(height=arm_width, center=true)
                    thick_path_2d(arm_thk/2);
}

module end_pad() {
    // Pad at end of arm, connected with slight overlap
    rise = max(arm_rise_Z, elbow_R + 0.0001);
    end_x = elbow_R + arm_reach_X;

    // Place pad so its top roughly aligns with arm top run; overlap into arm
    translate([ (base_L/2) + end_x - pad_L/2 + overlap, 0, base_H + rise - arm_thk/2 - pad_H/2 + overlap ])
        cube([pad_L, pad_W, pad_H], center=true);
}

module bosses() {
    rise = max(arm_rise_Z, elbow_R + 0.0001);
    end_x = elbow_R + arm_reach_X;

    // Boss near junction (on base top, at base right edge)
    translate([ base_L/2 - boss1_L/2 + overlap, 0, base_H + boss1_H/2 - overlap ])
        cube([boss1_L, boss1_W, boss1_H], center=true);

    // Boss near end pad (on top of arm near pad)
    translate([ base_L/2 + end_x - pad_L + boss2_L/2, 0, base_H + rise - arm_thk/2 - boss2_H/2 + overlap ])
        cube([boss2_L, boss2_W, boss2_H], center=true);
}

module base_block() {
    // Rounded-rectangle base block, centered at origin in XY, sitting on Z=0
    translate([0, 0, 0])
        rounded_rect_prism(base_L, base_W, base_H, base_corner_r);
}

module bracket_raw() {
    // Place arm so it starts at base right face, centered in Y, from base top
    // Arm path starts at X=0; shift to base right face with overlap
    translate([base_L/2 - overlap, 0, 0]) {
        arm_solid();
        end_pad();
        bosses();
    }

    base_block();
}

// Micro fillet via Minkowski (kept small to avoid bloating bbox too much)
minkowski() {
    bracket_raw();
    sphere(r=micro_fillet_r);
}

// Faceted lantern/pendant shell (single connected solid)
// Fixes: ensure a coherent faceted spherical/tapered shell, connected cap+tip+loop,
// and cutouts that carve into the shell (not fragment it).

// -------------------- Parameters --------------------
bbox_x = 0.02; //[0.01:0.04:0.001]
bbox_y = 0.02; //[0.01:0.04:0.001]
bbox_z = 0.05; //[0.025:0.1:0.001]

shell_t = 0.0012; //[0.0006:0.0024:0.0001]

taper_top_scale = 0.85; //[0.6:1.0:0.01]
taper_bottom_scale = 0.55; //[0.3:0.9:0.01]

tip_h = 0.008; //[0.004:0.016:0.0005]
tip_base_r = 0.006; //[0.003:0.012:0.0005]

cap_h = 0.004; //[0.002:0.008:0.0005]
cap_sides = 6; //[3:12:1]
cap_inset = 0.001; //[0.0005:0.002:0.0001]

hslot_len = 0.018; //[0.009:0.02:0.0005]
hslot_h = 0.004; //[0.002:0.008:0.0005]
hslot_depth = 0.012; //[0.003:0.02:0.0005]
hslot_z = 0.0; //[-0.01:0.01:0.0005]

vcut_count = 6; //[1:12:1]
vcut_w = 0.003; //[0.0015:0.006:0.0005]
vcut_len = 0.07; //[0.02:0.09:0.001]
vcut_depth = 0.02; //[0.004:0.03:0.0005]
vcut_tilt_deg = 0; //[-45:45:1]

dcut_count = 4; //[1:12:1]
dcut_w = 0.003; //[0.0015:0.006:0.0005]
dcut_len = 0.07; //[0.02:0.09:0.001]
dcut_depth = 0.02; //[0.004:0.03:0.0005]
dcut_tilt_deg = 25; //[0:60:1]

overlap = 0.001; //[0.0005:0.002:0.0001]
facet_scale_xy = 0.92; //[0.8:1.0:0.01]

loop_major_r = 0.003; //[0.0015:0.006:0.0005]
loop_minor_r = 0.0007; //[0.0004:0.0014:0.0001]
loop_hole_r  = 0.0009; //[0.0005:0.0018:0.0001]

// -------------------- Derived --------------------
outer_r = min(bbox_x, bbox_y, bbox_z) * 0.52;
z_top =  bbox_z/2;
z_bot = -bbox_z/2;
r_edge = min(bbox_x,bbox_y)/2;

// -------------------- Helpers --------------------
module faceted_ellipsoid(r=outer_r, fn=14) {
  scale([bbox_x/(2*r), bbox_y/(2*r), bbox_z/(2*r)])
    sphere(r=r, $fn=fn);
}

module tapered_profile() {
  cylinder(
    h=bbox_z + 2*overlap,
    r1=r_edge * taper_bottom_scale,
    r2=r_edge * taper_top_scale,
    center=true,
    $fn=12
  );
}

module shell_body() {
  // Coherent faceted spherical/tapered shell (hollow)
  difference() {
    intersection() {
      scale([facet_scale_xy, facet_scale_xy, 1])
        faceted_ellipsoid(fn=14);
      tapered_profile();
    }
    // inner cavity: slightly smaller and slightly more tapered to preserve wall
    intersection() {
      scale([facet_scale_xy, facet_scale_xy, 1])
        faceted_ellipsoid(r=max(outer_r - shell_t, outer_r*0.65), fn=14);
      scale([0.97,0.97,1])
        tapered_profile();
    }
  }
}

module top_cap_connected() {
  cap_r = max(r_edge - cap_inset, shell_t*2);
  // Overlap into shell to guarantee connectivity
  translate([0,0, z_top - cap_h/2 - overlap])
    cylinder(h=cap_h + 2*overlap, r=cap_r, center=true, $fn=cap_sides);
}

module bottom_tip_connected() {
  // Overlap into shell to guarantee connectivity
  translate([0,0, z_bot + tip_h/2 + overlap])
    cylinder(h=tip_h + 2*overlap, r1=tip_base_r, r2=0, center=true, $fn=4);
}

module mounting_loop_connected() {
  // Place loop so it intersects the cap (not floating)
  loop_z = z_top - cap_h + loop_minor_r; // intersects cap volume
  translate([0,0, loop_z])
    rotate([90,0,0])
      rotate_extrude($fn=64)
        translate([loop_major_r,0,0])
          circle(r=loop_minor_r, $fn=24);
}

module mounting_loop_hole() {
  loop_z = z_top - cap_h + loop_minor_r;
  translate([0,0, loop_z])
    rotate([90,0,0])
      cylinder(r=loop_hole_r,
               h=2*(loop_major_r + loop_minor_r + 2*overlap),
               center=true, $fn=40);
}

// -------------------- Cutouts / Grooves --------------------
module long_horizontal_slot_cut() {
  // Long horizontal recessed/through slot across the shell
  // Depth spans beyond body so it reliably cuts into the curved surface.
  translate([0,0,hslot_z])
    cube([hslot_len, max(hslot_depth, 2*r_edge + 2*overlap), hslot_h], center=true);
}

module radial_vertical_cutouts() {
  // Planar cutouts around the body; positioned to bite into shell (not separate parts)
  // Use a large Z length so they cut through the shell height.
  for (i=[0:vcut_count-1]) {
    ang = i*360/vcut_count;
    rotate([0,0,ang])
      rotate([0,vcut_tilt_deg,0])
        translate([r_edge - vcut_depth/2 + overlap, 0, 0])
          cube([vcut_depth, vcut_w, vcut_len], center=true);
  }
}

module radial_diagonal_cutouts() {
  for (i=[0:dcut_count-1]) {
    ang = i*360/dcut_count + 360/(2*dcut_count);
    rotate([0,0,ang])
      rotate([0,dcut_tilt_deg,45])
        translate([r_edge - dcut_depth/2 + overlap, 0, 0])
          cube([dcut_depth, dcut_w, dcut_len], center=true);
  }
}

module recessed_groove_rings() {
  // Recessed circumferential grooves (shallow pockets)
  groove_r = max(shell_t*0.55, 0.00035);
  major = r_edge * 0.78;

  for (zpos = [bbox_z*0.18, -bbox_z*0.12]) {
    translate([0,0,zpos])
      rotate_extrude($fn=84)
        translate([major,0,0])
          circle(r=groove_r, $fn=24);
  }
}

module symmetry_break_cut() {
  translate([bbox_x*0.18, 0, bbox_z*0.10])
    rotate([0,0,20])
      cube([bbox_x*0.25, bbox_y*0.18, bbox_z*0.18], center=true);
}

// -------------------- Final Model --------------------
module pendant_shell() {
  difference() {
    // One connected solid: shell + cap + tip + loop
    union() {
      shell_body();
      top_cap_connected();
      bottom_tip_connected();
      mounting_loop_connected();
    }

    // Openings / slots carved into the shell
    long_horizontal_slot_cut();
    radial_vertical_cutouts();
    radial_diagonal_cutouts();

    // Recessed grooves
    recessed_groove_rings();

    // Loop hole
    mounting_loop_hole();

    // Asymmetry pocket
    symmetry_break_cut();
  }
}

pendant_shell();

// U-shaped fork/clevis bracket with tapered end + transverse hex through-hole
// Bounding box target: 0.1 x 0.1 x 0.1 mm (model fits within these limits)
// Elongated along X

$fn = 96;

// -------------------- Overall bounds --------------------
L = 0.1;     // X (elongated)
W = 0.06;    // Y
H = 0.05;    // Z

// -------------------- Fork slot (through Z, open at tapered end) --------------------
slot_L = 0.075;
slot_W = 0.028;
slot_end_offset = 0.005;

// -------------------- End features --------------------
chamfer_L = 0.015;          // tapered/chamfered end length (at x=0)
round_end_R = 0.03;         // rounded end radius (at x=L)

// -------------------- Hex through-hole (axis along Y, near rounded end) --------------------
hex_flat_to_flat = 0.02;
hex_axis_offset_from_round_start = 0.02; // from x = (L - round_end_R)
hex_axis_z = H/2;

// -------------------- Robustness / overlap --------------------
eps = 0.0005;               // tiny numerical epsilon (mm)
over = 0.002;               // overlap for boolean robustness (mm)

// --- Helpers ---
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Convert flat-to-flat to circumradius for a regular hex
function hex_R_from_F(F) = F / sqrt(3);

// Regular hex polygon centered at origin
module hex2d(F) {
  R = hex_R_from_F(F);
  polygon(points=[ for(i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// Main body with rounded end (union of prism + cylindrical cap)
// Ensures overall X extent is exactly L (cap centered at x = L - round_end_R)
module body_with_round_end() {
  union() {
    // Main prism: x in [0, L-round_end_R]
    cube([L - round_end_R, W, H], center=false);

    // Rounded end cap: cylinder axis along Y, centered at x = L - round_end_R
    // Extends in X from (L - 2*round_end_R) to L
    translate([L - round_end_R, W/2, H/2])
      rotate([90, 0, 0])
        cylinder(r=round_end_R, h=W + 2*over, center=true);
  }
}

// CLEAR chamfer/taper at x=0: remove a wedge that slopes in Z from full height to 0
// Implemented as a non-degenerate polyhedron (no duplicated points).
module tapered_end_cut() {
  polyhedron(
    points=[
      // x=0 plane (collapsed to z=0 edge)
      [0,         0, 0],   // 0
      [0,         W, 0],   // 1

      // x=chamfer_L plane (full height)
      [chamfer_L, 0, 0],   // 2
      [chamfer_L, W, 0],   // 3
      [chamfer_L, 0, H],   // 4
      [chamfer_L, W, H]    // 5
    ],
    faces=[
      // bottom
      [0,2,3,1],
      // sloped top
      [0,1,5,4],
      // y=0 side
      [0,4,2],
      // y=W side
      [1,3,5],
      // x=chamfer_L side
      [2,4,5,3],
      // x=0 side (degenerate area but acceptable boundary)
      [0,1,3,2]
    ]
  );
}

// Through-slot: remove rectangular prism through Z, open at x=0 (starts at slot_end_offset)
module fork_slot_cut() {
  slot_x0 = clamp(slot_end_offset, 0, L);
  slot_x1 = clamp(slot_end_offset + slot_L, 0, L);
  slot_len = max(eps, slot_x1 - slot_x0);

  translate([slot_x0 - over, (W - slot_W)/2, -over])
    cube([slot_len + 2*over, slot_W, H + 2*over], center=false);
}

// Transverse hex through-hole (axis along Y), near rounded end
// FIX: ensure it is a TRUE through-hole across full width by extruding along Y
// and center it in Z so it is visible in orthographic views.
module hex_hole_cut() {
  // Desired center near rounded end
  x_center_raw = (L - round_end_R) + hex_axis_offset_from_round_start;

  // Keep the hex fully inside X bounds (avoid clipping at x=0 or x=L)
  Rhex = hex_R_from_F(hex_flat_to_flat);
  x_center = clamp(x_center_raw, Rhex + eps, L - Rhex - eps);

  // Through-hole along Y: extrude height >= W with overlap
  translate([x_center, W/2, clamp(hex_axis_z, Rhex + eps, H - Rhex - eps)])
    rotate([90, 0, 0])  // make extrude axis align with Y
      linear_extrude(height=W + 2*over, center=true, convexity=10)
        hex2d(hex_flat_to_flat);
}

// Final model (single connected solid)
difference() {
  body_with_round_end();

  // Cuts
  fork_slot_cut();
  hex_hole_cut();

  // Chamfer cut from the body to make the tapered end clearly visible
  // Extend in Y/Z via overlap to ensure clean subtraction.
  translate([0, -over, -over])
    scale([1, (W + 2*over)/W, (H + 2*over)/H])
      tapered_end_cut();
}

$fn = 32;

// -------------------- Parameters (mm) --------------------
bbox_x = 0.10;
bbox_y = 0.10;
bbox_z = 0.10;

plate_t = 0.008;

base_L = 0.080;
base_W = 0.080;

upright_H = 0.050;
upright_W = 0.080;

fillet_r = 0.020;

hole_d = 0.012;
hole_center_from_bend = 0.030;     // along Z from inside corner (bend)
hole_center_from_side = 0.040;     // along Y from -upright_W/2

flange_h = 0.010;
flange_t = 0.006;

outer_r = 0.003;                  // simplified: used only in 2D offset (no minkowski)

relief_L = 0.012;
relief_W = 0.012;
relief_depth = 0.004;

eps = 0.0008;

// -------------------- Helpers --------------------
module rrect2d(w, h, r) {
    rr = min(r, min(w,h)/2);
    offset(r=rr) square([w-2*rr, h-2*rr], center=true);
}

// Quarter-cylinder fillet (solid) along Y, placed in +X,+Z quadrant from origin
module internal_fillet_quarter(r, len_y) {
    intersection() {
        rotate([90,0,0]) cylinder(r=r, h=len_y, center=true);
        translate([r/2, 0, r/2]) cube([r, len_y + 2*eps, r], center=true);
    }
}

// -------------------- Main geometry --------------------
module base_plate_rounded() {
    // Rounded in XY only (fast): offset 2D then extrude
    translate([base_L/2, 0, 0])
        linear_extrude(height=plate_t)
            rrect2d(base_L, base_W, outer_r);
}

module upright_plate_rounded() {
    // Rounded in YZ only (fast): offset 2D then extrude along X
    translate([0, 0, upright_H/2])
        rotate([0,90,0])
            linear_extrude(height=plate_t)
                rrect2d(upright_W, upright_H, outer_r);
}

module edge_flange_lip() {
    // Thickened lip along +Y edge of base, sitting on top of base
    translate([base_L/2, base_W/2 - flange_t/2, plate_t - eps])
        cube([base_L, flange_t, flange_h], center=false);
}

module internal_fillet() {
    // Large internal fillet at inside corner between base (Z=0) and upright (X=0)
    translate([fillet_r, 0, fillet_r])
        internal_fillet_quarter(fillet_r, upright_W);
}

module bend_relief() {
    // Small relieved region near the bend (remove material)
    translate([relief_L/2 + eps, 0, relief_depth/2 + eps])
        cube([relief_L, relief_W, relief_depth], center=true);
}

module upright_through_hole() {
    // Through-hole in upright leg, drilled along X through the plate thickness
    y0 = -upright_W/2 + hole_center_from_side;
    z0 = hole_center_from_bend;
    translate([plate_t/2, y0, z0])
        rotate([0,90,0])
            cylinder(d=hole_d, h=plate_t + 6*eps, center=true);
}

// -------------------- Assembly --------------------
module raw_bracket() {
    union() {
        base_plate_rounded();
        upright_plate_rounded();
        internal_fillet();
        edge_flange_lip();
    }
}

module final_bracket() {
    difference() {
        raw_bracket();
        upright_through_hole();
        bend_relief();
    }
}

// -------------------- Render --------------------
final_bracket();

// Flat circular disk with thick outer rim, recessed inner face,
// five octagonal through-holes on a bolt circle, and a central square through-hole.

// ---------- Parameters (mm) ----------
thickness           = 10;     // overall plate thickness
outer_radius        = 20;     // outer disk radius
rim_radial_width    = 4;      // radial width of the thick rim (unrecessed ring)
recess_depth        = 3;      // depth of recessed inner face (from top surface)

bolt_circle_radius  = 11;     // radius of bolt circle for the 5 holes
oct_hole_flat_d     = 4;      // across-flats size of octagon hole
center_square_side  = 2;      // side length of central square through-hole

eps                 = 0.05;   // small overlap to ensure clean booleans
$fn                 = 180;    // smooth circle

// ---------- Derived ----------
inner_radius = outer_radius - rim_radial_width;

// Convert across-flats (2*apothem) to circumradius for regular octagon
// apothem a = R*cos(pi/8) => R = a / cos(pi/8)
oct_R = (oct_hole_flat_d/2) / cos(180/8);

// ---------- Helpers ----------
module octagon2d(R){
    polygon(points=[
        for (i=[0:7]) [ R*cos(i*45), R*sin(i*45) ]
    ]);
}

module oct_hole(){
    linear_extrude(height=thickness + 2*eps, center=true)
        octagon2d(oct_R);
}

module center_square_hole(){
    cube([center_square_side, center_square_side, thickness + 2*eps], center=true);
}

module bolt_circle_holes_5(){
    for (i=[0:4])
        rotate([0,0,i*360/5])
            translate([bolt_circle_radius, 0, 0])
                oct_hole();
}

// ---------- Main solid ----------
module hub_plate(){
    difference(){
        // Base disk
        cylinder(r=outer_radius, h=thickness, center=true);

        // Recessed inner face (remove material from the TOP only)
        // Leaves an outer rim of full thickness.
        translate([0,0, thickness/2 - recess_depth/2 + eps/2])
            cylinder(r=inner_radius, h=recess_depth + eps, center=true);

        // Through-holes
        bolt_circle_holes_5();
        center_square_hole();
    }
}

// ---------- Output ----------
hub_plate();

// Low-poly armored vehicle / tank-like platform
// Fixed: non-empty geometry, connected parts, clearly cylindrical end pods,
// distinct faceted turret, visible barrel, fins connected.
// Note: A true 0.0mm thickness bounding box is not physically meaningful in 3D;
// this model uses a small but nonzero Z thickness while keeping overall size ~0.1mm.

$fn = 18;

// Target overall envelope (approx)
L = 0.1;
W = 0.1;
H = 0.04;

// Fit/connection
overlap = 0.001;

// Main hull (elongated along X)
hull_L = 0.072;
hull_W = 0.034;
hull_H = 0.018;

// Cylindrical end pods
pod_R   = 0.017;
pod_len = 0.016;

// Turret / roof (faceted)
turret_L = 0.040;
turret_W = 0.026;
turret_H = 0.016;

// Barrel (protruding from +X end)
barrel_R = 0.004;
barrel_L = 0.020;

// Mid fins / winglets
fin_L = 0.012;
fin_W = 0.010;
fin_H = 0.004;

// Small top greebles
greeble_R = 0.0012;
greeble_H = 0.0015;

// --- Helpers ---
module hull_main() {
  cube([hull_L, hull_W, hull_H], center=true);
}

module end_pod(sign=1) {
  // Centered on hull mid-height so it reads as cylindrical in ortho views
  translate([sign*(hull_L/2 + pod_len/2 - overlap), 0, 0])
    rotate([0, 90, 0])
      cylinder(r=pod_R, h=pod_len, center=true);
}

module turret_roof() {
  // Place turret on top of hull with overlap for connectivity
  zc = hull_H/2 + turret_H/2 - overlap;

  translate([0, 0, zc])
    linear_extrude(height=turret_H, center=true)
      polygon(points=[
        [-turret_L/2, -turret_W/2],
        [ turret_L/2, -turret_W/2],
        [ turret_L/2 - turret_L*0.22, 0],
        [ turret_L/2,  turret_W/2],
        [-turret_L/2,  turret_W/2],
        [-turret_L/2 + turret_L*0.22, 0]
      ]);
}

module barrel() {
  // Attach to front pod/hull end (+X) and protrude outward
  // Inner end slightly inside the front pod for a solid connection.
  x_center = (hull_L/2 + pod_len - overlap) + barrel_L/2 - overlap;
  z_center = 0; // centered vertically for visibility in side views

  translate([x_center, 0, z_center])
    rotate([0, 90, 0])
      cylinder(r=barrel_R, h=barrel_L, center=true);
}

module mid_fin(side=1) {
  // Side fins connected to hull sides
  y_center = side*(hull_W/2 + fin_W/2 - overlap);
  z_center = 0;

  translate([0, y_center, z_center])
    cube([fin_L, fin_W, fin_H], center=true);
}

module surface_greebles() {
  // Small cylinders on top of hull (connected)
  zc = hull_H/2 + greeble_H/2 - overlap;
  translate([-hull_L*0.18,  hull_W*0.18, zc])
    cylinder(r=greeble_R, h=greeble_H, center=true);
  translate([ hull_L*0.18, -hull_W*0.18, zc])
    cylinder(r=greeble_R, h=greeble_H, center=true);
}

// --- Final model (single connected solid) ---
union() {
  hull_main();
  end_pod( 1);
  end_pod(-1);
  turret_roof();
  barrel();
  mid_fin( 1);
  mid_fin(-1);
  surface_greebles();
}

// Parameters
L = 80; //[40:160:1]
W = 60; //[30:120:1]
T = 40; //[20:80:1]
hex_flat_to_flat = 18; //[9:36:1]
hex_center_x = 18; //[9:36:1]
hex_center_y = 30; //[15:45:1]
min_edge_margin = 6; //[3:12:1]
neck_width = 28; //[14:56:1]
small_lobe_length = 28; //[14:56:1]
large_lobe_length = 52; //[26:104:1]
large_lobe_max_width = 60; //[30:120:1]
outline_corner_chamfer = 4; //[2:8:1]
eps_overlap = 1; //[0.5:2:0.5]
edge_fillet_approx = 2; //[1:4:0.5]

// Helper function to create a hexagon
module hexagon(size) {
  polygon(points=[
    [size/2, 0],
    [size/4, size*0.4330127019],
    [-size/4, size*0.4330127019],
    [-size/2, 0],
    [-size/4, -size*0.4330127019],
    [size/4, -size*0.4330127019]
  ]);
}

// Base shapes
module plate_body_two_lobe_outline() {
  linear_extrude(height=T, center=true)
    polygon(points=[
      [outline_corner_chamfer, W/2 - neck_width/2 + outline_corner_chamfer],
      [small_lobe_length - outline_corner_chamfer, W/2 - neck_width/2 + outline_corner_chamfer],
      [small_lobe_length + outline_corner_chamfer, W/2 - neck_width/2 + 2*outline_corner_chamfer],
      [L - large_lobe_length - outline_corner_chamfer, W/2 - large_lobe_max_width/2 + outline_corner_chamfer],
      [L - outline_corner_chamfer, W/2 - large_lobe_max_width/2 + 2*outline_corner_chamfer],
      [L - outline_corner_chamfer, W/2 + large_lobe_max_width/2 - 2*outline_corner_chamfer],
      [L - large_lobe_length + outline_corner_chamfer, W/2 + large_lobe_max_width/2 - outline_corner_chamfer],
      [small_lobe_length + outline_corner_chamfer, W/2 + neck_width/2 - 2*outline_corner_chamfer],
      [small_lobe_length - outline_corner_chamfer, W/2 + neck_width/2 - outline_corner_chamfer],
      [outline_corner_chamfer, W/2 + neck_width/2 - outline_corner_chamfer],
      [0, W/2 + neck_width/2 - 2*outline_corner_chamfer],
      [0, W/2 - neck_width/2 + 2*outline_corner_chamfer]
    ]);
}

module necked_transition_between_lobes() {
  translate([small_lobe_length, W/2, 0])
    cube([2*outline_corner_chamfer + eps_overlap, neck_width, T], center=true);
}

module through_hex_hole() {
  translate([hex_center_x, hex_center_y, 0])
    linear_extrude(height=T, center=true)
      hexagon(hex_flat_to_flat);
}

module engraving_or_marking() {
  translate([L/2, W/2, 0])
    cube([eps_overlap, eps_overlap, eps_overlap], center=true);
}

module edge_fillet_approximation() {
  sphere(r=edge_fillet_approx, center=true);
}

// Operations
module union_outline_with_neck() {
  union() {
    plate_body_two_lobe_outline();
    necked_transition_between_lobes();
  }
}

module plate_minus_hex_hole() {
  difference() {
    union_outline_with_neck();
    through_hex_hole();
  }
}

module edge_fillet_approximation_minkowski() {
  minkowski() {
    plate_minus_hex_hole();
    edge_fillet_approximation();
  }
}

module final_union_no_text() {
  union() {
    edge_fillet_approximation_minkowski();
    engraving_or_marking();
  }
}

// Final output
final_union_no_text();

// Compact symmetric bracket-like block with wedge wings, stepped pockets, V-notch, and diamond through-holes.
// Fixes:
// - Use realistic mm-scale dimensions (avoid near-zero that can render "blank").
// - Ensure wings are connected (no accidental rotation/offset separation).
// - Make V-notch truly V-shaped in top/bottom by cutting a triangular prism from the -Y edge.
// - Keep all translations dimension-derived.

$fn = 64;

// -------------------- Parameters (mm) --------------------
body_x = 32;
body_y = 28;
body_z = 12;

wing_span_x_each = 19;     // extension beyond body on each side
wing_y_root      = body_y; // width at body interface
wing_y_tip       = 45;     // width at outer tip
wing_z           = body_z;

v_notch_depth_y   = 10;    // how far the V goes inward from -Y edge
v_notch_opening_x = 18;    // opening width along X at the edge

step_depth_x  = 6;         // stepped face pocket depth (from +X side)
step_height_z = 5;         // pocket height near top

slot_count     = 3;
slot_x         = 16;
slot_y         = 6;
slot_depth_z   = 7;
slot_spacing_y = 8;

micro_pocket_x = 6;
micro_pocket_y = 4;
micro_pocket_z = 4;

diamond_hole_d = 6;        // square size (rotated 45° to look diamond)
overlap        = 0.2;      // small overlap to avoid coincident faces

// -------------------- Derived --------------------
total_x = body_x + 2*wing_span_x_each;
total_y = max(body_y, wing_y_tip);
total_z = body_z;

// -------------------- Helpers --------------------
module wing_wedge(side=1) {
    // side: +1 right, -1 left
    // Wedge in XY, extruded in Z, attached flush to body side with overlap.
    // Polygon spans x=[0..wing_span_x_each] so we place its x=0 edge at body side.
    translate([side*(body_x/2 - overlap), 0, 0])
        mirror([side==-1 ? 1 : 0, 0, 0])  // mirror for left side
            linear_extrude(height=wing_z, center=true)
                polygon(points=[
                    [0,               -wing_y_root/2],
                    [wing_span_x_each, -wing_y_tip/2],
                    [wing_span_x_each,  wing_y_tip/2],
                    [0,                wing_y_root/2]
                ]);
}

module v_notch_cut() {
    // True V-shaped notch along the -Y edge, visible in top/bottom.
    // Cut a triangular prism that extends inward (+Y) by v_notch_depth_y.
    // Triangle defined in XY, extruded through Z.
    translate([0, 0, 0])
        linear_extrude(height=total_z + 2*overlap, center=true)
            polygon(points=[
                [-v_notch_opening_x/2, -total_y/2 - overlap],
                [ v_notch_opening_x/2, -total_y/2 - overlap],
                [0,                    -total_y/2 + v_notch_depth_y]
            ]);
}

module top_step_pocket() {
    // Pocket on +X face near top (stepped face)
    translate([ (body_x/2 - step_depth_x/2 + overlap/2), 0,
                (body_z/2 - step_height_z/2 + overlap/2) ])
        cube([step_depth_x + overlap, body_y + 2*overlap, step_height_z + overlap], center=true);
}

module slots_pockets() {
    // Three rectangular slots/pockets cut from top surface
    zpos = (body_z/2 - slot_depth_z/2 + overlap/2);
    for (i = [0:slot_count-1]) {
        y = (i - (slot_count-1)/2) * slot_spacing_y;
        translate([0, y, zpos])
            cube([slot_x, slot_y, slot_depth_z + overlap], center=true);
    }

    // Small micro pockets on bottom surface
    zneg = -(body_z/2 - micro_pocket_z/2 + overlap/2);
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(body_x/4), sy*(body_y/4), zneg])
            cube([micro_pocket_x, micro_pocket_y, micro_pocket_z + overlap], center=true);
    }
}

module diamond_through_holes() {
    // Two diamond/square through-holes on the sloped wing regions.
    // Place them outside the body, within each wing.
    xh = body_x/2 + wing_span_x_each*0.60;
    yh = wing_y_tip*0.22;

    for (sx = [-1, 1]) {
        translate([sx*xh, yh, 0])
            rotate([0,0,45])
                cube([diamond_hole_d, diamond_hole_d, total_z + 4*overlap], center=true);
    }
}

// -------------------- Main Model --------------------
module final_model() {
    difference() {
        union() {
            // Central body
            cube([body_x, body_y, body_z], center=true);

            // Connected symmetric wings
            wing_wedge(+1);
            wing_wedge(-1);
        }

        // V-notch opening
        v_notch_cut();

        // Stepped face pocket
        top_step_pocket();

        // Slots and micro pockets
        slots_pockets();

        // Diamond through-holes
        diamond_through_holes();
    }
}

final_model();

$fn = 128;

// Units: meters in parameters below; convert to mm for modeling
mm = 1000;

// -------------------- Parameters (as given) --------------------
disk_d = 0.03;
disk_t = 0.012;

rim_radial_thk = 0.003;
rim_extra_t = 0.004;

hub_d = 0.012;
hub_h = 0.004;

hex_flat_to_flat = 0.006;
hex_clearance = 0.0002;

post_d = 0.006;
post_h = 0.004;

cutout_count = 4;
cutout_w = 0.004;
cutout_h = 0.004;
cutout_depth = 0.012;
cutout_radial_pos = 0.012;
cutout_corner_r = 0.001;

overlap = 0.001; // meters

// -------------------- Derived (mm) --------------------
disk_r      = (disk_d*mm)/2;
disk_h      =  disk_t*mm;

rim_thk_r   =  rim_radial_thk*mm;
rim_h       = (disk_t + rim_extra_t)*mm;

hub_r       = (hub_d*mm)/2;
hub_hh      =  hub_h*mm;

post_r      = (post_d*mm)/2;
post_hh     =  post_h*mm;

cut_w       =  cutout_w*mm;     // tangential width
cut_len     =  cutout_h*mm;     // radial length
cut_hh      =  cutout_depth*mm; // cutter height
cut_rpos    =  cutout_radial_pos*mm;
cut_cr      =  cutout_corner_r*mm;

eps         =  overlap*mm;      // mm overlap for robust unions/differences

// Hex sizing: for a regular hex, flat-to-flat = R * sqrt(3) where R is circumradius
hex_ftf     = (hex_flat_to_flat + hex_clearance)*mm;
hex_R       = hex_ftf / sqrt(3);

// -------------------- Helpers --------------------
module rounded_rect2d(w, h, r){
    r2 = min(r, min(w,h)/2);
    hull(){
        for (sx=[-1,1], sy=[-1,1])
            translate([sx*(w/2 - r2), sy*(h/2 - r2)]) circle(r=r2);
    }
}

module curved_perimeter_cutout(){
    // Curved rectangular slot near perimeter:
    // rounded rectangle intersected with an annulus band to curve inner/outer edges.
    intersection(){
        translate([cut_rpos, 0, 0])
            linear_extrude(height = rim_h + 2*eps, center=true)
                rounded_rect2d(cut_len, cut_w, cut_cr);

        linear_extrude(height = rim_h + 2*eps, center=true)
            difference(){
                circle(r = disk_r - rim_thk_r/2);
                circle(r = disk_r - rim_thk_r - cut_len - rim_thk_r/2);
            }
    }
}

module four_cutouts(){
    for(i=[0:cutout_count-1])
        rotate([0,0,i*360/cutout_count]) curved_perimeter_cutout();
}

module base_disk(){
    cylinder(r=disk_r, h=disk_h, center=true);
}

module outer_rim(){
    // Taller outer band to make rim thickness visible in side view.
    difference(){
        cylinder(r=disk_r, h=rim_h, center=true);
        cylinder(r=disk_r - rim_thk_r, h=rim_h + 2*eps, center=true);
    }
}

module hub(){
    // Raised hub on +Z face; increase step visibility by lifting it above the rim top.
    // Ensure solid connection by overlapping into the rim/disk by eps.
    // Place hub so its bottom is slightly below the rim top.
    z0 = (rim_h/2) - eps;                 // hub bottom (slightly into rim)
    zc = z0 + hub_hh/2;                   // hub center
    translate([0,0,zc])
        cylinder(r=hub_r, h=hub_hh, center=true);
}

module post(){
    // Short shaft on -Z face; make it clearly protrude from one face.
    // Ensure solid connection by overlapping into the rim/disk by eps.
    // Place post so its top is slightly above the rim bottom.
    z1 = -(rim_h/2) + eps;                // post top (slightly into rim)
    zc = z1 - post_hh/2;                  // post center
    translate([0,0,zc])
        cylinder(r=post_r, h=post_hh, center=true);
}

module hex_bore(){
    // Through hex bore across entire part (rim + hub + post), with margin.
    total_h = rim_h + hub_hh + post_hh + 8*eps;
    cylinder(r=hex_R, h=total_h, center=true, $fn=6);
}

// -------------------- Model --------------------
difference(){
    union(){
        base_disk();
        outer_rim();
        hub();
        post();
    }

    // Cutouts and bore
    four_cutouts();
    hex_bore();
}

// Stepped L-shaped block with prominent side notch + rear U-shaped fork pocket
// Bounding box: 0.1 x 0.1 x 0.1 mm
// Simplified for reliable/fast rendering (removed complex chamfer wedges)

$fn = 16;

bbox_X = 0.1;
bbox_Y = 0.1;
bbox_Z = 0.1;

// L thicknesses (legs)
legX = 0.035;   // thickness of vertical leg in X
legY = 0.035;   // thickness of horizontal leg in Y

// Step (top relief in the inner corner)
step_h = 0.03;

// Large rectangular side notch (cut through full Z)
side_notch_w  = 0.045;  // depth into X from +X side
side_notch_y  = 0.060;  // length along Y
side_notch_y0 = 0.020;  // start offset from -Y
side_notch_z  = bbox_Z + 0.01; // through all Z with margin

// Rear U-pocket (open to +Y, visible in BACK view as a forked pocket)
u_depth    = 0.040;  // pocket depth from +Y face inward
u_outer_x  = 0.070;  // overall width of pocket in X
u_outer_z  = 0.070;  // overall height of pocket in Z
u_wall     = 0.012;  // side walls thickness (fork tines)
u_floor    = 0.012;  // bottom floor thickness (in Z)
u_center_x = 0.0;
u_z0       = -bbox_Z/2; // start at bottom

eps = 0.0005;

// ---------- Main geometry ----------
module L_solid() {
    // Union of two overlapping legs
    union() {
        // horizontal leg (thin in Y)
        translate([0, -bbox_Y/2 + legY/2, 0])
            cube([bbox_X, legY, bbox_Z], center=true);

        // vertical leg (thin in X)
        translate([-bbox_X/2 + legX/2, 0, 0])
            cube([legX, bbox_Y, bbox_Z], center=true);
    }
}

module step_cut() {
    // Remove a top step in the inner corner region
    x_len = (bbox_X - legX) + 2*eps;
    y_len = (bbox_Y - legY) + 2*eps;
    z_len = step_h + 2*eps;

    translate([(-bbox_X/2 + legX) + x_len/2 - eps,
               (-bbox_Y/2 + legY) + y_len/2 - eps,
               bbox_Z/2 - z_len/2 + eps])
        cube([x_len, y_len, z_len], center=true);
}

module side_notch_cut() {
    // Side notch from +X face, through full Z
    x_len = side_notch_w + 2*eps;
    y_len = side_notch_y + 2*eps;
    z_len = side_notch_z;

    translate([bbox_X/2 - x_len/2 + eps,
               -bbox_Y/2 + side_notch_y0 + y_len/2 - eps,
               0])
        cube([x_len, y_len, z_len], center=true);
}

module rear_U_cut() {
    // U-shaped recess open to +Y: subtract inner from outer to leave two side walls + floor
    outer_x = u_outer_x;
    outer_z = u_outer_z;

    inner_x = max(outer_x - 2*u_wall, 0.001);
    inner_z = max(outer_z - u_floor, 0.001);

    y_center = bbox_Y/2 - u_depth/2 + eps;

    // Outer pocket volume
    translate([u_center_x, y_center, u_z0 + outer_z/2])
    difference() {
        cube([outer_x, u_depth + 2*eps, outer_z], center=true);

        // Inner removal (slightly longer in Y to ensure clean opening)
        translate([0, 0, (u_floor/2) + (inner_z/2)])
            cube([inner_x, u_depth + 4*eps, inner_z + 2*eps], center=true);
    }
}

module model() {
    difference() {
        L_solid();
        step_cut();
        side_notch_cut();
        rear_U_cut();
    }
}

model();

// Thin mounting plate with rounded corners, 4 corner holes,
// 2 opposite diamond tabs with holes, and a raised faceted octagonal bezel
// around a recessed rectangular pocket. Single connected solid.

// ---------------- Parameters ----------------
bbox_L = 0.27; //[0.135:0.54:0.001]
bbox_W = 0.16; //[0.08:0.32:0.001]
bbox_H = 0.03; //[0.015:0.06:0.001]

plate_thk = 0.018; //[0.009:0.036:0.001]
corner_R = 0.012; //[0.006:0.024:0.001]

corner_hole_d = 0.01; //[0.005:0.02:0.001]
corner_hole_edge_offset_L = 0.02; //[0.01:0.04:0.001]
corner_hole_edge_offset_W = 0.02; //[0.01:0.04:0.001]

tab_span_out = 0.02; //[0.01:0.04:0.001]
tab_diamond_L = 0.04; //[0.02:0.08:0.001]
tab_diamond_W = 0.03; //[0.015:0.06:0.001]
tab_hole_d = 0.01; //[0.005:0.02:0.001]

bezel_outer_flat_d = 0.09; //[0.045:0.18:0.001]
bezel_inner_flat_d = 0.065; //[0.0325:0.13:0.001]
bezel_h = 0.008; //[0.004:0.016:0.001]

pocket_L = 0.09; //[0.045:0.18:0.001]
pocket_W = 0.05; //[0.025:0.1:0.001]
pocket_depth = 0.006; //[0.003:0.012:0.001]

eps_overlap = 0.001; //[0.0005:0.002:0.0005]
hole_extra_h = 0.01; //[0.005:0.02:0.001]
bezel_facet_scale = 0.92; //[0.85:0.98:0.01]

$fn = 64;

// ---------------- Helpers ----------------
module rounded_rect_2d(L, W, R) {
  // Robust rounded rectangle (2D) using hull of circles
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(L/2 - R), sy*(W/2 - R)]) circle(r=R);
  }
}

module oct_2d(flat_d) {
  // Octagon defined by "flat-to-flat" distance along X/Y
  polygon(points=[
    [ flat_d/2, 0],
    [ flat_d/4,  flat_d/4],
    [ 0,  flat_d/2],
    [-flat_d/4,  flat_d/4],
    [-flat_d/2, 0],
    [-flat_d/4, -flat_d/4],
    [ 0, -flat_d/2],
    [ flat_d/4, -flat_d/4]
  ]);
}

module plate_solid() {
  // Single connected base plate + integrated tabs (same thickness)
  union() {
    linear_extrude(height=plate_thk, center=true)
      rounded_rect_2d(bbox_L, bbox_W, corner_R);

    // Tabs centered on midpoints of two opposite sides (along +/-Y)
    for (sy = [-1, 1]) {
      translate([0, sy*(bbox_W/2 + tab_span_out - eps_overlap), 0])
        linear_extrude(height=plate_thk, center=true)
          polygon(points=[
            [ tab_diamond_L/2, 0],
            [ 0,  tab_diamond_W/2],
            [-tab_diamond_L/2, 0],
            [ 0, -tab_diamond_W/2]
          ]);
    }
  }
}

module bezel_ring_faceted() {
  // Raised octagonal ring with a faceted top (via slight scale taper)
  // Outer ring minus inner opening; then intersect with a tapered prism to create facets.
  zc = plate_thk/2 + bezel_h/2 - eps_overlap;

  translate([0,0,zc])
  intersection() {
    // Ring volume
    difference() {
      linear_extrude(height=bezel_h, center=true) oct_2d(bezel_outer_flat_d);
      linear_extrude(height=bezel_h + hole_extra_h, center=true) oct_2d(bezel_inner_flat_d);
    }

    // Facet shaper: tapered octagonal prism (creates planar facets on the ring)
    linear_extrude(height=bezel_h, center=true, scale=bezel_facet_scale)
      oct_2d(bezel_outer_flat_d);
  }
}

module corner_holes_4x() {
  for (sx = [-1, 1], sy = [-1, 1]) {
    translate([
      sx*(bbox_L/2 - corner_hole_edge_offset_L),
      sy*(bbox_W/2 - corner_hole_edge_offset_W),
      0
    ])
      cylinder(d=corner_hole_d, h=plate_thk + bezel_h + hole_extra_h, center=true);
  }
}

module tab_holes_2x() {
  for (sy = [-1, 1]) {
    translate([0, sy*(bbox_W/2 + tab_span_out - eps_overlap), 0])
      cylinder(d=tab_hole_d, h=plate_thk + hole_extra_h, center=true);
  }
}

module pocket_cutter() {
  // Recessed rectangular pocket from the top face into the plate
  // Place cutter so it starts at top surface and goes down pocket_depth.
  translate([0, 0, plate_thk/2 - pocket_depth/2 + eps_overlap])
    cube([pocket_L, pocket_W, pocket_depth + hole_extra_h], center=true);
}

// ---------------- Final Model ----------------
difference() {
  union() {
    plate_solid();
    bezel_ring_faceted();
  }

  // Holes
  corner_holes_4x();
  tab_holes_2x();

  // Central recessed pocket
  pocket_cutter();
}

// Thin elongated plate with rounded ends, one large octagonal through-hole near one end,
// and four evenly spaced T-shaped through-slots along the centerline.

// ---------- Parameters (mm) ----------
L = 110;                 // overall length
W = 40;                  // overall width
T = 3;                   // thickness (plate-like)

end_radius = W/2;        // rounded ends (capsule)

hole_center_x_from_end = 18;   // from left end along length
oct_hole_flat_d = 18;          // across flats of octagon

t_count = 4;
t_pitch = 18;            // spacing between T-slots
t_stem_w = 4;
t_stem_l = 12;
t_head_w = 12;
t_head_l = 4;
t_start_x = 40;          // from left end to first T-slot center

eps_overlap = 0.2;       // for clean through-cuts

$fn = 96;

// ---------- Helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Regular octagon: given across-flats D, circumradius R = D/(2*cos(22.5))
function oct_R_from_flats(D) = D / (2 * cos(22.5));

// ---------- Base geometry ----------
module capsule_plate_2d(len, wid) {
    // 2D capsule (rounded rectangle) centered at origin
    hull() {
        translate([-(len/2 - wid/2), 0]) circle(r=wid/2);
        translate([ (len/2 - wid/2), 0]) circle(r=wid/2);
    }
}

module plate_outer() {
    linear_extrude(height=T, center=true)
        capsule_plate_2d(L, W);
}

// ---------- Cutouts ----------
module octagonal_through_hole() {
    // Place near LEFT end, on centerline
    R = oct_R_from_flats(oct_hole_flat_d);
    x = -L/2 + hole_center_x_from_end;
    translate([x, 0, 0])
        rotate([0, 0, 22.5])  // flat side roughly horizontal
            linear_extrude(height=T + 2*eps_overlap, center=true)
                circle(r=R, $fn=8);
}

module t_slot_2d() {
    // T shape centered at origin, stem extends in +X direction
    union() {
        // stem
        translate([t_stem_l/2, 0])
            square([t_stem_l, t_stem_w], center=true);
        // head at the far end of stem
        translate([t_stem_l - t_head_l/2, 0])
            square([t_head_l, t_head_w], center=true);
    }
}

module t_slot_through(x_center) {
    translate([x_center, 0, 0])
        linear_extrude(height=T + 2*eps_overlap, center=true)
            t_slot_2d();
}

module all_cutouts() {
    union() {
        octagonal_through_hole();

        // Evenly spaced T-slots along centerline
        for (i = [0 : t_count-1]) {
            x_i = -L/2 + t_start_x + i*t_pitch;
            t_slot_through(x_i);
        }
    }
}

// ---------- Final model ----------
difference() {
    plate_outer();
    all_cutouts();
}

// Flat toothed rosette / gear-like disk (solid, no cutouts)
// Target bbox ~0.1 x 0.1 x thin Z

$fn = 180;

// Parameters (mm)
bbox_xy      = 0.10;
thickness_z  = 0.03;

tooth_count  = 36;          // many evenly spaced teeth
outer_radius = bbox_xy/2;   // tooth tip radius
root_radius  = outer_radius * 0.82;  // base disk radius (between teeth)

// Tooth shape control (2D)
tooth_angle_frac = 0.55;    // fraction of pitch occupied by tooth (0..1)
tooth_overlap    = outer_radius * 0.01; // small overlap into root for watertight union

module rosette_2d() {
    pitch = 360 / tooth_count;
    half_tooth = (pitch * tooth_angle_frac) / 2;

    union() {
        // Base circular disk (ensures round body, not polygonal)
        circle(r = root_radius);

        // Triangular teeth (2D), then extruded uniformly
        for (i = [0:tooth_count-1]) {
            rotate(i * pitch)
                polygon(points = [
                    // two base points slightly inside root radius for solid connectivity
                    [root_radius - tooth_overlap, 0],
                    [outer_radius * cos( half_tooth), outer_radius * sin( half_tooth)],
                    [outer_radius * cos(-half_tooth), outer_radius * sin(-half_tooth)]
                ]);
        }
    }
}

linear_extrude(height = thickness_z, center = true, convexity = 10)
    rosette_2d();

// Parameters
bbox_x = 0.01; //[0.005:0.02:0.0001]
bbox_y = 0.01; //[0.005:0.02:0.0001]
bbox_z = 0.03; //[0.015:0.06:0.0001]
main_D = 0.01; //[0.005:0.02:0.0001]
main_H = 0.022; //[0.011:0.044:0.0001]
boss_D = 0.006; //[0.003:0.012:0.0001]
boss_H = 0.008; //[0.004:0.016:0.0001]
hole_square_W = 0.003; //[0.0015:0.006:0.0001]
rim_amp = 0.0006; //[0.0003:0.0012:0.00001]
rim_teeth = 12; //[6:24:1]
facet_sides = 8; //[6:16:1]
shoulder_H = 0.002; //[0.001:0.004:0.0001]
overlap = 0.0005; //[0.0002:0.001:0.0001]
chamfer_H = 0.0006; //[0.0003:0.0012:0.00001]
fillet_r = 0.0004; //[0.0002:0.0008:0.00001]
knurl_depth = 0.00025; //[0.0001:0.0005:0.00001]
knurl_count = 12; //[6:24:1]

// Base Shapes
module main_barrel() {
