// Rectangular prismatic block with clipped corners on top/bottom faces,
// centered THROUGH octagonal bore opening on the SMALL side faces (YZ faces),
// plus top recessed slot and four corner recesses.
//
// Structural fixes applied:
// - Ensure octagonal bore is truly through along X and visible on left/right faces
// - Ensure slot + 4 square recesses are on the TOP face (Z+), not on side faces
// - Robust boolean overlaps via eps; all features intersect the base solid

// Parameters (mm)  (kept as provided; note these are extremely small)
L = 0.05; //[0.025:0.1:0.001]
W = 0.03; //[0.015:0.06:0.001]
H = 0.03; //[0.015:0.06:0.001]

chamfer = 0.003; //[0.0015:0.006:0.0005]

bore_flat_d = 0.012; //[0.006:0.024:0.0005]   // across flats
slot_L = 0.038; //[0.019:0.076:0.001]
slot_W = 0.004; //[0.002:0.008:0.0005]
slot_depth = 0.0015; //[0.0005:0.003:0.00025]

sq_size = 0.004; //[0.002:0.008:0.0005]
sq_depth = 0.001; //[0.0005:0.002:0.00025]
sq_offset_x = 0.018; //[0.009:0.036:0.001]
sq_offset_y = 0.01; //[0.005:0.02:0.001]

// Use a tiny epsilon for robust booleans at this scale
eps = 0.0005; //[0.00025:0.002:0.00025]

$fn = 64;

// --- Helpers ---
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Regular octagon sized by across-flats (AF)
module octagon2d_by_af(af){
  n = 8;
  // AF = 2*apothem = 2*R*cos(180/n)  => R = AF/(2*cos(180/n))
  R = af / (2*cos(180/n));
  polygon(points=[ for(i=[0:n-1]) [ R*cos(360*i/n), R*sin(360*i/n) ] ]);
}

// Main block with clipped corners visible in top/bottom views
// Implemented as 2D corner cuts extruded through full height (Z)
module main_block_with_clipped_corners(){
  c = clamp(chamfer, 0, min(L,W)/2 - eps);

  linear_extrude(height=H, center=true)
    difference(){
      square([L, W], center=true);

      // Clip 4 corners (45°) on the large faces silhouette (XY)
      for (sx=[-1,1], sy=[-1,1])
        translate([sx*(L/2 - c/2), sy*(W/2 - c/2)])
          rotate(45)
            square([c, c], center=true);
    }
}

// Through octagonal bore centered on the smaller side faces (YZ faces).
// Axis along X so it opens on left/right faces; extend beyond body for clean cut.
module through_octagonal_bore(){
  // Extrude along X by rotating an XY-profile into YZ and extruding in Z
  // rotate([0,90,0]) makes linear_extrude's Z axis align with global X.
  rotate([0,90,0])
    linear_extrude(height=L + 2*eps, center=true)
      octagon2d_by_af(bore_flat_d);
}

// Top recessed long slot (subtract), running along length (X) on TOP face (Z+)
module top_recessed_long_slot(){
  d = clamp(slot_depth, 0, H - 2*eps);
  // Place so it cuts into the top surface only
  zc = (H/2) - (d/2) + eps;  // slight overlap into the solid
  translate([0, 0, zc])
    cube([clamp(slot_L, 0, L - 2*eps), clamp(slot_W, 0, W - 2*eps), d + 2*eps], center=true);
}

// Four top corner square recesses (subtract) on TOP face (Z+)
module four_top_corner_square_recesses(){
  d = clamp(sq_depth, 0, H - 2*eps);

  // Keep recesses inside the clipped-corner outline by staying away from edges
  ox = clamp(sq_offset_x, 0, L/2 - sq_size/2 - eps);
  oy = clamp(sq_offset_y, 0, W/2 - sq_size/2 - eps);

  zc = (H/2) - (d/2) + eps;  // slight overlap into the solid

  for (sx=[-1,1], sy=[-1,1])
    translate([sx*ox, sy*oy, zc])
      cube([sq_size, sq_size, d + 2*eps], center=true);
}

// Final solid (single connected body with subtracted features)
difference(){
  // Base solid (single connected body)
  main_block_with_clipped_corners();

  // Subtractive features
  through_octagonal_bore();
  top_recessed_long_slot();
  four_top_corner_square_recesses();
}

// Curved lightweighted strap/handle with 2 rectangular windows, end holes,
// chamfered/rounded ends, and a stepped/faceted reinforced midsection.
// Units: mm. One connected solid. Length along Z, thickness along Y.

$fn = 96;

// ---------------- Parameters ----------------
L = 0.16;                 // overall length (Z)
H = 0.03;                 // thickness (Y)
curve_sag = 0.006;        // lateral bow amount (X), peak at ends

body_w_end = 0.032;       // width at ends (X)
body_w_mid = 0.04;        // width at mid (X)

end_round_r = 0.006;      // end rounding radius
end_chamfer = 0.004;      // end chamfer depth (along Z)

hole_d = 0.006;           // end hole diameter
hole_end_offset = 0.014;  // hole offset from end along Z

win_len = 0.045;          // window length (Z)
win_w = 0.018;            // window width (X)
win_corner_r = 0.002;     // window corner radius
win_gap = 0.01;           // gap between windows (Z)

mid_step_len = 0.03;      // reinforced region length (Z)
mid_step_drop = 0.004;    // step amount (X,Y)
facet_count = 6;          // number of facets around midsection

eps = 0.0008;
overlap = 0.0015;         // small guaranteed overlap for robust connectivity

// ---------------- Derived placements ----------------
z_end_hole_pos =  L/2 - hole_end_offset;
z_end_hole_neg = -L/2 + hole_end_offset;

z_win_center_offset = (win_gap/2 + win_len/2);
z_win_pos =  z_win_center_offset;
z_win_neg = -z_win_center_offset;

// Keep windows fully inside ends and outside reinforced midsection
function clamp(v, a, b) = min(max(v, a), b);
z_win_limit = (L/2 - end_round_r - end_chamfer - win_len/2 - 2*eps);
z_win_pos_c = clamp(z_win_pos, -z_win_limit, z_win_limit);
z_win_neg_c = clamp(z_win_neg, -z_win_limit, z_win_limit);

// ---------------- Helpers ----------------
module rounded_rect_prism(size=[10,10,10], r=1, center=true) {
  // size = [X,Y,Z]
  x = size[0]; y = size[1]; z = size[2];
  rr = min(r, x/2 - eps, y/2 - eps);
  if (rr <= 0) {
    cube(size, center=center);
  } else {
    translate(center ? [0,0,0] : [x/2,y/2,z/2])
      linear_extrude(height=z, center=true, convexity=10)
        offset(r=rr)
          square([x-2*rr, y-2*rr], center=true);
  }
}

// Bow function: 0 at center, +/-curve_sag at ends (smooth)
function bow_x(z) = curve_sag * (2*z/L);

// Cross-section slice at z (thin in Z), used for hulling
module strap_section(w, zpos) {
  translate([ bow_x(zpos), 0, zpos ])
    rounded_rect_prism(
      [w, H, eps],
      r=min(end_round_r*0.6, w/2-eps, H/2-eps),
      center=true
    );
}

module curved_tapered_body() {
  // Continuous elongated strap via hull of multiple sections
  hull() {
    strap_section(body_w_end, -L/2);
    strap_section(body_w_mid, -L/4);
    strap_section(body_w_mid,  0);
    strap_section(body_w_mid,  L/4);
    strap_section(body_w_end,  L/2);
  }
}

module end_rounding() {
  // Rounded caps blended into strap (ensure overlap into body)
  for (s = [-1, 1]) {
    z0 = s*(L/2 - end_round_r);
    hull() {
      translate([ bow_x(z0), 0, z0 ]) sphere(r=end_round_r);
      strap_section(body_w_end, s*(L/2 - 2*end_round_r - overlap));
    }
  }
}

module reinforced_midsection() {
  // Stepped reinforcement centered at Z=0
  union() {
    rounded_rect_prism(
      [body_w_mid + 2*mid_step_drop, H + mid_step_drop, mid_step_len + 2*overlap],
      r=min(end_round_r*0.55,
            (body_w_mid+2*mid_step_drop)/2-eps,
            (H+mid_step_drop)/2-eps),
      center=true
    );

    rounded_rect_prism(
      [body_w_mid - mid_step_drop, H + 2*mid_step_drop, mid_step_len*0.6 + 2*overlap],
      r=min(end_round_r*0.5,
            (body_w_mid-mid_step_drop)/2-eps,
            (H+2*mid_step_drop)/2-eps),
      center=true
    );
  }
}

module end_chamfer_cutters() {
  // Chamfer both ends with wedges that intersect the strap ends
  for (s = [-1, 1]) {
    zc = s*(L/2 - end_chamfer/2);
    translate([ bow_x(zc), 0, zc ])
      rotate([0, 45*s, 0])
        cube([body_w_mid*3, H*3, end_chamfer*3], center=true);
  }
}

module window_cutout(zc) {
  // Enclosed rectangular through-window (through Y)
  translate([ bow_x(zc), 0, zc ])
    rounded_rect_prism([win_w, H + 6*eps, win_len], r=win_corner_r, center=true);
}

module end_hole(zc) {
  // Through-hole along Y
  translate([ bow_x(zc), 0, zc ])
    rotate([90, 0, 0])
      cylinder(d=hole_d, h=H + 8*eps, center=true);
}

module facet_cutters() {
  // Facet only the midsection: cutters limited in Z to mid_step_len
  // IMPORTANT: these are SUBTRACTED, so they must be placed OUTSIDE and cut IN.
  // Use large blocks positioned beyond the outer radius so they shave flats.
  outer_r = (body_w_mid/2 + mid_step_drop + overlap);
  cut_w = body_w_mid*4;
  cut_h = (H + 6*mid_step_drop)*6;
  cut_z = mid_step_len*1.25 + 2*overlap;

  for (i = [0:facet_count-1]) {
    ang = i * 360/facet_count;
    rotate([0, 0, ang])
      translate([ outer_r + cut_w/2 - overlap, 0, 0 ])
        cube([cut_w, cut_h, cut_z], center=true);
  }
}

module main_solid() {
  // One continuous elongated strap + blended ends + connected reinforcement
  union() {
    curved_tapered_body();
    end_rounding();

    // Ensure reinforcement is fused to strap with explicit overlap hull
    hull() {
      reinforced_midsection();
      strap_section(body_w_mid, 0);
      // add two nearby sections to guarantee a continuous midspan silhouette
      strap_section(body_w_mid,  mid_step_len/2 - overlap);
      strap_section(body_w_mid, -mid_step_len/2 + overlap);
    }
  }
}

module final_part() {
  difference() {
    // Base + reinforcement, then chamfer ends and facet midsection
    difference() {
      difference() {
        main_solid();
        end_chamfer_cutters();
      }
      facet_cutters();
    }

    // Two enclosed rectangular through-windows along the length
    window_cutout(z_win_pos_c);
    window_cutout(z_win_neg_c);

    // Two small circular through-holes at ends (same continuous strap)
    end_hole(z_end_hole_pos);
    end_hole(z_end_hole_neg);
  }
}

// Final Output (upright, length along Z)
final_part();

// Long rectangular prismatic block with stepped (L-shaped) planform
// and TWO centered U-shaped notches cut into opposite end faces.
// Units: mm

// Overall size (elongated along X)
L = 0.13;
W = 0.07;
H = 0.04;

// Step parameters to create an L-shaped planform in TOP view
step_L = 0.045;   // extent along X removed
step_W = 0.03;    // extent along Y removed

// U-notch parameters (cut into end faces along X)
notch_depth = 0.020;      // depth into the part along X
notch_height = 0.026;     // opening height along Z
notch_side_wall = 0.012;  // remaining wall on each side along Y (U-legs)

// Robust boolean epsilon / overlap
eps = 0.001;

// Main L-shaped planform block (extruded in Z)
// IMPORTANT: The corner removal is positioned so it actually removes the +X,+Y corner
// of the centered cube, producing an L-shaped footprint in TOP view.
module main_block_L_planform() {
    difference() {
        cube([L, W, H], center=true);

        // Remove +X,+Y corner prism:
        // Cutter spans x: [L/2-step_L, L/2], y: [W/2-step_W, W/2]
        // With center=true, place cutter center at:
        // x = L/2 - step_L/2, y = W/2 - step_W/2
        translate([ L/2 - step_L/2, W/2 - step_W/2, 0 ])
            cube([step_L + 2*eps, step_W + 2*eps, H + 2*eps], center=true);
    }
}

// Centered U-shaped notch cut from an end face (x = +/- L/2).
// Implemented as a rectangular recess that opens from the end face,
// leaving side walls (U-legs) along Y. Centered in Y and Z.
module end_u_notch(x_sign=1) {
    notch_w = max(eps, W - 2*notch_side_wall);
    notch_h = min(notch_height, H - 2*eps);

    // End face is at x = x_sign*(L/2).
    // Cutter extends slightly past the end face for a clean boolean:
    // Center at x = x_sign*(L/2 - (notch_depth/2) + eps)
    translate([ x_sign*(L/2 - notch_depth/2 + eps), 0, 0 ])
        cube([notch_depth + 2*eps, notch_w, notch_h], center=true);
}

difference() {
    // Single connected solid body
    main_block_L_planform();

    // Two matching centered U-notches on opposite end faces
    end_u_notch(-1);
    end_u_notch( 1);
}

// Thin rectangular plate with centered pentagonal through-cutout
// and four diamond-oriented square through-holes near corners.

// Use a small but nonzero thickness so geometry is visible/robust.
plate_L = 0.1;
plate_W = 0.1;
plate_T = 0.001;

// Cutouts
pent_R = 0.022;          // circumradius of pentagon
pent_rot_deg = 90;       // fixed orientation (consistent in all views)
corner_sq_side = 0.010;  // square side length
corner_sq_rot_deg = 45;  // diamond orientation

// Corner hole offsets from edges
edge_margin_L = 0.015;
edge_margin_W = 0.015;

// Through-cut settings
tool_overlap = plate_T;                 // ensure cutters fully span plate
cut_through_H = plate_T + 2*tool_overlap;

// Helpers
function pent_points(r, rot_deg) =
    [ for (i = [0:4])
        [ r*cos(rot_deg + i*72), r*sin(rot_deg + i*72) ]
    ];

module plate_main_body() {
    cube([plate_L, plate_W, plate_T], center=true);
}

module center_pentagon_through_cutout() {
    // Keep the pentagon strictly in XY and extrude along Z for consistent orientation.
    linear_extrude(height=cut_through_H, center=true, convexity=10)
        polygon(points=pent_points(pent_R, pent_rot_deg));
}

module corner_hole(xsign, ysign) {
    translate([
        xsign*(plate_L/2 - edge_margin_L),
        ysign*(plate_W/2 - edge_margin_W),
        0
    ])
    rotate([0, 0, corner_sq_rot_deg])
        cube([corner_sq_side, corner_sq_side, cut_through_H], center=true);
}

difference() {
    plate_main_body();

    // Center pentagonal opening
    center_pentagon_through_cutout();

    // Four corner diamond holes
    corner_hole( 1,  1);
    corner_hole(-1,  1);
    corner_hole(-1, -1);
    corner_hole( 1, -1);
}

// Short solid cylindrical puck/drum with slight fillets and subtle faceting
// Bounding box target: 0.1 x 0.1 x 0.1 mm (max extents)

// --- Parameters (mm) ---
