// Derived
rod_r = D/2;
hole_r = hole_D/2;

// Clamp hole position so it stays inside the rod length
hole_z = max(-L/2 + hole_offset_from_end, -L/2 + hole_r + eps);

difference() {
    // Single solid body
    union() {
        cylinder(h = L, r = rod_r, center = true, $fn = facet_fn);
    }

    // Transverse through-hole (axis along Y so it is visible in front/right orthographic views)
    // Make the cutter longer than the diameter to guarantee a clean through-hole.
    translate([0, 0, hole_z])
        rotate([90, 0, 0])
            cylinder(h = D + 2*eps, r = hole_r, center = true, $fn = facet_fn);
}
}

// Hex nut-like ring with circular through-hole and slight top/bottom chamfers
// (Fixes: non-empty geometry, truly circular bore, consistent hole in all views, connected solid)

// Parameters (mm)
outer_flat_to_flat = 10;     // across flats
height            = 6;       // overall thickness
hole_d            = 4;       // circular through-hole diameter
chamfer_h         = 0.5;     // chamfer height (top and bottom)
chamfer_inset     = 0.5;     // chamfer inset (radial shrink at chamfer)
eps               = 0.02;    // small overlap for robust booleans

$fn = 96;

// Derived
outer_R = outer_flat_to_flat / sqrt(3);                 // circumradius for hex with given across-flats
inner_R = max(0.01, outer_R - chamfer_inset);           // chamfered hex circumradius (slightly smaller)

// 2D hex helper (pointy-top orientation; still yields 6 flat wrench faces)
module hex2d(R) {
    polygon([ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// Main model
module hex_nut() {
    difference() {
        // Outer body with top/bottom chamfers via hull of two hex slices
        hull() {
            // bottom slice
            translate([0,0,-height/2]) linear_extrude(height=eps) hex2d(inner_R);
            // middle slice (full size)
            translate([0,0,-height/2 + chamfer_h]) linear_extrude(height=eps) hex2d(outer_R);
            // top slice (full size)
            translate([0,0, height/2 - chamfer_h - eps]) linear_extrude(height=eps) hex2d(outer_R);
            // top chamfer slice
            translate([0,0, height/2 - eps]) linear_extrude(height=eps) hex2d(inner_R);
        }

        // Circular through-hole (guaranteed round)
        cylinder(d=hole_d, h=height + 2*eps, center=true);
    }
}

hex_nut();

// Flat 6-armed radial plate with integrated rounded pads + diamond through-holes
// All geometry is built in 2D (XY) then extruded once to ensure a single connected planar solid.

$fn = 64;

// --- Parameters (mm) ---
bbox_X = 0.1;          // overall X target
bbox_Y = 0.0;          // planar (thickness handled by plate_thk)
bbox_Z = 0.1;          // overall Y target (kept symmetric)
plate_thk = 0.01;

hub_r = 0.012;

arm_len = 0.045;
arm_w_root = 0.01;
arm_w_tip  = 0.014;

pad_len = 0.03;
pad_w = 0.02;
pad_corner_r = 0.004;

hole_count_per_pad = 3;
hole_size = 0.004;
hole_pitch = 0.006;
hole_edge_margin = 0.004;
hole_rotation_deg = 45;

overlap = 0.001;

notch_r = 0.0015;
notch_depth = 0.001;

// --- Helpers ---
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module rounded_rect_2d(w, h, r){
  r2 = clamp(r, 0, min(w,h)/2);
  hull(){
    for (sx=[-1,1], sy=[-1,1])
      translate([sx*(w/2 - r2), sy*(h/2 - r2)]) circle(r=r2);
  }
}

module arm_2d(){
  // Arm extends from hub edge outward along +Y
  polygon(points=[
    [-arm_w_root/2, hub_r - overlap],
    [ arm_w_root/2, hub_r - overlap],
    [ arm_w_tip/2,  hub_r + arm_len + overlap],
    [-arm_w_tip/2,  hub_r + arm_len + overlap]
  ]);
}

module pad_2d(){
  // Pad centered at end of arm, integrated by union in 2D
  translate([0, hub_r + arm_len + pad_len/2 - overlap])
    rounded_rect_2d(pad_w, pad_len, pad_corner_r);
}

module hub_2d(){
  circle(r=hub_r);
}

module diamond_hole_2d(){
  rotate(hole_rotation_deg) square([hole_size, hole_size], center=true);
}

module notch_2d(){
  // Small circular notch near pad tip (subtracted)
  translate([0, hub_r + arm_len + pad_len - overlap - notch_depth])
    circle(r=notch_r);
}

// --- Build one arm (2D) ---
module arm_with_pad_2d(){
  union(){
    arm_2d();
    pad_2d();
  }
}

// --- Full plate outline (2D) ---
module spider_2d(){
  union(){
    hub_2d();
    for(i=[0:5])
      rotate(i*60) arm_with_pad_2d();
  }
}

// --- Holes (2D) ---
module holes_2d(){
  union(){
    for(i=[0:5]){
      rotate(i*60){
        // Place holes along pad length (Y direction), centered in pad width
        y0 = hub_r + arm_len + hole_edge_margin;
        for(j=[0:hole_count_per_pad-1]){
          translate([0, y0 + j*hole_pitch])
            diamond_hole_2d();
        }
      }
    }
  }
}

// --- Notches (2D) ---
module notches_2d(){
  union(){
    for(i=[0:5])
      rotate(i*60) notch_2d();
  }
}

// --- Final (single connected planar solid) ---
linear_extrude(height=plate_thk, center=true)
difference(){
  spider_2d();
  holes_2d();
  notches_2d();
}

// U-frame bracket with circular end plates and windowed crossbar
// Units: mm

$fn = 128;

// -------------------- Parameters --------------------
crossbar_len = 60;
crossbar_w   = 12;
crossbar_h   = 4;

plate_D      = 28;
plate_th     = 6;
plate_rise   = 26;   // height of cheeks above crossbar top

hole_D       = 16;

small_cutout_D        = 4;
small_cutout_offset_r = 8;

win_len   = 16;
win_w     = 6;

diamond_w = 10;
diamond_h = 10;

overlap   = 0.4;   // ensures connectivity / robust booleans
cut_depth = 200;   // through-cuts

// -------------------- Derived --------------------
plate_r = plate_D/2;

x_left  = -crossbar_len/2 + plate_th/2;
x_right =  crossbar_len/2 - plate_th/2;

// Place crossbar so its TOP is at z=0, and cheeks rise upward (+z)
z_crossbar_center = -crossbar_h/2;

// End plates: their centers sit at z = plate_r so their bottom is at z=0
z_plate_center = plate_r;

// -------------------- Helpers --------------------
module diamond_prism(w, h, t, center=true) {
  linear_extrude(height=t, center=center)
    polygon(points=[
      [ 0,  h/2],
      [ w/2, 0],
      [ 0, -h/2],
      [-w/2, 0]
    ]);
}

module end_plate_at(xpos) {
  // Plate is a disk in YZ plane (extruded along X)
  translate([xpos, 0, z_plate_center])
    rotate([0, 90, 0])
      cylinder(r=plate_r, h=plate_th, center=true);
}

module end_plate_cuts_at(xpos) {
  translate([xpos, 0, z_plate_center])
    rotate([0, 90, 0]) {
      // central opening
      cylinder(r=hole_D/2, h=cut_depth, center=true);

      // small cutouts (3)
      translate([0,  small_cutout_offset_r, 0])
        cylinder(r=small_cutout_D/2, h=cut_depth, center=true);
      translate([0, -small_cutout_offset_r, 0])
        cylinder(r=small_cutout_D/2, h=cut_depth, center=true);
      translate([0, 0,  small_cutout_offset_r])
        cylinder(r=small_cutout_D/2, h=cut_depth, center=true);
    }
}

module crossbar_solid() {
  translate([0, 0, z_crossbar_center])
    cube([crossbar_len, crossbar_w, crossbar_h], center=true);
}

module crossbar_windows() {
  // Cut windows through crossbar thickness (Z)
  // Left and right rectangular windows
  translate([-crossbar_len/4, 0, z_crossbar_center])
    cube([win_len, win_w, cut_depth], center=true);

  translate([ crossbar_len/4, 0, z_crossbar_center])
    cube([win_len, win_w, cut_depth], center=true);

  // Center diamond window
  translate([0, 0, z_crossbar_center])
    rotate([0, 0, 45])
      diamond_prism(diamond_w, diamond_h, cut_depth, center=true);
}

module cheeks() {
  // Two vertical side cheeks rising from crossbar top (z=0) to z=plate_rise
  // They overlap slightly into the crossbar for a single connected solid.
  cheek_h = plate_rise + overlap;
  cheek_z = cheek_h/2 - overlap/2; // bottom slightly below z=0

  union() {
    translate([x_left, 0, cheek_z])
      cube([plate_th, plate_D, cheek_h], center=true);

    translate([x_right, 0, cheek_z])
      cube([plate_th, plate_D, cheek_h], center=true);
  }
}

// -------------------- Final Model --------------------
difference() {
  union() {
    crossbar_solid();
    cheeks();

    // Circular end plates at the top of cheeks
    // Centered at z=plate_rise + plate_r so their bottom touches z=plate_rise
    translate([0, 0, plate_rise])
      union() {
        end_plate_at(x_left);
        end_plate_at(x_right);
      }
  }

  // Crossbar windows
  crossbar_windows();

  // End plate openings/cutouts
  translate([0, 0, plate_rise]) {
    end_plate_cuts_at(x_left);
    end_plate_cuts_at(x_right);
  }
}

// Thick circular disk/button with shallow recessed rim, 5 diamond cutouts,
// central square through feature, and a short square peg on the back.
// Units: mm

