// Short thick cylindrical sleeve/cap-like solid with slightly chamfered end edges,
// a visible shallow circumferential groove near one end, and an asymmetric rectangular lug
// with a small notch cutout. One connected solid.

$fn = 128;

// --- Parameters (meters as given; keep as-is) ---
body_d = 0.008;          // outer diameter
body_h = 0.0020;         // overall height (slightly more plate-like)

wall_t = 0.0007;         // sleeve wall thickness
cap_floor = 0.00035;     // closed-end floor thickness (cap-like)

edge_chamfer = 0.00018;  // small chamfer on outer end edges

// Groove (external circumferential)
groove_depth = 0.00025;               // radial depth into outer surface
groove_w = 0.0007;                    // axial width
groove_offset_from_open_end = 0.00055;// from open end (-Z) to groove center

// Lug
lug_l = 0.0042;         // length outward from cylinder (X)
lug_w = 0.0030;         // width (Y)
lug_h = body_h;         // match body height
lug_y_offset = body_d * 0.14; // asymmetry in Y

// Notch in lug
notch_l = 0.0012;
notch_w = 0.0010;
notch_h = 0.0012;

overlap = 0.002;        // 1–2mm overlap for robust connectivity (per requirement)
eps = 1e-6;

// --- Helpers ---
module chamfered_cylinder(h, r, c) {
  c2 = min(c, h/2 - 2*eps);
  union() {
    cylinder(h=h - 2*c2, r=r, center=true);
    translate([0,0,(h/2 - c2/2)])
      cylinder(h=c2, r1=r, r2=max(r - c2, 0), center=true);
    translate([0,0,(-h/2 + c2/2)])
      cylinder(h=c2, r1=max(r - c2, 0), r2=r, center=true);
  }
}

module outer_shell() {
  chamfered_cylinder(body_h, body_d/2, edge_chamfer);
}

module inner_void() {
  // Open end at -Z, closed end at +Z with floor thickness cap_floor
  inner_r = max(body_d/2 - wall_t, 0);
  inner_h = max(body_h - cap_floor, 0);

  // Center so top of void is at +Z: (body_h/2 - cap_floor)
  inner_center_z = (body_h/2 - cap_floor) - inner_h/2;

  translate([0,0,inner_center_z])
    cylinder(h=inner_h + 2*eps, r=inner_r, center=true);
}

module lug_solid() {
  // Attach to +X side with guaranteed overlap into the cylinder
  // Inner face penetrates cylinder by 'overlap'
  lug_center_x = (body_d/2) + (lug_l/2) - overlap;

  translate([lug_center_x, lug_y_offset, 0])
    cube([lug_l, lug_w, lug_h], center=true);
}

module groove_cutter() {
  // Cut a shallow circumferential groove near the open end (-Z)
  // Use a slightly larger outer radius so the subtraction is guaranteed to bite.
  groove_center_z_raw = -body_h/2 + groove_offset_from_open_end;
  groove_center_z = min(
                    max(groove_center_z_raw, -body_h/2 + groove_w/2 + eps),
                    +body_h/2 - groove_w/2 - eps
                  );

  outer_r = body_d/2 + 0.001; // ensure visible/robust cut (>= 1mm beyond OD)
  inner_r = max(body_d/2 - groove_depth, 0);

  translate([0,0,groove_center_z])
    difference() {
      cylinder(h=groove_w + 2*eps, r=outer_r, center=true);
      cylinder(h=groove_w + 4*eps, r=inner_r, center=true);
    }
}

module notch_cutter() {
  // Notch cutout in the lug to suggest indexing/locking.
  // Place it on the OUTER end of the lug and cut inward.
  lug_center_x = (body_d/2) + (lug_l/2) - overlap;
  lug_outer_x  = lug_center_x + lug_l/2;

  // Keep notch fully within lug bounds, near +Y and +Z edges.
  notch_center_x = lug_outer_x - notch_l/2;                      // flush to outer face
  notch_center_y = lug_y_offset + (lug_w/2 - notch_w/2) - eps;   // near +Y edge
  notch_center_z = (lug_h/2 - notch_h/2) - eps;                  // near +Z edge

  translate([notch_center_x, notch_center_y, notch_center_z])
    cube([notch_l + 2*eps, notch_w + 2*eps, notch_h + 2*eps], center=true);
}

// --- Model ---
difference() {
  union() {
    outer_shell();
    lug_solid();
  }
  inner_void();       // sleeve/cap (open at -Z, closed at +Z)
  groove_cutter();    // visible shallow circumferential groove near open end
  notch_cutter();     // notch in lug
}

// Compact mounting bracket with rounded-rectangle base and elbowed arm
// Bounding box target: 0.2 x 0.1 x 0.1 mm (X x Y x Z)

$fn = 64;

// ---- Target bounding box ----
bbox_L = 0.2;
bbox_W = 0.1;
bbox_H = 0.1;

// ---- Base ----
base_L = 0.10;
base_W = bbox_W;
base_H = bbox_H;
base_corner_r = 0.02;

// ---- Arm (plan-view elbow) ----
arm_thk = 0.04;                 // thickness in Z (sits on top of base)
arm_w = 0.028;                  // main arm width in Y
arm_neck_w = 0.018;             // narrow neck width in Y
arm_neck_L = 0.018;             // neck length in X
arm_elbow_offset_W = 0.028;     // Y offset of the arm after elbow
arm_end_L = 0.034;              // obround end length in X
arm_end_W = 0.040;              // obround end width in Y

// Derived to hit bbox_L exactly
arm_reach_L = bbox_L - base_L/2; // from base center to arm tip in +X

// ---- Neck side bosses/steps ----
boss_L = 0.010;
boss_W = 0.008;
boss_H = 0.020;

// ---- Cuts ----
cavity_L = 0.030;
cavity_W = 0.050;
cavity_H = 0.040;

hole_r = 0.006;
hole_edge_margin = 0.020;

step_depth = 0.010;
step_band_W = 0.020;

overlap = 0.001;

// ----------------- Helpers -----------------
module rounded_rect_2d(L, W, r) {
  r2 = min(r, min(L, W)/2 - 1e-6);
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(L/2 - r2), sy*(W/2 - r2)]) circle(r=r2);
  }
}

module obround_2d(L, W) {
  // L >= W recommended
  L2 = max(L, W);
  hull() {
    translate([-(L2/2 - W/2), 0]) circle(r=W/2);
    translate([ (L2/2 - W/2), 0]) circle(r=W/2);
  }
}

// ----------------- Base -----------------
module base_block() {
  linear_extrude(height=base_H, center=true)
    rounded_rect_2d(base_L, base_W, base_corner_r);
}

// ----------------- Arm (single connected solid) -----------------
module arm_solid() {
  // Place arm on top surface of base
  zc = base_H/2 - arm_thk/2;

  // Key X positions (all formula-based)
  x0 = base_L/2 - overlap;                 // start slightly inside base for guaranteed connection
  x1 = x0 + arm_neck_L;                    // end of neck
  x_tip = base_L/2 + arm_reach_L;          // absolute tip in +X (bbox_L/2)
  x_end_center = x_tip - arm_end_L/2;      // center of obround end
  x_end_start = x_tip - arm_end_L;         // start of obround end
  x_mid_end = x_end_start - overlap;       // end of mid segment (overlap into end)

  // Elbow corner center (plan view)
  // Use a quarter-round elbow with radius = arm_w/2
  r_elbow = arm_w/2;
  x_corner = x1 + r_elbow;
  y_corner = r_elbow;

  // Ensure there is some straight length after elbow before the end
  // Mid segment starts after elbow and runs to just before obround end
  x_mid_start = x_corner;
  y_mid = arm_elbow_offset_W;

  union() {
    // Neck (narrow)
    translate([(x0 + x1)/2, 0, zc])
      cube([x1 - x0 + overlap, arm_neck_w, arm_thk], center=true);

    // Small side bosses around neck region (on top of base)
    translate([x0 + boss_L/2,  (arm_neck_w/2 + boss_W/2 - overlap), base_H/2 - boss_H/2])
      cube([boss_L, boss_W, boss_H], center=true);
    translate([x0 + boss_L/2, -(arm_neck_w/2 + boss_W/2 - overlap), base_H/2 - boss_H/2])
      cube([boss_L, boss_W, boss_H], center=true);

    // Transition from neck width to arm width (short blend block)
    blend_L = max(arm_w, 0.012);
    translate([x1 + blend_L/2 - overlap, 0, zc])
      cube([blend_L, arm_w, arm_thk], center=true);

    // Elbow: quarter-ring sector (curved in plan view)
    // Center at (x_corner, y_corner), sweeping from +X to +Y
    translate([x_corner, y_corner, zc])
      linear_extrude(height=arm_thk, center=true)
        difference() {
          intersection() {
            circle(r=arm_w);
            square([arm_w, arm_w], center=false); // first quadrant
          }
          intersection() {
            circle(r=arm_w - arm_w); // placeholder to keep structure valid if arm_w changes
            square([arm_w, arm_w], center=false);
          }
        }

    // Proper elbow as a thick quarter-annulus using offset on a quarter-arc path
    // (Implemented via hull of small circles along the arc for robustness)
    translate([0,0,zc])
      linear_extrude(height=arm_thk, center=true)
        hull() {
          for (a = [0:10:90]) {
            translate([x_corner + r_elbow*cos(a), y_corner + r_elbow*sin(a)])
              circle(r=arm_w/2);
          }
        }

    // Straight segment after elbow (at Y offset)
    mid_L = max(0.0, x_mid_end - x_mid_start);
    if (mid_L > 0)
      translate([x_mid_start + mid_L/2, y_mid, zc])
        cube([mid_L + overlap, arm_w, arm_thk], center=true);

    // Obround terminal end (smooth, not faceted)
    translate([x_end_center, y_mid, zc])
      linear_extrude(height=arm_thk, center=true)
        obround_2d(arm_end_L, arm_end_W);
  }
}

// ----------------- Cuts -----------------
module base_relief_cavity() {
  translate([-base_L/2 + base_corner_r + cavity_L/2, 0, -base_H/2 + cavity_H/2 + overlap])
    cube([cavity_L, cavity_W, cavity_H], center=true);
}

module mounting_holes() {
  // Two holes along X, centered in Y
  translate([-base_L/2 + hole_edge_margin, 0, 0])
    cylinder(r=hole_r, h=base_H + 4*overlap, center=true);
  translate([ base_L/2 - hole_edge_margin, 0, 0])
    cylinder(r=hole_r, h=base_H + 4*overlap, center=true);
}

module surface_step_band_cut() {
  translate([0, base_W/2 - step_band_W/2 - overlap, base_H/2 - step_depth/2])
    cube([base_L - 2*base_corner_r, step_band_W, step_depth + 2*overlap], center=true);
}

// ----------------- Assembly -----------------
module bracket() {
  difference() {
    union() {
      base_block();
      arm_solid();
    }
    base_relief_cavity();
    mounting_holes();
    surface_step_band_cut();
  }
}

bracket();

// Wedge-shaped mounting bracket/block (single connected solid)
// Units: mm
$fn = 64;

// -------------------- Parameters (mm) --------------------
body_x = 60;     // length (X)
body_y = 40;     // width  (Y)
body_z = 50;     // height (Z)

// Sloped face: z at x=-body_x/2 is slope_z_left, at x=+body_x/2 is slope_z_right
slope_z_left  = 6;
slope_z_right = 46;

// End flange/step on +X end (thicker vertical flange)
flange_len_x = 10;
flange_extra_y = 10;   // adds thickness on +Y side
flange_z = body_z;

// Small lower protruding foot near +X end, on -Y and bottom
foot_len_x = 14;
foot_y = 12;
foot_z = 10;

// Side relief cavity (small cut on -Y side)
side_cavity_x = 22;
side_cavity_y = 10;
side_cavity_z = 26;
side_cavity_offset_x = 14;  // from -X face inward
side_cavity_offset_z = 10;  // from bottom upward

// Small alignment notch (cut at -X, +Y, bottom corner)
notch_x = 8;
notch_y = 8;
notch_z = 8;

// Cosmetic shallow recess on -Y face
cosmetic_recess_x = 30;
cosmetic_recess_y = 2;
cosmetic_recess_z = 26;

// Holes through Y (on sloped region), plus shallow counterbore/recess on +Y side
hole_d = 4;
recess_d = 7;
recess_depth = 3;
hole_count = 2;
hole_spacing = 16;
hole_edge_margin_x = 16; // from -X face

// Small overlap for robust booleans
eps = 0.2;

// -------------------- Helpers --------------------
function slope_z_at_x(x) =
    slope_z_left + (x + body_x/2) * (slope_z_right - slope_z_left) / body_x;

// Main wedge body: rectangular block with a diagonal cut creating a sloped face
module wedge_body() {
    difference() {
        // Base block
        translate([0, 0, body_z/2])
            cube([body_x, body_y, body_z], center=true);

        // Cut away volume above the sloped plane (creates the diagonal face)
        // Use a large prism defined by a polygon in XZ, extruded along Y.
        translate([0, 0, 0])
            rotate([90, 0, 0])
                linear_extrude(height=body_y + 2*eps, center=true)
                    polygon(points=[
                        // Keep region below the line; remove region above by subtracting a big shape
                        [-body_x/2 - eps, slope_z_left],
                        [ body_x/2 + eps, slope_z_right],
                        [ body_x/2 + eps, body_z + 50],
                        [-body_x/2 - eps, body_z + 50]
                    ]);
    }
}

// End flange step on +X end, thicker on +Y side
module end_flange() {
    // Place flange so it overlaps the main body by eps to ensure connectivity
    translate([ body_x/2 - flange_len_x/2 + eps, (body_y + flange_extra_y)/2 - flange_extra_y/2, flange_z/2 ])
        cube([flange_len_x, body_y + flange_extra_y, flange_z], center=true);
}

// Lower foot protrusion near +X end, on -Y and bottom
module lower_foot() {
    translate([ body_x/2 - foot_len_x/2 + eps, -body_y/2 + foot_y/2, foot_z/2 ])
        cube([foot_len_x, foot_y, foot_z], center=true);
}

// Through holes and shallow recesses (counterbore) on +Y side
module holes_and_recesses() {
    for (i = [0:hole_count-1]) {
        xh = -body_x/2 + hole_edge_margin_x + i*hole_spacing;
        zh = min(body_z - 8, max(8, slope_z_at_x(xh) - 6)); // keep within body

        // Through hole along Y
        translate([xh, 0, zh])
            rotate([90, 0, 0])
                cylinder(d=hole_d, h=body_y + flange_extra_y + 4*eps, center=true);

        // Shallow recess from +Y side
        translate([xh, body_y/2 + flange_extra_y - recess_depth/2 + eps, zh])
            rotate([90, 0, 0])
                cylinder(d=recess_d, h=recess_depth + 2*eps, center=true);
    }
}

// Side relief cavity cut on -Y side
module side_relief_cavity() {
    translate([
        -body_x/2 + side_cavity_offset_x + side_cavity_x/2,
        -body_y/2 + side_cavity_y/2 + eps,
        side_cavity_offset_z + side_cavity_z/2
    ])
        cube([side_cavity_x, side_cavity_y, side_cavity_z], center=true);
}

// Small alignment notch cut at -X, +Y, bottom
module alignment_notch() {
    translate([
        -body_x/2 + notch_x/2 - eps,
        body_y/2 - notch_y/2 + eps,
        notch_z/2 - eps
    ])
        cube([notch_x, notch_y, notch_z], center=true);
}

// Cosmetic shallow recess on -Y face
module cosmetic_recess() {
    translate([0, -body_y/2 + cosmetic_recess_y/2 + eps, body_z/2])
        cube([cosmetic_recess_x, cosmetic_recess_y, cosmetic_recess_z], center=true);
}

// -------------------- Final assembly --------------------
difference() {
    union() {
        wedge_body();
        end_flange();
        lower_foot();
    }

    holes_and_recesses();
    side_relief_cavity();
    alignment_notch();
    cosmetic_recess();
}

// Hex nut-like ring with circular through-hole and slight edge chamfers
// (single connected solid; no floating parts)

$fn = 96;

// --- Parameters (mm) ---
outer_flat_to_flat = 10;     // across flats
thickness          = 4;      // overall thickness (elongated along Z)
hole_d             = 5;      // circular through-hole diameter
edge_chamfer       = 0.4;    // chamfer height on top and bottom edges
overlap            = 0.05;   // boolean robustness

// --- Derived ---
outer_R = outer_flat_to_flat / sqrt(3); // circumradius for hex with given flat-to-flat
inner_R = max(outer_R - edge_chamfer, 0.01);
mid_h   = max(thickness - 2*edge_chamfer, 0.01);

// 2D hex helper
module hex2d(R){
    polygon(points=[
        [ R, 0],
        [ R/2,  R*0.866025403784],
        [-R/2,  R*0.866025403784],
        [-R, 0],
        [-R/2, -R*0.866025403784],
        [ R/2, -R*0.866025403784]
    ]);
}

// Outer body with slight chamfer via hull of three extrusions
module outer_body(){
    hull(){
        // bottom "cap"
        translate([0,0,-thickness/2])
            linear_extrude(height=overlap, center=false) hex2d(outer_R);

        // middle inset
        translate([0,0,-mid_h/2])
            linear_extrude(height=mid_h, center=true) hex2d(inner_R);

        // top "cap"
        translate([0,0, thickness/2 - overlap])
            linear_extrude(height=overlap, center=false) hex2d(outer_R);
    }
}

// Circular through-hole (true circle, not polygonal)
module through_hole(){
    cylinder(d=hole_d, h=thickness + 2*overlap, center=true, $fn=128);
}

// Final solid
difference(){
    outer_body();
    through_hole();
}

// Axisymmetric coupling/knob with two knurled bands, stepped flange, and through hex bore
// Units: mm

$fn = 160;

// Parameters (kept from original, but interpreted as mm-scale values)
body_D = 0.0082;
body_L = 0.0096;

flange_D = 0.0098;
flange_L = 0.0016;

hex_flat = 0.0046;

upper_knurl_L = 0.0022;
lower_knurl_L = 0.0022;

knurl_peak = 0.00035;          // radial protrusion of knurl teeth
serration_count = 18;          // teeth around circumference
overlap = 0.0006;

chamfer_z = 0.00035;           // end chamfer height
relief_groove_L = 0.0007;      // small relief at bottom end
relief_groove_depth = 0.00035; // radial depth of relief groove

mid_serration_L = 0.0016;      // optional mid band height (kept subtle)
knurl_phase_deg = 10;

scale_uniform = 1;

// Derived
body_r = body_D/2;
flange_r = flange_D/2;

// Z layout (centered body)
z_bot = -body_L/2;
z_top =  body_L/2;

z_lower_knurl_c = z_bot + lower_knurl_L/2;
z_upper_knurl_c = z_top - flange_L - upper_knurl_L/2;

// Place mid band between lower and upper regions
mid_free_L = max(0, body_L - flange_L - upper_knurl_L - lower_knurl_L);
z_mid_c = z_bot + lower_knurl_L + mid_free_L/2;

// ---------- Helpers ----------
module hex2d(flat) {
  // Regular hex with given flat-to-flat distance
  // circumradius = flat / sqrt(3)
  r = flat / sqrt(3);
  polygon(points=[for(i=[0:5]) [r*cos(60*i), r*sin(60*i)]]);
}

module knurl_band(zc, h, base_r, peak, n, phase=0) {
  // Adds outward triangular teeth around circumference (axisymmetric base + radial teeth)
  // Teeth overlap into base by 'overlap' to ensure connectivity.
  tooth_len = peak + overlap;
  tooth_w   = 2*PI*base_r / n * 0.55; // tangential width
  union() {
    // Slightly enlarged band cylinder to blend teeth
    translate([0,0,zc]) cylinder(r=base_r + peak*0.25, h=h, center=true);

    for (i = [0:n-1]) {
      rotate([0,0,phase + i*360/n])
        translate([base_r + tooth_len/2 - overlap, 0, zc])
          // Triangular prism tooth (pointing outward)
          rotate([0,90,0])
            linear_extrude(height=tooth_len, center=true, convexity=5)
              polygon(points=[
                [-tooth_w/2, -h/2],
                [-tooth_w/2,  h/2],
                [ tooth_w/2,  0]
              ]);
    }
  }
}

module end_chamfer(zc, r, h, top=true) {
  // Chamfer as a conical frustum removed from end
  // top=true -> chamfer at +Z end, else at -Z end
  translate([0,0,zc])
    cylinder(h=h, r1=top ? r : 0, r2=top ? 0 : r, center=true);
}

// ---------- Main solid ----------
module outer_solid() {
  union() {
    // Main body
    cylinder(r=body_r, h=body_L, center=true);

    // Stepped flange on +Z end (distinct)
    translate([0,0, z_top - flange_L/2 + overlap])
      cylinder(r=flange_r, h=flange_L, center=true);

    // Knurled grip bands (upper and lower)
    knurl_band(z_lower_knurl_c, lower_knurl_L, body_r, knurl_peak, serration_count, 0);
    knurl_band(z_upper_knurl_c, upper_knurl_L, body_r, knurl_peak, serration_count, knurl_phase_deg);

    // Subtle mid serration band (smaller than knurl)
    if (mid_serration_L > 0)
      knurl_band(z_mid_c, mid_serration_L, body_r, serration_depth=knurl_peak*0.55, n=serration_count, phase=knurl_phase_deg/2);
  }
}

// OpenSCAD doesn't allow named args not in signature; provide wrapper for mid band depth
module knurl_band(zc, h, base_r, peak, n, phase=0, serration_depth=undef) {
  p = (serration_depth == undef) ? peak : serration_depth;
  tooth_len = p + overlap;
  tooth_w   = 2*PI*base_r / n * 0.55;
  union() {
    translate([0,0,zc]) cylinder(r=base_r + p*0.20, h=h, center=true);
    for (i = [0:n-1]) {
      rotate([0,0,phase + i*360/n])
        translate([base_r + tooth_len/2 - overlap, 0, zc])
          rotate([0,90,0])
            linear_extrude(height=tooth_len, center=true, convexity=5)
              polygon(points=[
                [-tooth_w/2, -h/2],
                [-tooth_w/2,  h/2],
                [ tooth_w/2,  0]
              ]);
    }
  }
}

module outer_with_details() {
  difference() {
    outer_solid();

    // End chamfers (remove material)
    // Top chamfer around flange OD
    end_chamfer(z_top + chamfer_z/2 - overlap, flange_r + overlap, chamfer_z + 2*overlap, top=true);

    // Bottom chamfer around body OD
    end_chamfer(z_bot - chamfer_z/2 + overlap, body_r + overlap, chamfer_z + 2*overlap, top=false);

    // Bottom relief groove (a shallow undercut ring)
    translate([0,0, z_bot + relief_groove_L/2])
      cylinder(r=body_r + knurl_peak + overlap, h=relief_groove_L + 2*overlap, center=true);

    // Carve the relief depth by subtracting a slightly smaller cylinder from the groove region
    // (leaves a step/undercut)
    translate([0,0, z_bot + relief_groove_L/2])
      cylinder(r=body_r + knurl_peak - relief_groove_depth, h=relief_groove_L + 2*overlap, center=true);
  }
}

module through_hex_bore() {
  // Through bore spans entire part including chamfers/flange with margin
  bore_h = body_L + flange_L + 2*chamfer_z + 6*overlap;
  linear_extrude(height=bore_h, center=true, convexity=10)
    hex2d(hex_flat);
}

module final_part() {
  difference() {
    outer_with_details();
    through_hex_bore();
  }
}

// Final output
scale([scale_uniform, scale_uniform, scale_uniform])
  final_part();

