// Rectangular hollow prism (box-section tube) with centered through-opening
// Bounding box: 0.8 x 0.3 x 0.3 mm (X x Y x Z), elongated along X

L = 0.8;     // length (X)
W = 0.3;     // width  (Y)
H = 0.3;     // height (Z)

wall_t = 0.03;   // uniform wall thickness
eps = 0.002;     // small overlap to ensure clean boolean through-cut

// Inner opening dimensions (must be positive and smaller than outer)
innerW = max(W - 2*wall_t, eps);
innerH = max(H - 2*wall_t, eps);

union() {
    difference() {
        // Outer tube (featureless exterior)
        cube([L, W, H], center=true);

        // Centered rectangular through-opening (slightly longer so ends are open)
        cube([L + 2*eps, innerW, innerH], center=true);
    }
}

// Simple block with centered cylindrical boss (one connected solid)

// Use sensible, visible millimeter-scale dimensions (avoid near-zero sizes)
block_L = 60;   // length (X)
block_W = 60;   // width  (Y)
block_H = 30;   // height (Z)

boss_r  = 10;   // boss radius
boss_h  = 8;    // boss height
overlap = 0.2;  // small overlap to guarantee manifold union

$fn = 96;

// Base shapes
module block() {
    cube([block_L, block_W, block_H], center=true);
}

module cylindrical_boss() {
    // Centered on the top face of the block
    translate([0, 0, block_H/2 + boss_h/2 - overlap])
        cylinder(h=boss_h, r=boss_r, center=true);
}

// Final model (single connected solid)
union() {
    block();
    cylindrical_boss();
}

// Stepped coin-like disk with 3 HEX through-cutouts + recessed triangular/ribbed webs (both faces)
// Structural fixes:
//  - Make cutouts unambiguously HEX in face views (true 6-sided prism, rotated 30°)
//  - Make recessed 3-spoke web clearly connect the three openings on BOTH faces
//  - Recalculate all translate() values so parts touch (boss sits on flange with slight overlap)
// Notes:
//  - The "0.1 x 0.1 x 0.0 mm" bbox is physically impossible for a solid; we keep a small nonzero Z.
//  - Target bounding box: 0.1 x 0.1 x 0.04 mm

$fn = 128;

// ---- Bounding box targets ----
bbox_X = 0.1;
bbox_Y = 0.1;
bbox_Z = 0.04;

// ---- Main dimensions (fit within bbox) ----
flange_D = bbox_X;          // 0.1
flange_t = 0.028;

boss_D   = 0.06;
boss_h   = bbox_Z - flange_t;   // ensures total height = bbox_Z

// ---- Hex pattern (clearly visible) ----
hex_AF       = 0.026;       // across flats
hex_center_R = 0.022;       // radius to hex centers (triangular pattern)

// ---- Web recess (both faces) ----
web_recess_depth     = 0.004;   // depth of recess into each face
web_thickness        = 0.008;   // rib width
web_clearance_to_hex = 0.002;

eps = 0.0005;

// ---------- Helpers ----------
function clamp(x,a,b) = x < a ? a : (x > b ? b : x);

// Regular hex polygon sized by across-flats (AF)
module hex2d(af=hex_AF) {
    // For a regular hex: AF = 2*apothem; apothem = r*cos(30) => r = AF/sqrt(3)
    r = af / sqrt(3);
    polygon(points=[ for(i=[0:5]) [ r*cos(60*i), r*sin(60*i) ] ]);
}

module hex_cutout_at(xy=[0,0], rot=0, h=bbox_Z + 40*eps) {
    translate([xy[0], xy[1], 0])
        rotate([0,0,rot])
            linear_extrude(height=h, center=true, convexity=10)
                hex2d(hex_AF);
}

// Recessed 3-spoke web that CONNECTS the three hex openings (both faces)
// Implemented as: three "capsules" (hull of two circles) from center to near each hex center,
// plus a small central hub. This reads as a triangular/ribbed web in orthographic views.
module tri_web_recess(z_center=0, depth=web_recess_depth) {
    rib_r = web_thickness/2;

    // Keep ribs clear of hex openings: stop short of hex by (apothem + clearance)
    hex_apothem = hex_AF/2;
    stop_clear  = hex_apothem + web_clearance_to_hex;

    // End point along each spoke, measured from center
    spoke_end_R = max(0, hex_center_R - stop_clear);

    translate([0,0,z_center])
        linear_extrude(height=depth, center=true, convexity=10)
            union() {
                // Three spokes (capsules) from center to near each hex opening
                for(a=[0,120,240]) {
                    hull() {
                        circle(r=rib_r, $fn=48);
                        translate([spoke_end_R*cos(a), spoke_end_R*sin(a)])
                            circle(r=rib_r, $fn=48);
                    }
                }

                // Central hub to ensure connectivity and a clear "3-spoke" read
                circle(r=rib_r*1.35, $fn=48);
            }
}

// ---------- Main solid ----------
module part() {
    // Enforce exact overall height bbox_Z with a true step:
    // flange centered at z=0, boss sits on top face of flange.
    boss_h_eff   = clamp(boss_h, eps, bbox_Z - eps);
    flange_t_eff = clamp(flange_t, eps, bbox_Z - boss_h_eff);

    // Recess depth must not exceed available face thickness
    recess_d = clamp(web_recess_depth, eps, flange_t_eff/2 - 3*eps);

    // Slight overlap between flange and boss for robust union (scaled to tiny model)
    overlap_z = 2*eps;

    difference() {
        // Base: flange + raised boss (connected)
        union() {
            // Flange centered at z=0
            cylinder(d=flange_D, h=flange_t_eff, center=true);

            // Boss on top of flange:
            // flange top face at +flange_t/2
            // boss bottom face at (boss_center - boss_h/2)
            // set boss_center so boss bottom is slightly below flange top (overlap)
            boss_center_z = (flange_t_eff/2) + (boss_h_eff/2) - overlap_z;

            translate([0,0,boss_center_z])
                cylinder(d=boss_D, h=boss_h_eff, center=true);
        }

        // Three THROUGH hex cutouts (clearly hex, 120° apart)
        for(a=[0,120,240]) {
            hex_cutout_at(
                xy=[hex_center_R*cos(a), hex_center_R*sin(a)],
                rot=30,                       // flats horizontal/vertical in views
                h=bbox_Z + 40*eps
            );
        }

        // Recessed webs on BOTH faces of the flange (do not cut through)
        // Top face of flange at +flange_t/2, bottom face at -flange_t/2
        tri_web_recess(
            z_center= (flange_t_eff/2) - (recess_d/2),
            depth=recess_d + 2*eps
        );
        tri_web_recess(
            z_center=-(flange_t_eff/2) + (recess_d/2),
            depth=recess_d + 2*eps
        );
    }
}

part();

// Bent elbow-like bracket/duct component (fixed structure + connectivity)
// Target bounding box: 0.2 x 0.1 x 0.1 mm (X x Y x Z)

$fn = 96;

// --- Bounding box targets ---
bbox_X = 0.20;
bbox_Y = 0.10;
bbox_Z = 0.10;

// --- Small overlap to guarantee connectivity (in mm) ---
ov = 0.002;   // 1–2 "mm" requested; using 0.002 in this tiny scale to avoid blowing bbox

// --- Main elbow (solid, thick curved body) ---
R_center = 0.040;          // centerline radius of elbow
tube_D   = 0.060;          // outer diameter of elbow body (thick)
arc_deg  = 90;

// --- End interfaces ---
big_L = 0.070;             // larger rectangular block length (along -X)
big_Y = bbox_Y;
big_Z = bbox_Z;

tongue_L = 0.060;          // smaller tongue length (along +Y)
tongue_Y = 0.040;
tongue_Z = 0.050;

// --- Obround end-cap near small end (integrated) ---
cap_L = 0.040;             // obround length along +Y
cap_W = 0.030;             // obround width along X
cap_Z = 0.050;

// --- Top lugs/steps near tip ---
lug1_L = 0.018; lug1_W = 0.018; lug1_H = 0.010;
lug2_L = 0.014; lug2_W = 0.014; lug2_H = 0.008;

// ----------------- Helpers -----------------
module obround_2d(L, W) {
    // L along Y, W along X
    r = W/2;
    hull() {
        translate([0, -L/2 + r]) circle(r=r);
        translate([0,  L/2 - r]) circle(r=r);
    }
}

module elbow_solid() {
    // Quarter torus-like solid made by rotate_extrude of a circle
    // Arc runs from +X toward +Y in XY plane.
    rotate_extrude(angle=arc_deg, convexity=10)
        translate([R_center, 0, 0])
            circle(d=tube_D);
}

module elbow_keep_quadrant() {
    // Keep only the +X,+Y quadrant and limit Z to bbox_Z
    intersection() {
        elbow_solid();
        // Keep region: x>=0, y>=0, |z|<=bbox_Z/2
        translate([bbox_X/2, bbox_Y/2, 0])
            cube([bbox_X, bbox_Y, bbox_Z], center=true);
    }
}

// ----------------- Main connected solid -----------------
module model_solid() {

    // Useful radii/edges for attachment math
    elbow_outer_r = R_center + tube_D/2;   // max x or y of elbow in kept quadrant

    // Place everything so the elbow sits near the inside corner (x>=0,y>=0),
    // then attach a big block at +X end and a tongue at +Y end.
    union() {

        // 1) Curved 90-degree elbow body (recognizable L/arc silhouette)
        elbow_keep_quadrant();

        // 2) Large rectangular block at the +X end, extending toward -X
        // Attach: block's +X face slightly overlaps elbow's max X (elbow_outer_r)
        // Block center x = (attach_x - big_L/2 + ov)
        translate([ elbow_outer_r - big_L/2 + ov,
                    big_Y/2,
                    0 ])
            cube([big_L, big_Y, big_Z], center=true);

        // 3) Smaller rectangular tongue at the +Y end, extending toward +Y
        // Attach: tongue's -Y face slightly overlaps elbow's max Y (elbow_outer_r)
        // Tongue center y = (attach_y + tongue_L/2 - ov)
        translate([ tongue_Y/2,
                    elbow_outer_r + tongue_L/2 - ov,
                    0 ])
            cube([tongue_Y, tongue_L, tongue_Z], center=true);

        // 4) Obround end-cap integrated near the smaller end (near tongue tip)
        // Place so its -Y end overlaps tongue tip region.
        // Tongue +Y face is at y = elbow_outer_r + tongue_L - ov
        cap_center_y = (elbow_outer_r + tongue_L - ov) - cap_L/2 + ov;
        translate([ 0,
                    cap_center_y,
                    0 ])
            linear_extrude(height=cap_Z, center=true)
                obround_2d(cap_L, cap_W);

        // 5) Two small rectangular lugs/steps on top side near the tip
        // Put them on top of the tongue (z = tongue_Z/2) with slight overlap.
        tongue_top_z = tongue_Z/2;

        // Lug 1 (closest to tip): overlap into tongue by ov in Z and Y
        lug1_center_y = (elbow_outer_r + tongue_L - ov) - lug1_L/2 + ov;
        translate([ 0,
                    lug1_center_y,
                    tongue_top_z + lug1_H/2 - ov ])
            cube([lug1_W, lug1_L, lug1_H], center=true);

        // Lug 2 (behind lug 1): positioned just behind with overlap
        lug2_center_y = lug1_center_y - (lug1_L/2 + lug2_L/2) + ov;
        translate([ 0,
                    lug2_center_y,
                    tongue_top_z + lug2_H/2 - ov ])
            cube([lug2_W, lug2_L, lug2_H], center=true);
    }
}

// ----------------- Final (fit/center to bbox) -----------------
module complete_model() {
    // Compute conservative extents from construction (before centering):
    elbow_outer_r = R_center + tube_D/2;

    // X extents:
    // min from big block: (elbow_outer_r - big_L + 2*ov) approximately
    // max from elbow: elbow_outer_r
    x_min = elbow_outer_r - big_L + 2*ov;
    x_max = elbow_outer_r;

    // Y extents:
    // min from elbow: 0
    // max from tongue/cap: elbow_outer_r + tongue_L (cap doesn't exceed tongue tip in Y)
    y_min = 0;
    y_max = elbow_outer_r + tongue_L;

    // Center into bbox in X/Y, keep Z centered at 0
    x_mid = (x_min + x_max)/2;
    y_mid = (y_min + y_max)/2;

    translate([bbox_X/2 - x_mid, bbox_Y/2 - y_mid, 0])
        model_solid();
}

complete_model();

// Render-safe OpenSCAD model: tapered plate with concave semicircular cutout (horns),
// four through-slots (two parallel pairs), stencil cut-through text,
// and two underside mounting feet/tabs. One connected solid.

$fn = 64;

// -------------------- Parameters --------------------
plate_L = 0.08;
plate_W_wide = 0.08;
plate_W_narrow = 0.055;
plate_thk = 0.006;

cutout_r = 0.028;
cutout_center_offset_from_end = 0.0;

// Slots: two parallel pairs near cutout end (all horizontal in plan view)
slot_L = 0.018;
slot_W = 0.003;
slot_pair_spacing = 0.008;              // spacing within each side pair (in Y)
slot_pair_offset_from_cutout_end = 0.016;
slot_pair_lateral_offset = 0.018;       // center of each side pair from centerline (in Y)

text_height = 0.008;                    // font size
text_stroke = 0.0012;                   // stencil bridge thickness
text_offset_from_cutout_end = 0.034;    // move text away from cutout
text_depth = 0.02;                      // ensure full cut-through (>= plate_thk)

foot_L = 0.012;
foot_W = 0.006;
foot_drop = 0.004;
foot_offset_from_cutout_end = 0.06;
foot_lateral_offset = 0.02;

eps = 0.001;

// -------------------- Helpers --------------------
module tapered_plate_2d() {
    polygon(points=[
        [-plate_L/2, -plate_W_wide/2],
        [-plate_L/2,  plate_W_wide/2],
        [ plate_L/2,  plate_W_narrow/2],
        [ plate_L/2, -plate_W_narrow/2]
    ]);
}

module tapered_plate_body() {
    linear_extrude(height=plate_thk, center=false)
        tapered_plate_2d();
}

// Concave semicircular cutout along the LEFT end (x = -plate_L/2).
module concave_semicircular_end_cutout() {
    translate([-plate_L/2 + cutout_center_offset_from_end, 0, plate_thk/2])
        cylinder(r=cutout_r, h=plate_thk + 2*eps, center=true);
}

// Rounded slot (capsule) via hull of two circles, then extrude.
module rounded_slot_3d(len, wid) {
    linear_extrude(height=plate_thk + 2*eps, center=true)
        hull() {
            translate([-(len/2 - wid/2), 0]) circle(r=wid/2, $fn=32);
            translate([ (len/2 - wid/2), 0]) circle(r=wid/2, $fn=32);
        }
}

// Four slots: two parallel pairs near cutout end (2 on +Y side, 2 on -Y side).
module all_through_slots() {
    x_center = -plate_L/2 + slot_pair_offset_from_cutout_end + slot_L/2;

    for (dy = [-(slot_pair_spacing/2), +(slot_pair_spacing/2)]) {
        translate([x_center,  slot_pair_lateral_offset + dy, plate_thk/2])
            rounded_slot_3d(slot_L, slot_W);
        translate([x_center, -slot_pair_lateral_offset + dy, plate_thk/2])
            rounded_slot_3d(slot_L, slot_W);
    }
}

// Stencil cut-through text: "EEZYbot ARM MK2"
// Fixes:
// - Ensure full string appears (no clipping) by scaling to fit available length.
// - Ensure readable from FRONT (not mirrored) by keeping normal orientation.
// - Keep stencil bridges but avoid over-subtracting.
module stencil_text_cutout() {
    x_text = -plate_L/2 + text_offset_from_cutout_end;
    zc = plate_thk/2;

    // Available length from x_text to near right end, keep a margin.
    avail_len = (plate_L/2 - x_text) - 0.004;

    module raw_text_2d() {
        text("EEZYbot ARM MK2",
             size=text_height,
             halign="left",
             valign="center",
             font="Liberation Sans:style=Bold");
    }

    // Measure and scale text to fit in X so it doesn't get clipped by the plate taper.
    module fitted_text_2d() {
        // Use textmetrics via text() bounding box approximation using offset+projection:
        // OpenSCAD lacks direct text bbox; use a conservative scale based on heuristic length.
        // Heuristic: average glyph width ~0.62*size; length ~ n*0.62*size.
        n = 14; // "EEZYbot ARM MK2" length incl spaces (approx)
        est_len = n * 0.62 * text_height;
        sx = min(1, avail_len / est_len);
        scale([sx, 1]) raw_text_2d();
    }

    module text_solid() {
        translate([x_text, 0, zc])
            linear_extrude(height=plate_thk + 2*eps, center=true)
                fitted_text_2d();
    }

    // Stencil bridges: thin vertical bars that REMOVE from the text-solid,
    // leaving small connections in the final cutout.
    module bridge_bars() {
        // Place several bars across the text span.
        // Use same heuristic span as above, but clamp to avail_len.
        n = 14;
        est_len = n * 0.62 * text_height;
        span = min(avail_len, est_len);
        bar_h = text_height * 1.8;

        for (i = [1:6]) {
            bx = x_text + i * span / 7;
            translate([bx, 0, zc])
                cube([text_stroke, bar_h, plate_thk + 4*eps], center=true);
        }
    }

    difference() {
        text_solid();
        bridge_bars();
    }
}

// Two underside mounting feet/tabs, connected to underside of plate.
// Ensure they overlap into the plate (z overlap) so union is one connected solid.
module underside_mounting_feet_tabs_x2() {
    x_foot_center = -plate_L/2 + foot_offset_from_cutout_end + foot_L/2;

    // Plate spans z=[0, plate_thk]. Feet should extend below 0 and overlap slightly into plate.
    z_foot_center = -foot_drop/2 + eps; // top of foot at z=eps (overlaps into plate)

    translate([x_foot_center,  foot_lateral_offset, z_foot_center])
        cube([foot_L, foot_W, foot_drop], center=true);

    translate([x_foot_center, -foot_lateral_offset, z_foot_center])
        cube([foot_L, foot_W, foot_drop], center=true);
}

// Main plate with cutouts
module plate_with_all_cutouts() {
    difference() {
        tapered_plate_body();
        concave_semicircular_end_cutout();
        all_through_slots();
        stencil_text_cutout();
    }
}

// Final connected model
union() {
    plate_with_all_cutouts();
    underside_mounting_feet_tabs_x2();
}

// Thin elongated tag/plate with chamfered ends, circular boss at one end,
// diamond-shaped through-hole, raised "ASTRID" text, and a small geometric logo.
// Units: mm

$fn = 128;

// --- Parameters (kept tiny as provided) ---
L = 0.1;      // overall length
W = 0.02;     // overall width
T = 0.01;     // plate thickness

chamfer_L = 0.006;

// Boss (circular pad) at one end
