module face_pattern_with_extras() {
    // Adds a few edge-near extras (still connected via overlap)
    union() {
        face_pattern();
        translate([ 0.0,  0.040, 0]) octa_boss(extra_d, extra_h);
        translate([ 0.0, -0.040, 0]) octa_boss(extra_d, extra_h);
        translate([ 0.040, 0.0, 0]) octa_boss(extra_d, extra_h);
        translate([-0.040, 0.0, 0]) octa_boss(extra_d, extra_h);
