    cube([block, block, block], center=true);

    // Six faces (slight deterministic variation per face)
    on_face_zp( 0.0);
    on_face_zn( j);
    on_face_xp(-j);
    on_face_xn( 0.5*j);
    on_face_yp(-0.5*j);
