z_fl1   = z0 + flange_t;
z_bd0   = z_fl1;
z_bd1   = z0 + total_H;

// --- Helpers ---
module hex2d(r){
    polygon(points=[
        [ r, 0],
        [ r/2,  r*sqrt(3)/2],
        [-r/2,  r*sqrt(3)/2],
        [-r, 0],
        [-r/2, -r*sqrt(3)/2],
        [ r/2, -r*sqrt(3)/2]
    ]);
}

module diamond2d(w,h){
    polygon(points=[
        [ w/2, 0],
        [ 0,   h/2],
        [-w/2, 0],
        [ 0,  -h/2]
