      [bbox_X/2 - outline_margin - step_inset_2, -bbox_Y/2 + outline_margin + bbox_Y*0.28],
      [bbox_X/2 - outline_margin - step_inset_2, bbox_Y/2 - outline_margin - bbox_Y*0.22],
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin - bbox_Y*0.22],
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin - step_inset_1],
      [bbox_X/2 - outline_margin - step_inset_1, bbox_Y/2 - outline_margin],
      [-bbox_X/2 + outline_margin + step_inset_2, bbox_Y/2 - outline_margin],
      [-bbox_X/2 + outline_margin, bbox_Y/2 - outline_margin - step_inset_2],
      [-bbox_X/2 + outline_margin, bbox_Y/2 - outline_margin - bbox_Y*0.35],
      [-bbox_X/2 + outline_margin + step_inset_1, bbox_Y/2 - outline_margin - bbox_Y*0.35],
      [-bbox_X/2 + outline_margin + step_inset_1, -bbox_Y/2 + outline_margin + bbox_Y*0.18],
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin + bbox_Y*0.18],
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin + corner_ch]
    ]);
  }
}

module stepped_outline_segments() {
  linear_extrude(height=T, center=true) {
    polygon(points=[
      [bbox_X/2 - outline_margin - step_inset_1, -bbox_Y/2 + outline_margin],
      [bbox_X/2 - outline_margin, -bbox_Y/2 + outline_margin + step_inset_1],
      [bbox_X/2 - outline_margin, -bbox_Y/2 + outline_margin + bbox_Y*0.28],
      [bbox_X/2 - outline_margin - step_inset_2, -bbox_Y/2 + outline_margin + bbox_Y*0.28],
      [bbox_X/2 - outline_margin - step_inset_2, bbox_Y/2 - outline_margin - bbox_Y*0.22],
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin - bbox_Y*0.22],
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin - step_inset_1],
      [bbox_X/2 - outline_margin - step_inset_1, bbox_Y/2 - outline_margin],
      [-bbox_X/2 + outline_margin + step_inset_2, bbox_Y/2 - outline_margin],
      [-bbox_X/2 + outline_margin, bbox_Y/2 - outline_margin - step_inset_2],
      [-bbox_X/2 + outline_margin, bbox_Y/2 - outline_margin - bbox_Y*0.35],
      [-bbox_X/2 + outline_margin + step_inset_1, bbox_Y/2 - outline_margin - bbox_Y*0.35],
      [-bbox_X/2 + outline_margin + step_inset_1, -bbox_Y/2 + outline_margin + bbox_Y*0.18],
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin + bbox_Y*0.18],
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin]
    ]);
  }
}

module corner_rounds_or_chamfers() {
  linear_extrude(height=T, center=true) {
    polygon(points=[
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin],
      [-bbox_X/2 + outline_margin + corner_ch, -bbox_Y/2 + outline_margin],
      [-bbox_X/2 + outline_margin, -bbox_Y/2 + outline_margin + corner_ch]
    ]);
  }
}

module mixed_corner_treatments_per_corner() {
  linear_extrude(height=T, center=true) {
    polygon(points=[
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin],
      [bbox_X/2 - outline_margin - corner_ch, bbox_Y/2 - outline_margin],
      [bbox_X/2 - outline_margin, bbox_Y/2 - outline_margin - corner_ch]
    ]);
  }
}

module through_hole(position_x, position_y) {
  rotate([0, 0, hole_rot_deg]) {
    translate([position_x, position_y, 0]) {
      cube([hole_sq, hole_sq, T + hole_clear_z], center=true);
    }
  }
}

module small_edge_break_chamfer() {
  sphere(r=edge_break_r, center=true);
}

module hole_edge_chamfer_or_countersink_suggestion() {
  cylinder(h=T, r1=hole_sq/2, r2=0, center=true);
}

// Operations
module plate_minus_corner_chamfers() {
  difference() {
    plate_main_profile();
    corner_rounds_or_chamfers();
    mixed_corner_treatments_per_corner();
  }
}

module plate_with_edge_break() {
  minkowski() {
    plate_minus_corner_chamfers();
    small_edge_break_chamfer();
  }
}

module plate_with_steps_and_edge_break() {
  union() {
    plate_with_edge_break();
    stepped_outline_segments();
  }
}

module plate_with_holes() {
  difference() {
    plate_with_steps_and_edge_break();
    through_hole(-hole_group_dx/2 - hole_pitch_x/2 + hole_center_offset_x, -hole_group_dy/2 - hole_pitch_y + hole_center_offset_y);
    through_hole(-hole_group_dx/2 + hole_center_offset_x, -hole_group_dy/2 + hole_center_offset_y);
    through_hole(-hole_group_dx/2 + hole_pitch_x/2 + hole_center_offset_x, -hole_group_dy/2 + hole_pitch_y + hole_center_offset_y);
    through_hole(hole_group_dx/2 - hole_pitch_x/2 + hole_center_offset_x, hole_group_dy/2 - hole_pitch_y + hole_center_offset_y);
    through_hole(hole_group_dx/2 + hole_center_offset_x, hole_group_dy/2 + hole_center_offset_y);
    through_hole(hole_group_dx/2 + hole_pitch_x/2 + hole_center_offset_x, hole_group_dy/2 + hole_pitch_y + hole_center_offset_y);
  }
}

module final_model() {
  union() {
    plate_with_holes();
    hole_edge_chamfer_or_countersink_suggestion();
  }
}

// Final Output
final_model();

// C-shaped circular ring segment (planar clip) with rounded ends and one bulbous end
// All geometry is one connected solid; no extra floating parts.

$fn = 128;

// Parameters (meters in original; keep as-is)
thickness_z     = 0.0001;
outer_radius    = 0.015;
band_width      = 0.004;
gap_angle_deg   = 50;

end_round_radius = 0.002;
bulb_radius      = 0.0025;
bulb_offset      = 0.001;

overlap = 0.0005;

// Derived
inner_radius = outer_radius - band_width;
mid_radius   = outer_radius - band_width/2;

// 2D ring sector (C-shape) made by subtracting inner circle and a gap wedge
module c_ring_2d() {
    difference() {
        // annulus
        difference() {
            circle(r = outer_radius);
            circle(r = inner_radius);
        }

        // gap wedge centered on +X axis, symmetric about X
        rotate(gap_angle_deg/2)
            polygon(points = [
                [0, 0],
                [ (outer_radius + 2*overlap), 0],
                [ (outer_radius + 2*overlap)*cos(180-gap_angle_deg), (outer_radius + 2*overlap)*sin(180-gap_angle_deg) ]
            ]);
        rotate(-gap_angle_deg/2)
            polygon(points = [
                [0, 0],
                [ (outer_radius + 2*overlap), 0],
                [ (outer_radius + 2*overlap)*cos(180-gap_angle_deg), -(outer_radius + 2*overlap)*sin(180-gap_angle_deg) ]
            ]);

        // simpler robust wedge cut (covers both polygons above)
        // (kept as polygons to avoid arbitrary translations)
    }
}

// Rounded end caps + bulbous feature as 2D additions (then extruded)
module end_features_2d() {
    // Endpoints of the ring centerline at the gap edges
    // Gap is centered on +X axis; ends at angles +/- gap_angle/2
    a = gap_angle_deg/2;

    p_pos = [ mid_radius*cos(a),  mid_radius*sin(a) ];
    p_neg = [ mid_radius*cos(a), -mid_radius*sin(a) ];

    // Rounded ends: add circles at both ends (fillet-like)
    circle(r = end_round_radius, center = true, $fn = 64)
        translate(p_pos) children();
    circle(r = end_round_radius, center = true, $fn = 64)
        translate(p_neg) children();

    // Bulbous feature on the +angle end (slightly outward along radial direction)
    p_bulb = [ (mid_radius + bulb_offset)*cos(a), (mid_radius + bulb_offset)*sin(a) ];
    circle(r = bulb_radius, center = true, $fn = 64)
        translate(p_bulb) children();
}

// Helper to place a circle at a point (OpenSCAD doesn't allow circle+translate in one line with children easily)
module circle_at(pt, r) {
    translate(pt) circle(r = r);
}

module clip_2d() {
    a = gap_angle_deg/2;

    p_pos  = [ mid_radius*cos(a),  mid_radius*sin(a) ];
    p_neg  = [ mid_radius*cos(a), -mid_radius*sin(a) ];
    p_bulb = [ (mid_radius + bulb_offset)*cos(a), (mid_radius + bulb_offset)*sin(a) ];

    union() {
        // Main C-ring band
        difference() {
            difference() {
                circle(r = outer_radius);
                circle(r = inner_radius);
            }
            // Gap wedge: a large triangle sector centered on +X
            polygon(points = [
                [0, 0],
                [ (outer_radius + 2*overlap)*cos( a),  (outer_radius + 2*overlap)*sin( a)],
                [ (outer_radius + 2*overlap)*cos(-a),  (outer_radius + 2*overlap)*sin(-a)]
            ]);
        }

        // Rounded ends (2D)
        hull() {
            circle_at(p_pos, end_round_radius);
            circle_at(p_neg, end_round_radius);
        }

        // Bulbous end (2D) blended into the +end
        hull() {
            circle_at(p_pos, end_round_radius);
            circle_at(p_bulb, bulb_radius);
        }
    }
}

// Final 3D: planar extrusion with uniform thickness
linear_extrude(height = thickness_z, center = true, convexity = 10)
    clip_2d();

// Parameters (meters; OpenSCAD default units are arbitrary)
bbox_X = 0.02; //[0.01:0.04:0.001]
bbox_Y = 0.01; //[0.005:0.02:0.001]
bbox_Z = 0.02; //[0.01:0.04:0.001]
shaft_d = 0.01; //[0.005:0.02:0.0005]
shaft_L = 0.02; //[0.01:0.04:0.001]
collar_AF = 0.01; //[0.005:0.02:0.0005]
collar_thk = 0.006; //[0.003:0.012:0.0005]
chamfer = 0.0005; //[0.0002:0.001:0.0001]
overlap = 0.0005; //[0.0002:0.001:0.0001]
engrave_depth = 0.0003; //[0.0001:0.0008:0.0001]
engrave_w = 0.0006; //[0.0003:0.0012:0.0001]
engrave_L = 0.004; //[0.002:0.008:0.0005]

$fn = 96;

// Derived
shaft_r = shaft_d/2;
hex_R   = collar_AF / sqrt(3);          // circumradius for across-flats = collar_AF
total_L = shaft_L + collar_thk;         // overall length

// Base solids
module shaft_cylinder() {
  // Clean cylinder spanning full length; collar will be unioned around midsection
  cylinder(h=total_L, r=shaft_r, center=true);
}

module hex_collar() {
  // True 6-flat hex prism (wrenching surface)
  cylinder(h=collar_thk, r=hex_R, $fn=6, center=true);
}

// Engraving cuts (kept shallow; placed on opposite flats)
module engraving_mark_cut_pos() {
  translate([0, collar_AF/2 - engrave_depth/2, 0])
    cube([collar_AF*1.2, engrave_depth, engrave_L], center=true);
}

module engraving_mark_cut_neg() {
  translate([0, -(collar_AF/2 - engrave_depth/2), 0])
    cube([collar_AF*1.2, engrave_depth, engrave_L], center=true);
}

// Final
difference() {
  union() {
    shaft_cylinder();
    hex_collar();
  }
  engraving_mark_cut_pos();
  engraving_mark_cut_neg();
}
